INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C1','soc',4,1,'u3',1,'경제활동과 선택의 문제 — 경제활동 = 생활에 필요한 것을 만들고 사고팔거나 사용하는 모든 활동 · 선택 = 무엇을 고를지 고민하는 것 · 자원의 희소성 = 원하는 것에 비해 돈·시간·물건 같은 자원이 부족한 상태 · 선택의 문제가 일어나는 까닭 = 자원의 희소성 · 하나를 고르면 다른 하나는 포기 · 희소성은 자원의 양뿐 아니라 원하는 정도에 따라 달라짐(쥐치·주말 숙소 요금) · 넉넉한 것(공기)에는 선택의 문제가 없음',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C2','soc',4,1,'u3',2,'합리적 선택이 필요한 까닭 — 여러 가지를 따져 보지 않고 고르면(날씨·가격 비교·품질) 후회 · 합리적 선택 = 적은 비용과 노력으로 가장 큰 만족감을 얻는 선택 · 고쳐 쓰기·새로 사기·중고 사기를 비용과 만족으로 견줌 · 자원은 한정되어 아무렇게나 고르면 낭비와 후회 · 사람마다 중요하게 여기는 것이 달라 선택이 다양 · 퍼스널 쇼퍼 = 취향을 파악해 합리적 선택을 도움',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C3','soc',4,1,'u3',3,'합리적 선택의 방법 — 정보 얻기: 써 본 주변 사람(생생한 정보)·인터넷과 광고(종류와 가격 비교)·가게 직접 방문(직접 보고 물어봄) · 여러 방법을 함께 쓰면 더 정확 · 정보를 쓸 때 출처가 믿을 만한지·정확한지 확인 · 근거 없이 부풀린 과장 광고 조심 · 차례: 필요한지 생각 → 정보 찾기 → 가격·품질 비교 → 선택',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C4','soc',4,1,'u3',4,'일상생활에서 합리적 선택 실천 — 사기 전 확인: 꼭 필요한지·이미 있거나 빌려 쓸 수 있는지·가진 돈으로 살 수 있는지 · 선택 기준: 가격(살 수 있는 돈·적당한 값)·품질(기능·오래 씀·안전)·디자인(모양·색)·서비스(무상 수리·배송)·친환경(소재·해롭지 않음) · 기준에 따라 가장 좋은 것이 달라짐 · 우선순위가 사람마다 달라 선택이 달라도 둘 다 합리적일 수 있음 · 착한 소비 = 사람·동물·환경에 도움이 되는 상품 고르기',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C5','soc',4,1,'u3',5,'선택 기준에 따라 점수 매겨 선택하기 — 기준마다 점수를 매기고 합계를 견줘 합계가 가장 큰 것을 고름 · 중요한 기준일수록 줄 수 있는 최대 점수를 크게(우선순위를 담음) · 점수는 내가 판단해 매김(정해진 정답 없음) · 같은 표를 보고도 선택이 다를 수 있음 · 여러 기준과 정보를 살피면 나에게 맞는 선택이 또렷해짐',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C6','soc',4,1,'u3',6,'주제① 생각 펼치기 — 희소성 → 선택의 문제 → 기준과 정보 → 합리적 선택 → 착한 소비로 이어짐 · 학급 시장 놀이 = 하나뿐인 물건은 희소성을, 쓸모는 기준을 살려 값과 홍보 문구를 정함 · 새 상품 제안 = 생활 속 선택의 문제나 불편을 바탕으로',ARRAY['[4사07-01] 자원의 희소성으로 경제활동에서 선택의 문제가 생김을 알고 합리적으로 선택하는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C7','soc',4,1,'u3',7,'생산과 소비 — 생산 = 생활에 필요한 물건을 만들거나 생활을 편리하고 즐겁게 해 주는 것(진료·머리 손질·공연 같은 서비스도 생산) · 소비 = 생산한 것을 사거나 이용하는 것 · 같은 가게에서 파는 쪽은 생산, 사는 쪽은 소비 · 시장 = 한 곳에서 생산과 소비를 함께 볼 수 있음 · 생산과 소비는 짝을 이룸',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C8','soc',4,1,'u3',8,'우리 주변의 생산·소비 활동 — 생산 활동 세 종류: 자연에서 얻는 활동(벼농사·고기잡이·버섯 따기)·필요한 것을 만드는 활동(빵 만들기·건물 짓기·옷 만들기)·편리하고 즐겁게 해 주는 활동(진료·공연·배달 = 서비스) · 소비 활동(채소 사기·버스 타기) · 내 소비는 누군가의 생산과 이어짐',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C9','soc',4,1,'u3',9,'지역 간 교류가 필요한 까닭 — 지역마다 자연환경(땅·날씨·바다)과 생산 기술이 달라 잘 나는 것이 다름 · 한 지역이 모든 것을 만들 수 없음 · 교류 = 지역끼리 서로 필요한 것을 주고받는 것 · 김밥 한 줄에 여러 지역의 재료 · 교류하는 모든 지역이 이로움 · 상호 의존 = 서로 의지하며 함께 살아감 → 함께 발전',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C10','soc',4,1,'u3',10,'지역 간 다양한 교류 — 물자 교류 = 생산물·상품을 주고받음 · 기술 교류 = 기술·정보·사람(인력)을 주고받음 · 문화 교류 = 공연·축제·전통·예술을 함께 나눔 · 봉사 활동으로 도움을 주고받는 것도 교류 · 지역들은 다양한 교류로 밀접하게 이어져 혼자서만 살아갈 수 없음',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C11','soc',4,1,'u3',11,'우리 지역 교류 지도 만들기 — 먼저 교류 사례 조사(지역 누리집·주요 생산물) · 우리 지역을 가운데, 교류하는 지역을 둘레에 · 들어오는 교류는 노란색, 나가는 교류는 파란색으로 방향 표시 · 완성한 지도로 교류 관계·주요 생산물·상호 의존을 한눈에 · 만드는 사람마다 조금씩 다를 수 있음',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u3-C12','soc',4,1,'u3',12,'주제② 생각 펼치기 — 생산과 소비가 생활을 이룸 → 지역마다 나는 것이 달라 교류 → 상호 의존하며 함께 발전 · 강점은 주고 부족함은 받으면 두 지역 모두 만족 · 자매결연 = 우리 강점이 필요하거나 부족함을 채워 줄 지역과 맺음 · 교류가 없으면 우리 지역에서 나는 것만 써야 함',ARRAY['[4사07-02] 생산·소비 활동과 지역 간 교류를 조사해 지역들이 서로 의존하며 발전함을 안다(차시 머리 표기 · 문구 초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X01','soc',4,'u3',ARRAY['SO4-1-u3-C1']::text[],'경제활동을 돈을 버는 어른의 일로만 여겨, 물건을 사고 쓰는 일도 경제활동이라는 것을 놓친다','만들기 · 사고팔기 · 사용하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X02','soc',4,'u3',ARRAY['SO4-1-u3-C1']::text[],'희소성을 물건의 양이 적은 것으로만 여겨, 원하는 정도에 비해 부족한 상태이며 원하는 정도에 따라 달라진다는 것을 놓친다','원하는 것에 비해 부족') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X03','soc',4,'u3',ARRAY['SO4-1-u3-C1','SO4-1-u3-C6']::text[],'선택의 문제가 일어나는 까닭을 물건이 많아서·고르기 귀찮아서 같은 데서 찾고, 자원이 부족하다는 것을 놓친다','자원이 부족하니까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X04','soc',4,'u3',ARRAY['SO4-1-u3-C1']::text[],'원하는 것을 모두 가질 수 있다고 여겨, 하나를 고르면 다른 하나는 포기해야 한다는 것을 놓친다','고르면 하나는 포기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X05','soc',4,'u3',ARRAY['SO4-1-u3-C1']::text[],'공기처럼 넉넉해 부족하지 않은 것에도 선택의 문제가 일어난다고 여긴다','넉넉하면 고를 필요 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X06','soc',4,'u3',ARRAY['SO4-1-u3-C2','SO4-1-u3-C5']::text[],'합리적 선택을 가장 싼 것·가장 비싼 것·새것을 고르는 일로 여긴다','비용은 적게 · 만족은 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X07','soc',4,'u3',ARRAY['SO4-1-u3-C2']::text[],'디자인만·가격만 보는 것처럼 여러 가지를 따져 보지 않고 골라도 된다고 여겨 후회하는 까닭을 놓친다','여러 가지를 따져 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X08','soc',4,'u3',ARRAY['SO4-1-u3-C2','SO4-1-u3-C4','SO4-1-u3-C5']::text[],'나와 친구의 선택이 다르면 둘 가운데 하나는 잘못 고른 것이라고 여긴다','우선순위가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X09','soc',4,'u3',ARRAY['SO4-1-u3-C3']::text[],'정보를 얻는 방법과 그 좋은 점을 바꾸어 안다(써 본 사람에게 묻기를 가격 비교라고 하는 등)','생생 · 비교 · 직접 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X10','soc',4,'u3',ARRAY['SO4-1-u3-C3']::text[],'광고나 인터넷 정보를 출처와 정확성을 확인하지 않고 그대로 믿는다','출처 · 정확성 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X11','soc',4,'u3',ARRAY['SO4-1-u3-C3']::text[],'정보를 찾지 않고 고르거나 합리적 선택의 차례를 바꾼다','필요 → 정보 → 비교 → 선택') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X12','soc',4,'u3',ARRAY['SO4-1-u3-C3']::text[],'정보를 얻는 방법은 한 가지만 쓰면 충분하다고 여긴다','여러 방법을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X13','soc',4,'u3',ARRAY['SO4-1-u3-C4']::text[],'사기 전에 꼭 필요한지·이미 있는지·가진 돈으로 살 수 있는지 확인하지 않는다','필요 · 있음 · 돈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X14','soc',4,'u3',ARRAY['SO4-1-u3-C4']::text[],'선택 기준과 그 기준에서 살필 점을 바꾸어 안다(무상 수리를 품질로 보는 등)','가격·품질·디자인·서비스·친환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X15','soc',4,'u3',ARRAY['SO4-1-u3-C4','SO4-1-u3-C5']::text[],'한 가지 기준만 보면 된다고 여기거나, 어느 기준으로 보아도 가장 좋은 것이 같다고 여긴다','기준마다 가장 좋은 것이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X16','soc',4,'u3',ARRAY['SO4-1-u3-C4','SO4-1-u3-C6']::text[],'착한 소비를 가장 싼 것 사기·나에게만 좋은 선택으로 여긴다','사람 · 동물 · 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X17','soc',4,'u3',ARRAY['SO4-1-u3-C5']::text[],'점수표에서 합계가 아니라 한 칸의 점수나 가격만 보고 고른다','합계가 가장 큰 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X18','soc',4,'u3',ARRAY['SO4-1-u3-C5']::text[],'중요한 기준일수록 점수를 작게 주거나 모든 기준에 똑같이 주어 우선순위를 담지 않는다','중요할수록 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X19','soc',4,'u3',ARRAY['SO4-1-u3-C5']::text[],'점수표의 점수에 누구에게나 같은 정답이 있다고 여긴다','점수는 내가 판단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X20','soc',4,'u3',ARRAY['SO4-1-u3-C6']::text[],'희소성·선택의 문제·합리적 선택이 이어지는 차례를 바꾸어 안다','희소성 → 선택의 문제 → 합리적 선택') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X21','soc',4,'u3',ARRAY['SO4-1-u3-C6']::text[],'물건의 값과 홍보 문구, 새 상품 제안을 배운 것(희소성·쓸모·불편)과 관계없이 마음대로 정한다','희소성과 쓸모를 살려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X22','soc',4,'u3',ARRAY['SO4-1-u3-C7','SO4-1-u3-C8']::text[],'물건을 만드는 것만 생산이라고 여겨 진료·공연·배달 같은 서비스를 놓친다','해 주는 일도 생산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X23','soc',4,'u3',ARRAY['SO4-1-u3-C7','SO4-1-u3-C8']::text[],'생산과 소비를 바꾸어 안다(사는 일을 생산이라고 하는 등)','만들기·해 주기 / 사기·이용하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X24','soc',4,'u3',ARRAY['SO4-1-u3-C7','SO4-1-u3-C8']::text[],'한 가게에서는 생산이나 소비 하나만 일어난다고 여기거나, 생산과 소비가 서로 관계없는 활동이라고 여긴다','짝을 이뤄요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X25','soc',4,'u3',ARRAY['SO4-1-u3-C8']::text[],'생산 활동의 세 종류를 바꾸어 나눈다(버섯 따기를 만드는 활동이라고 하는 등)','자연에서 · 만들기 · 해 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X26','soc',4,'u3',ARRAY['SO4-1-u3-C9']::text[],'지역마다 나는 것이 다른 까닭을 사람 수나 지역 이름에서 찾고 자연환경과 생산 기술을 놓친다','자연환경 · 생산 기술') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X27','soc',4,'u3',ARRAY['SO4-1-u3-C9','SO4-1-u3-C12']::text[],'한 지역이 필요한 것을 모두 만들 수 있다고 여겨 교류가 필요 없다고 본다','다 만들 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X28','soc',4,'u3',ARRAY['SO4-1-u3-C9','SO4-1-u3-C12']::text[],'교류하면 주는 지역만 손해를 본다고, 곧 한쪽만 이롭다고 여긴다','모두 이로워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X29','soc',4,'u3',ARRAY['SO4-1-u3-C10']::text[],'교류를 물건 주고받기로만 여겨 기술·문화·봉사로 주고받는 교류를 놓친다','물자 · 기술 · 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X30','soc',4,'u3',ARRAY['SO4-1-u3-C10','SO4-1-u3-C11']::text[],'물자·기술·문화 교류를 서로 바꾸어 나눈다','생산물 · 기술 · 공연') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X31','soc',4,'u3',ARRAY['SO4-1-u3-C11']::text[],'교류 지도를 조사 없이 만들거나 우리 지역이 아닌 곳을 가운데에 둔다','조사 → 우리 지역 가운데') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X32','soc',4,'u3',ARRAY['SO4-1-u3-C11']::text[],'교류 지도에서 들어오는 교류와 나가는 교류의 방향을 바꾸어 읽는다','노랑 들어옴 · 파랑 나감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X33','soc',4,'u3',ARRAY['SO4-1-u3-C9','SO4-1-u3-C12']::text[],'상호 의존을 혼자서 살아가기나 한쪽만 다른 쪽에 기대기로 잘못 안다','서로 의지하며 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u3-X34','soc',4,'u3',ARRAY['SO4-1-u3-C12']::text[],'교류하거나 자매결연을 맺을 지역을 우리 지역의 강점·부족함과 관계없이 고르거나, 교류가 없어도 생활이 그대로라고 여긴다','강점은 주고 부족함은 받고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#1','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',1,'mc','auto','생활에 필요한 것을 만들고, 사고팔거나 사용하는 모든 활동을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"mc","stem":"생활에 필요한 것을 만들고, 사고팔거나 사용하는 모든 활동을 무엇이라고 하나요?","options":[{"t":"경제활동","correct":true},{"t":"봉사 활동","mis":"SO4-1-u3-X01"},{"t":"여가 활동","mis":"SO4-1-u3-X01"},{"t":"체육 활동","mis":"SO4-1-u3-X01"}],"explanation":["만들고 사고팔아요.","쓰는 일도 들어가요.","경제활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#2','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',1,'sa','auto','원하는 것에 비해 자원이 부족한 상태를 자원의 ○○○이라고 해요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"sa","stem":"원하는 것에 비해 자원이 부족한 상태를 자원의 ○○○이라고 해요. 세 글자로 쓰세요.","answer":["희소성"],"explanation":["원하는 것이 많아요.","자원은 부족해요.","희소성이에요."],"mis":"SO4-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#3','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',1,'ox','auto','가게에서 물건을 사는 일도 경제활동이에요.',ARRAY['SO4-1-u3-X01']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"ox","stem":"가게에서 물건을 사는 일도 경제활동이에요.","answer":"O","reason_options":[{"t":"만들고 사고팔고 쓰는 모든 활동이 경제활동이기 때문에","correct":true},{"t":"돈을 버는 일만 경제활동이기 때문에","mis":"SO4-1-u3-X01"}],"mis":"SO4-1-u3-X01","explanation":["사는 일도 들어가요.","사고팔기예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#4','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',1,'mc','auto','경제활동에서 선택의 문제가 일어나는 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X03']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"mc","stem":"경제활동에서 선택의 문제가 일어나는 까닭은 무엇인가요?","options":[{"t":"돈·시간 같은 자원이 부족하기 때문이에요","correct":true},{"t":"물건이 너무 많기 때문이에요","mis":"SO4-1-u3-X03"},{"t":"돈이 넉넉하기 때문이에요","mis":"SO4-1-u3-X03"},{"t":"고를 것이 하나도 없기 때문이에요","mis":"SO4-1-u3-X03"}],"explanation":["다 가질 수 있나요?","자원이 모자라요.","그래서 골라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#5','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',2,'mc','auto','민재가 축구공을 먼저 샀어요. 남은 돈으로 만화책을 살 수 있나요?',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"mc","stem":"민재가 축구공을 먼저 샀어요. 남은 돈으로 만화책을 살 수 있나요?","options":[{"t":"살 수 없어요 — 남은 1,000원으로는 모자라요","correct":true},{"t":"살 수 있어요 — 용돈은 늘 넉넉해요","mis":"SO4-1-u3-X04"},{"t":"살 수 있어요 — 하나 사면 하나는 공짜예요","mis":"SO4-1-u3-X04"},{"t":"두 권도 살 수 있어요","mis":"SO4-1-u3-X04"}],"explanation":["5,000원에서 4,000원을 썼어요.","1,000원이 남아요.","만화책은 포기해요."],"asset":{"type":"passage","lines":["민재의 용돈 — 5,000원","만화책 — 3,000원","축구공 — 4,000원","색연필 세트 — 2,500원","젤리 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"민재가 갖고 싶은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#6','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',2,'mc','auto','같은 방인데 주말 요금이 더 높은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X02']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"mc","stem":"같은 방인데 주말 요금이 더 높은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"주말에 그 방을 쓰려는 사람이 더 많기 때문이에요","correct":true},{"t":"주말에는 방이 더 넓어지기 때문이에요","mis":"SO4-1-u3-X02"},{"t":"주말에만 문을 열기 때문이에요","mis":"SO4-1-u3-X02"},{"t":"주말에는 방의 수가 늘어나기 때문이에요","mis":"SO4-1-u3-X02"}],"explanation":["방은 그대로예요.","쓰려는 사람이 달라요.","원하는 사람이 많아요."],"asset":{"type":"passage","lines":["같은 숙소, 같은 방이다.","월요일~목요일 — 이용 요금이 낮다.","금요일~토요일 — 이용 요금이 높다.","주말에는 이 방을 쓰려는 사람이 훨씬 많다."],"title":"숙소 요금 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#7','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',2,'ox','auto','쥐치는 옛날이나 오늘날이나 똑같이 귀한 물고기예요.',ARRAY['SO4-1-u3-X02']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"ox","stem":"쥐치는 옛날이나 오늘날이나 똑같이 귀한 물고기예요.","answer":"X","reason_options":[{"t":"찾는 사람이 많아지면서 오늘날 귀해졌기 때문에","correct":true},{"t":"희소성은 물고기 수로만 정해져 늘 같기 때문에","mis":"SO4-1-u3-X02"}],"mis":"SO4-1-u3-X02","explanation":["옛날에는 흔했어요.","찾는 사람이 늘었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["옛날 — 바다에 흔했지만 찾는 사람이 적어 귀하지 않았다.","오늘날 — 쥐포의 인기가 높아져 찾는 사람이 많아졌다.","그래서 오늘날에는 귀한 물고기가 되었다."],"title":"쥐치 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#8','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"경제활동","r":"만들고 사고팔고 쓰는 모든 활동"},{"l":"자원의 희소성","r":"원하는 것에 비해 자원이 부족한 상태"}],"mis":"SO4-1-u3-X02","explanation":["경제활동은 활동이에요.","희소성은 상태예요.","뜻을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#9','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',2,'blank','auto','원하는 것을 모두 가질 수 없으니, 하나를 고르면 다른 하나는 (    )해야 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"blank","stem":"원하는 것을 모두 가질 수 없으니, 하나를 고르면 다른 하나는 (    )해야 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"포기","correct":true},{"t":"저축","mis":"SO4-1-u3-X04"},{"t":"선물","mis":"SO4-1-u3-X04"},{"t":"주문","mis":"SO4-1-u3-X04"}],"explanation":["다 가질 수 없어요.","하나를 골라요.","나머지는 포기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_basic#10','soc',4,1,'u3','L01','g4_1_soc_u3_L01_basic','lesson_basic','SO4-1-u3-C1',3,'mc','auto','선택의 문제가 일어나는 상황이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X05']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"mc","stem":"선택의 문제가 일어나는 상황이 아닌 것은 무엇인가요?","options":[{"t":"숨 쉴 공기를 마실지 말지 고민해요","correct":true},{"t":"돈이 모자라 무엇을 살지 고민해요","mis":"SO4-1-u3-X05"},{"t":"시간이 모자라 무엇을 할지 고민해요","mis":"SO4-1-u3-X05"},{"t":"의자가 하나뿐이라 누가 앉을지 고민해요","mis":"SO4-1-u3-X05"}],"explanation":["부족한 것을 찾아요.","공기는 넉넉해요.","고를 필요가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#1','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',2,'mc','auto','경제활동에서 말하는 선택이란 무엇인가요?',ARRAY['SO4-1-u3-X04','SO4-1-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"mc","stem":"경제활동에서 말하는 선택이란 무엇인가요?","options":[{"t":"여러 가지 가운데 무엇을 고를지 정하는 것","correct":true},{"t":"원하는 것을 모두 갖는 것","mis":"SO4-1-u3-X04"},{"t":"아무것도 고르지 않는 것","mis":"SO4-1-u3-X04"},{"t":"물건을 만드는 것","mis":"SO4-1-u3-X01"}],"explanation":["고민해요.","하나를 골라요.","선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#2','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',2,'ox','auto','약속에 늦어 택시를 탈지 버스를 탈지 고민하는 것도 선택의 문제예요.',ARRAY['SO4-1-u3-X02']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"ox","stem":"약속에 늦어 택시를 탈지 버스를 탈지 고민하는 것도 선택의 문제예요.","answer":"O","reason_options":[{"t":"시간이라는 자원이 부족해 고르는 일이기 때문에","correct":true},{"t":"자원은 돈 하나뿐이기 때문에","mis":"SO4-1-u3-X02"}],"mis":"SO4-1-u3-X02","explanation":["시간이 모자라요.","시간도 자원이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#3','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',3,'error','auto','민재가 갖고 싶은 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"error","stem":"민재가 갖고 싶은 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「네 가지를 모두 사도 5,000원이면 충분해.」","correct":true,"mis_target":"SO4-1-u3-X04"},{"t":"친구 가 — 「돈이 모자라서 무엇을 살지 골라야 해.」","mis":"SO4-1-u3-X04"},{"t":"친구 다 — 「하나를 고르면 다른 것은 포기해야 해.」","mis":"SO4-1-u3-X04"}],"explanation":["모두 사면 10,500원이에요.","용돈은 5,000원이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["민재의 용돈 — 5,000원","만화책 — 3,000원","축구공 — 4,000원","색연필 세트 — 2,500원","젤리 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"민재가 갖고 싶은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#4','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',3,'mc','auto','쥐치 이야기로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X02']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"mc","stem":"쥐치 이야기로 알 수 있는 것은 무엇인가요?","options":[{"t":"희소성은 사람들이 원하는 정도에 따라서도 달라져요","correct":true},{"t":"희소성은 물고기의 수로만 정해져요","mis":"SO4-1-u3-X02"},{"t":"흔한 것은 언제까지나 흔해요","mis":"SO4-1-u3-X02"},{"t":"귀한 것은 아무도 찾지 않아요","mis":"SO4-1-u3-X02"}],"explanation":["옛날에는 흔했어요.","찾는 사람이 늘었어요.","원하는 정도가 달라졌어요."],"asset":{"type":"passage","lines":["옛날 — 바다에 흔했지만 찾는 사람이 적어 귀하지 않았다.","오늘날 — 쥐포의 인기가 높아져 찾는 사람이 많아졌다.","그래서 오늘날에는 귀한 물고기가 되었다."],"title":"쥐치 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#5','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',3,'mc','auto','다음 가운데 희소성이 가장 큰 것은 무엇인가요?',ARRAY['SO4-1-u3-X05','SO4-1-u3-X02']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 희소성이 가장 큰 것은 무엇인가요?","options":[{"t":"보고 싶은 사람은 많은데 자리가 적은 공연 표","correct":true},{"t":"바닷가에 끝없이 깔린 모래","mis":"SO4-1-u3-X05"},{"t":"어디에나 있는 공기","mis":"SO4-1-u3-X05"},{"t":"아무도 찾지 않는 낡은 종이","mis":"SO4-1-u3-X02"}],"explanation":["원하는 사람이 많아요.","그런데 적어요.","공연 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#6','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',3,'ox','auto','원하는 것은 많은데 돈이 넉넉하지 않으면, 무엇을 고르고 무엇을 포기할지 정해야 해요.',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"ox","stem":"원하는 것은 많은데 돈이 넉넉하지 않으면, 무엇을 고르고 무엇을 포기할지 정해야 해요.","answer":"O","reason_options":[{"t":"자원이 부족하면 원하는 것을 다 가질 수 없기 때문에","correct":true},{"t":"원하는 것은 언제나 모두 가질 수 있기 때문에","mis":"SO4-1-u3-X04"}],"mis":"SO4-1-u3-X04","explanation":["돈이 넉넉하지 않아요.","다 가질 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#7','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',3,'mc','auto','경제활동이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X01']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"mc","stem":"경제활동이 아닌 것은 무엇인가요?","options":[{"t":"공원에서 친구와 술래잡기를 해요","correct":true},{"t":"가게에서 빵을 사요","mis":"SO4-1-u3-X01"},{"t":"부모님이 회사에서 일하세요","mis":"SO4-1-u3-X01"},{"t":"산 연필을 공부할 때 써요","mis":"SO4-1-u3-X01"}],"explanation":["만들기·사고팔기·쓰기를 찾아요.","술래잡기는 놀이예요.","경제활동이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#8','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',4,'essay','teacher','자원의 희소성이 무엇인지 쓰고, 민재가 갖고 싶은 것을 모두 살 수 없는 까닭과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C1","difficulty":4,"kind":"essay","stem":"자원의 희소성이 무엇인지 쓰고, 민재가 갖고 싶은 것을 모두 살 수 없는 까닭과 이어 쓰세요.","answer_guide":{"answer":"예: 자원의 희소성은 원하는 것에 비해 돈·시간 같은 자원이 부족한 상태예요. 민재가 갖고 싶은 것을 모두 사려면 10,500원이 드는데 용돈은 5,000원뿐이라, 무엇을 사고 무엇을 포기할지 골라야 해요.","scoring_points":["희소성의 뜻을 썼는가","용돈과 드는 돈을 견주어 썼는가","고르고 포기해야 한다는 것과 이어 썼는가"]},"explanation":["뜻을 먼저 써요.","돈을 견줘요.","선택과 이어요."],"asset":{"type":"passage","lines":["민재의 용돈 — 5,000원","만화책 — 3,000원","축구공 — 4,000원","색연필 세트 — 2,500원","젤리 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"민재가 갖고 싶은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#9','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',4,'mc','auto','숙소 요금을 희소성으로 설명한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X02','SO4-1-u3-X03']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C1","difficulty":4,"kind":"mc","stem":"숙소 요금을 희소성으로 설명한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주말에는 원하는 사람이 많아 같은 방도 더 귀해지기 때문이에요","correct":true},{"t":"주말에는 방이 더 좋아지기 때문이에요","mis":"SO4-1-u3-X02"},{"t":"평일에 희소성이 더 크기 때문이에요","mis":"SO4-1-u3-X02"},{"t":"요금은 희소성과 관계없기 때문이에요","mis":"SO4-1-u3-X03"}],"explanation":["방은 같아요.","원하는 사람이 달라요.","주말에 더 귀해요."],"asset":{"type":"passage","lines":["같은 숙소, 같은 방이다.","월요일~목요일 — 이용 요금이 낮다.","금요일~토요일 — 이용 요금이 높다.","주말에는 이 방을 쓰려는 사람이 훨씬 많다."],"title":"숙소 요금 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L01_challenge#10','soc',4,1,'u3','L01','g4_1_soc_u3_L01_challenge','lesson_challenge','SO4-1-u3-C1',4,'essay','teacher','내 생활에서 선택의 문제를 겪은 일을 하나 쓰고, 무엇을 고르고 무엇을 포기했는지와 그렇게 해야 했던 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C1","difficulty":4,"kind":"essay","stem":"내 생활에서 선택의 문제를 겪은 일을 하나 쓰고, 무엇을 고르고 무엇을 포기했는지와 그렇게 해야 했던 까닭을 쓰세요.","answer_guide":{"answer":"예: 토요일 오후에 친구와 놀지 숙제를 할지 고민했어요. 시간이 모자라 숙제를 고르고 노는 것은 포기했어요. 시간이라는 자원이 부족해 둘 다 할 수 없었기 때문이에요.","scoring_points":["선택의 문제를 겪은 일을 썼는가","고른 것과 포기한 것을 썼는가","자원이 부족해서라는 까닭을 썼는가"]},"explanation":["겪은 일을 떠올려요.","고른 것과 포기한 것을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#1','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',1,'mc','auto','적은 비용과 노력으로 가장 큰 만족감을 얻는 선택을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07','SO4-1-u3-X08']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"mc","stem":"적은 비용과 노력으로 가장 큰 만족감을 얻는 선택을 무엇이라고 하나요?","options":[{"t":"합리적 선택","correct":true},{"t":"가장 비싼 선택","mis":"SO4-1-u3-X06"},{"t":"아무렇게나 한 선택","mis":"SO4-1-u3-X07"},{"t":"친구를 따라 한 선택","mis":"SO4-1-u3-X08"}],"explanation":["비용은 적게요.","만족은 크게요.","합리적 선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#2','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',1,'sa','auto','여러 가지를 따져 보지 않고 골라 만족하지 못하면 무엇을 하기 쉬운가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"sa","stem":"여러 가지를 따져 보지 않고 골라 만족하지 못하면 무엇을 하기 쉬운가요? 두 글자로 쓰세요.","answer":["후회"],"explanation":["따져 보지 않았어요.","만족하지 못해요.","후회해요."],"mis":"SO4-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#3','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',1,'ox','auto','합리적 선택은 언제나 가장 싼 물건을 사는 거예요.',ARRAY['SO4-1-u3-X06']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"ox","stem":"합리적 선택은 언제나 가장 싼 물건을 사는 거예요.","answer":"X","reason_options":[{"t":"비용에 비해 만족이 큰지를 함께 따져야 하기 때문에","correct":true},{"t":"값이 쌀수록 언제나 만족이 크기 때문에","mis":"SO4-1-u3-X06"}],"mis":"SO4-1-u3-X06","explanation":["싸기만 하면 될까요?","만족도 따져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#4','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',1,'mc','auto','수아가 후회한 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X08','SO4-1-u3-X03']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"mc","stem":"수아가 후회한 까닭은 무엇인가요?","options":[{"t":"날씨를 생각하지 않고 디자인만 보고 골랐기 때문이에요","correct":true},{"t":"옷값이 쌌기 때문이에요","mis":"SO4-1-u3-X06"},{"t":"친구와 같은 옷이었기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"옷이 너무 많았기 때문이에요","mis":"SO4-1-u3-X03"}],"explanation":["얇은 옷이에요.","디자인만 봤어요.","날씨를 놓쳤어요."],"asset":{"type":"passage","lines":["수아 — 날씨는 생각하지 않고 디자인만 보고 산 옷이 너무 얇아 추웠다.","태오 — 산 필통을 다른 가게에서 더 싸게 파는 것을 나중에 보았다.","나연 — 품질은 살피지 않고 값만 보고 산 신발이 발에 불편했다."],"title":"세 친구의 후회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#5','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',2,'mc','auto','태오가 같은 후회를 하지 않으려면 어떻게 해야 하나요?',ARRAY['SO4-1-u3-X07','SO4-1-u3-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"mc","stem":"태오가 같은 후회를 하지 않으려면 어떻게 해야 하나요?","options":[{"t":"사기 전에 여러 가게의 값을 견줘 봐요","correct":true},{"t":"디자인만 보고 골라요","mis":"SO4-1-u3-X07"},{"t":"처음 들른 가게에서 바로 사요","mis":"SO4-1-u3-X07"},{"t":"가장 비싼 가게에서 사요","mis":"SO4-1-u3-X06"}],"explanation":["더 싸게 파는 곳이 있었어요.","값을 견주지 않았어요.","견줘 보고 사요."],"asset":{"type":"passage","lines":["수아 — 날씨는 생각하지 않고 디자인만 보고 산 옷이 너무 얇아 추웠다.","태오 — 산 필통을 다른 가게에서 더 싸게 파는 것을 나중에 보았다.","나연 — 품질은 살피지 않고 값만 보고 산 신발이 발에 불편했다."],"title":"세 친구의 후회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#6','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',2,'mc','auto','조금만 고치면 되는 고장이에요. 비용과 만족을 견주면 가장 합리적인 선택은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07','SO4-1-u3-X04']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"mc","stem":"조금만 고치면 되는 고장이에요. 비용과 만족을 견주면 가장 합리적인 선택은 무엇인가요?","options":[{"t":"㉮ 고쳐 쓰기","correct":true},{"t":"㉯ 새로 사기 — 새것이 언제나 가장 좋아서","mis":"SO4-1-u3-X06"},{"t":"㉰ 아무 중고나 사기 — 가장 싸서","mis":"SO4-1-u3-X07"},{"t":"그냥 버리고 타지 않기","mis":"SO4-1-u3-X04"}],"explanation":["가벼운 고장이에요.","수리비는 조금 들어요.","고쳐 쓰기예요."],"asset":{"type":"passage","lines":["지안이의 인라인스케이트 바퀴 하나가 고장 났다(조금만 고치면 된다).","㉮ 고쳐 쓰기 — 수리비가 조금 들고, 익숙한 것을 계속 탄다.","㉯ 새로 사기 — 새것이라 좋지만 돈이 많이 든다.","㉰ 중고 사기 — 새것보다 싸지만 상태를 잘 살펴야 한다."],"title":"고장 난 인라인스케이트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#7','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',2,'ox','auto','나연이는 품질을 살피지 않고 값만 보고 골라 후회했어요.',ARRAY['SO4-1-u3-X07']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"ox","stem":"나연이는 품질을 살피지 않고 값만 보고 골라 후회했어요.","answer":"O","reason_options":[{"t":"값만 보고 품질을 따지지 않으면 만족하지 못할 수 있기 때문에","correct":true},{"t":"값만 보고 고르면 언제나 후회가 없기 때문에","mis":"SO4-1-u3-X07"}],"mis":"SO4-1-u3-X07","explanation":["값만 봤어요.","발이 불편했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["수아 — 날씨는 생각하지 않고 디자인만 보고 산 옷이 너무 얇아 추웠다.","태오 — 산 필통을 다른 가게에서 더 싸게 파는 것을 나중에 보았다.","나연 — 품질은 살피지 않고 값만 보고 산 신발이 발에 불편했다."],"title":"세 친구의 후회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#8','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',2,'match','auto','비용과 만족감의 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"match","stem":"비용과 만족감의 뜻을 알맞게 이으세요.","pairs":[{"l":"비용","r":"고를 때 드는 돈·시간·노력"},{"l":"만족감","r":"고른 뒤에 느끼는 흐뭇한 마음"}],"mis":"SO4-1-u3-X06","explanation":["비용은 드는 것이에요.","만족감은 느끼는 것이에요.","뜻을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#9','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',2,'blank','auto','돈·시간·노력 같은 자원은 (    )되어 있어서, 아무렇게나 고르면 낭비하고 후회하기 쉬워요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X07','SO4-1-u3-X06']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"blank","stem":"돈·시간·노력 같은 자원은 (    )되어 있어서, 아무렇게나 고르면 낭비하고 후회하기 쉬워요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"한정","correct":true},{"t":"무한","mis":"SO4-1-u3-X07"},{"t":"공짜로 준비","mis":"SO4-1-u3-X06"},{"t":"언제나 남게","mis":"SO4-1-u3-X07"}],"explanation":["자원은 끝이 있어요.","아껴야 해요.","한정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_basic#10','soc',4,1,'u3','L02','g4_1_soc_u3_L02_basic','lesson_basic','SO4-1-u3-C2',3,'mc','auto','같은 고장을 두고 나는 ㉮, 친구는 ㉰를 골랐어요. 그럴 수 있는 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X08','SO4-1-u3-X06']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"mc","stem":"같은 고장을 두고 나는 ㉮, 친구는 ㉰를 골랐어요. 그럴 수 있는 까닭은 무엇인가요?","options":[{"t":"사람마다 중요하게 여기는 것이 다르기 때문이에요","correct":true},{"t":"둘 가운데 한 사람은 잘못 골랐기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"합리적 선택은 언제나 하나뿐이기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"비싼 것을 고른 사람이 이기기 때문이에요","mis":"SO4-1-u3-X06"}],"explanation":["중요한 것이 달라요.","선택이 달라져요.","둘 다 따져 봤어요."],"asset":{"type":"passage","lines":["지안이의 인라인스케이트 바퀴 하나가 고장 났다(조금만 고치면 된다).","㉮ 고쳐 쓰기 — 수리비가 조금 들고, 익숙한 것을 계속 탄다.","㉯ 새로 사기 — 새것이라 좋지만 돈이 많이 든다.","㉰ 중고 사기 — 새것보다 싸지만 상태를 잘 살펴야 한다."],"title":"고장 난 인라인스케이트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#1','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',2,'mc','auto','퍼스널 쇼퍼는 어떤 일을 하나요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07','SO4-1-u3-X08']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"mc","stem":"퍼스널 쇼퍼는 어떤 일을 하나요?","options":[{"t":"사려는 사람의 나이·취향 등을 살펴 알맞은 상품을 추천해요","correct":true},{"t":"가장 비싼 상품만 권해요","mis":"SO4-1-u3-X06"},{"t":"아무 상품이나 골라 줘요","mis":"SO4-1-u3-X07"},{"t":"모든 사람에게 같은 상품을 권해요","mis":"SO4-1-u3-X08"}],"explanation":["취향을 살펴요.","알맞은 것을 찾아요.","합리적 선택을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#2','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',2,'ox','auto','합리적 선택을 하면 자원을 아끼면서 더 큰 만족을 얻을 수 있어요.',ARRAY['SO4-1-u3-X06']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"ox","stem":"합리적 선택을 하면 자원을 아끼면서 더 큰 만족을 얻을 수 있어요.","answer":"O","reason_options":[{"t":"따져 보고 골라 낭비와 후회를 줄이기 때문에","correct":true},{"t":"합리적 선택은 만족과 관계없기 때문에","mis":"SO4-1-u3-X06"}],"mis":"SO4-1-u3-X06","explanation":["따져 보고 골라요.","낭비가 줄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#3','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',3,'error','auto','고장 난 인라인스케이트를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"error","stem":"고장 난 인라인스케이트를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「새것이 가장 좋으니 고장 나면 언제나 새로 사는 게 합리적이야.」","correct":true,"mis_target":"SO4-1-u3-X06"},{"t":"친구 가 — 「가벼운 고장이면 고쳐 쓰는 게 비용이 적어.」","mis":"SO4-1-u3-X07"},{"t":"친구 나 — 「중고는 싸지만 상태를 잘 살펴야 해.」","mis":"SO4-1-u3-X07"}],"explanation":["언제나 새것일까요?","비용도 따져요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["지안이의 인라인스케이트 바퀴 하나가 고장 났다(조금만 고치면 된다).","㉮ 고쳐 쓰기 — 수리비가 조금 들고, 익숙한 것을 계속 탄다.","㉯ 새로 사기 — 새것이라 좋지만 돈이 많이 든다.","㉰ 중고 사기 — 새것보다 싸지만 상태를 잘 살펴야 한다."],"title":"고장 난 인라인스케이트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#4','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',3,'mc','auto','㉰ 중고 사기를 고를 때 꼭 살펴야 할 것은 무엇인가요?',ARRAY['SO4-1-u3-X07','SO4-1-u3-X06','SO4-1-u3-X08']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"mc","stem":"㉰ 중고 사기를 고를 때 꼭 살펴야 할 것은 무엇인가요?","options":[{"t":"물건의 상태가 좋은지","correct":true},{"t":"색이 예쁜지만","mis":"SO4-1-u3-X07"},{"t":"가장 싼지만","mis":"SO4-1-u3-X06"},{"t":"친구도 샀는지","mis":"SO4-1-u3-X08"}],"explanation":["중고는 쓰던 것이에요.","금방 고장 날 수 있어요.","상태를 살펴요."],"asset":{"type":"passage","lines":["지안이의 인라인스케이트 바퀴 하나가 고장 났다(조금만 고치면 된다).","㉮ 고쳐 쓰기 — 수리비가 조금 들고, 익숙한 것을 계속 탄다.","㉯ 새로 사기 — 새것이라 좋지만 돈이 많이 든다.","㉰ 중고 사기 — 새것보다 싸지만 상태를 잘 살펴야 한다."],"title":"고장 난 인라인스케이트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#5','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',3,'mc','auto','합리적 선택이 필요한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X07','SO4-1-u3-X06','SO4-1-u3-X08']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"mc","stem":"합리적 선택이 필요한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자원은 한정되어 있어 낭비와 후회를 줄여야 하기 때문이에요","correct":true},{"t":"가게가 많아 모두 들러야 하기 때문이에요","mis":"SO4-1-u3-X07"},{"t":"비싼 물건을 많이 사야 하기 때문이에요","mis":"SO4-1-u3-X06"},{"t":"다른 사람과 똑같이 사야 하기 때문이에요","mis":"SO4-1-u3-X08"}],"explanation":["자원은 끝이 있어요.","아껴 써야 해요.","그래서 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#6','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',3,'ox','auto','사람마다 중요하게 여기는 것이 달라서 합리적 선택도 여러 가지일 수 있어요.',ARRAY['SO4-1-u3-X08']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"ox","stem":"사람마다 중요하게 여기는 것이 달라서 합리적 선택도 여러 가지일 수 있어요.","answer":"O","reason_options":[{"t":"같은 상황에서도 따져 보는 것이 달라 선택이 달라지기 때문에","correct":true},{"t":"합리적 선택은 누구에게나 하나뿐이기 때문에","mis":"SO4-1-u3-X08"}],"mis":"SO4-1-u3-X08","explanation":["중요한 것이 달라요.","선택도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#7','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',3,'mc','auto','세 친구가 후회한 일의 공통점은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X08']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"mc","stem":"세 친구가 후회한 일의 공통점은 무엇인가요?","options":[{"t":"여러 가지를 따져 보지 않고 골라 만족하지 못했어요","correct":true},{"t":"모두 가장 비싼 것을 샀어요","mis":"SO4-1-u3-X06"},{"t":"모두 새것이 아니었어요","mis":"SO4-1-u3-X06"},{"t":"모두 친구를 따라 샀어요","mis":"SO4-1-u3-X08"}],"explanation":["수아·태오·나연이에요.","한 가지만 봤어요.","따져 보지 않았어요."],"asset":{"type":"passage","lines":["수아 — 날씨는 생각하지 않고 디자인만 보고 산 옷이 너무 얇아 추웠다.","태오 — 산 필통을 다른 가게에서 더 싸게 파는 것을 나중에 보았다.","나연 — 품질은 살피지 않고 값만 보고 산 신발이 발에 불편했다."],"title":"세 친구의 후회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#8','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',4,'essay','teacher','합리적 선택이 무엇인지 쓰고, 지안이에게 가장 알맞은 선택과 그 까닭을 비용과 만족으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C2","difficulty":4,"kind":"essay","stem":"합리적 선택이 무엇인지 쓰고, 지안이에게 가장 알맞은 선택과 그 까닭을 비용과 만족으로 쓰세요.","answer_guide":{"answer":"예: 합리적 선택은 적은 비용과 노력으로 가장 큰 만족을 얻는 선택이에요. 지안이는 바퀴만 조금 고치면 되니 ㉮ 고쳐 쓰기가 알맞아요. 수리비는 조금 들고, 익숙한 인라인스케이트를 계속 탈 수 있어 만족이 크기 때문이에요.","scoring_points":["합리적 선택의 뜻을 썼는가","하나를 골랐는가","비용과 만족으로 까닭을 썼는가"]},"explanation":["뜻을 써요.","하나를 골라요.","비용과 만족을 견줘요."],"asset":{"type":"passage","lines":["지안이의 인라인스케이트 바퀴 하나가 고장 났다(조금만 고치면 된다).","㉮ 고쳐 쓰기 — 수리비가 조금 들고, 익숙한 것을 계속 탄다.","㉯ 새로 사기 — 새것이라 좋지만 돈이 많이 든다.","㉰ 중고 사기 — 새것보다 싸지만 상태를 잘 살펴야 한다."],"title":"고장 난 인라인스케이트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#9','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',4,'mc','auto','수아가 날마다 쓸 우산을 골라요. ㉮ 2,000원 — 바람에 금방 뒤집힘 / ㉯ 6,000원 — 바람에도 튼튼함. 수아에게 더 합리적인 선택과 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C2","difficulty":4,"kind":"mc","stem":"수아가 날마다 쓸 우산을 골라요. ㉮ 2,000원 — 바람에 금방 뒤집힘 / ㉯ 6,000원 — 바람에도 튼튼함. 수아에게 더 합리적인 선택과 까닭은 무엇인가요?","options":[{"t":"㉯ — 날마다 쓰니 조금 비싸도 오래 써서 만족이 크기 때문이에요","correct":true},{"t":"㉮ — 가장 싼 것은 언제나 합리적이기 때문이에요","mis":"SO4-1-u3-X06"},{"t":"㉯ — 비쌀수록 언제나 좋기 때문이에요","mis":"SO4-1-u3-X06"},{"t":"아무거나 — 우산은 따져 볼 필요가 없기 때문이에요","mis":"SO4-1-u3-X07"}],"explanation":["날마다 써요.","튼튼해야 해요.","만족이 큰 ㉯예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L02_challenge#10','soc',4,1,'u3','L02','g4_1_soc_u3_L02_challenge','lesson_challenge','SO4-1-u3-C2',4,'essay','teacher','세 친구 가운데 한 명을 골라, 다시 고른다면 무엇을 따져 봐야 하는지 쓰고 그렇게 하면 무엇이 좋아지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C2","difficulty":4,"kind":"essay","stem":"세 친구 가운데 한 명을 골라, 다시 고른다면 무엇을 따져 봐야 하는지 쓰고 그렇게 하면 무엇이 좋아지는지 쓰세요.","answer_guide":{"answer":"예: 나연이는 값뿐 아니라 품질도 따져 봐야 해요. 직접 신어 보고 발이 편한지, 튼튼한지 살피면 불편한 신발을 사서 후회하는 일이 줄고, 돈에 비해 만족이 커져요.","scoring_points":["한 친구를 골랐는가","따져 봐야 할 것을 썼는가","좋아지는 점을 썼는가"]},"explanation":["친구를 골라요.","놓친 것을 찾아요.","좋아지는 점을 써요."],"asset":{"type":"passage","lines":["수아 — 날씨는 생각하지 않고 디자인만 보고 산 옷이 너무 얇아 추웠다.","태오 — 산 필통을 다른 가게에서 더 싸게 파는 것을 나중에 보았다.","나연 — 품질은 살피지 않고 값만 보고 산 신발이 발에 불편했다."],"title":"세 친구의 후회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_basic#1','soc',4,1,'u3','L03','g4_1_soc_u3_L03_basic','lesson_basic','SO4-1-u3-C3',1,'mc','auto','물건을 써 본 주변 사람에게 물어보면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u3-X09','SO4-1-u3-X10']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"mc","stem":"물건을 써 본 주변 사람에게 물어보면 좋은 점은 무엇인가요?","options":[{"t":"실제로 써 본 생생한 정보를 알 수 있어요","correct":true},{"t":"여러 가게의 값을 한눈에 볼 수 있어요","mis":"SO4-1-u3-X09"},{"t":"물건을 직접 만져 볼 수 있어요","mis":"SO4-1-u3-X09"},{"t":"언제나 가장 싼 값을 알려 줘요","mis":"SO4-1-u3-X10"}],"explanation":["써 본 사람이에요.","경험을 들어요.","생생한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_basic#2','soc',4,1,'u3','L03','g4_1_soc_u3_L03_basic','lesson_basic','SO4-1-u3-C3',1,'sa','auto','정보를 쓸 때 그 정보가 어디에서 나왔는지 확인해요. 정보가 나온 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"sa","stem":"정보를 쓸 때 그 정보가 어디에서 나왔는지 확인해요. 정보가 나온 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["어디에서 나왔나요?","나온 곳이에요.","출처예요."],"mis":"SO4-1-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_basic#3','soc',4,1,'u3','L03','g4_1_soc_u3_L03_basic','lesson_basic','SO4-1-u3-C3',1,'ox','auto','㉱ 광고에 나온 말은 그대로 믿어도 돼요.',ARRAY['SO4-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"ox","stem":"㉱ 광고에 나온 말은 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"근거 없이 부풀린 말일 수 있어 확인해야 하기 때문에","correct":true},{"t":"광고에 나온 말은 모두 사실이기 때문에","mis":"SO4-1-u3-X10"}],"mis":"SO4-1-u3-X10","explanation":["「무조건」이라고 해요.","근거가 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 써 본 형 — 「두 달 신었는데 발이 편하고 멀쩡해.」","㉯ 가격 비교 누리집 — 가게 ① 20,000원 · 가게 ② 17,000원 · 가게 ③ 18,500원","㉰ 가게에서 직접 신어 보니 크기가 맞고 바느질이 튼튼했다.","㉱ 광고 — 「이 운동화만 신으면 달리기 1등! 무조건!」"],"title":"지안이가 운동화를 사려고 모은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
