INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_basic#7','soc',4,1,'u3','L03','g4_1_soc_u3_L03_basic','lesson_basic','SO4-1-u3-C3',2,'ox','auto','여러 방법으로 정보를 얻으면 더 정확한 정보를 얻을 수 있어요.',ARRAY['SO4-1-u3-X12']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"ox","stem":"여러 방법으로 정보를 얻으면 더 정확한 정보를 얻을 수 있어요.","answer":"O","reason_options":[{"t":"방법마다 알 수 있는 것이 달라 서로 보태지기 때문에","correct":true},{"t":"정보는 한 가지 방법으로만 얻어도 충분하기 때문에","mis":"SO4-1-u3-X12"}],"mis":"SO4-1-u3-X12","explanation":["방법마다 좋은 점이 달라요.","함께 쓰면 보태져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
