INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_basic#9','soc',4,1,'u3','L03','g4_1_soc_u3_L03_basic','lesson_basic','SO4-1-u3-C3',2,'blank','auto','「무조건 1등!」처럼 근거 없이 부풀린 광고를 (    ) 광고라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X09']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"blank","stem":"「무조건 1등!」처럼 근거 없이 부풀린 광고를 (    ) 광고라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"과장된","correct":true},{"t":"정확한","mis":"SO4-1-u3-X10"},{"t":"믿을 만한","mis":"SO4-1-u3-X10"},{"t":"생생한","mis":"SO4-1-u3-X09"}],"explanation":["부풀렸어요.","근거가 없어요.","과장된 광고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
