INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#1','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',2,'mc','auto','정보를 쓸 때 꼭 확인할 두 가지는 무엇인가요?',ARRAY['SO4-1-u3-X10']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"mc","stem":"정보를 쓸 때 꼭 확인할 두 가지는 무엇인가요?","options":[{"t":"출처가 믿을 만한지, 정확한 정보인지","correct":true},{"t":"광고가 화려한지, 글자가 큰지","mis":"SO4-1-u3-X10"},{"t":"값이 비싼지, 유행하는지","mis":"SO4-1-u3-X10"},{"t":"가장 먼저 나왔는지, 가장 짧은지","mis":"SO4-1-u3-X10"}],"explanation":["어디서 나왔나요?","맞는 정보인가요?","두 가지를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#2','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',2,'ox','auto','㉮는 실제로 신어 본 사람이 알려 준 정보예요.',ARRAY['SO4-1-u3-X09']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"ox","stem":"㉮는 실제로 신어 본 사람이 알려 준 정보예요.","answer":"O","reason_options":[{"t":"형이 두 달 동안 신어 본 경험을 말했기 때문에","correct":true},{"t":"㉮는 가게에서 낸 광고이기 때문에","mis":"SO4-1-u3-X09"}],"mis":"SO4-1-u3-X09","explanation":["써 본 형이에요.","두 달 신었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 써 본 형 — 「두 달 신었는데 발이 편하고 멀쩡해.」","㉯ 가격 비교 누리집 — 가게 ① 20,000원 · 가게 ② 17,000원 · 가게 ③ 18,500원","㉰ 가게에서 직접 신어 보니 크기가 맞고 바느질이 튼튼했다.","㉱ 광고 — 「이 운동화만 신으면 달리기 1등! 무조건!」"],"title":"지안이가 운동화를 사려고 모은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#3','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',3,'error','auto','지안이가 모은 정보를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"error","stem":"지안이가 모은 정보를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉱ 광고에 ‘무조건’이라고 했으니 꼭 사실일 거야.」","correct":true,"mis_target":"SO4-1-u3-X10"},{"t":"친구 가 — 「㉯로 가게마다 값을 견줄 수 있어.」","mis":"SO4-1-u3-X09"},{"t":"친구 다 — 「㉰는 직접 신어 보고 확인한 정보야.」","mis":"SO4-1-u3-X09"}],"explanation":["「무조건」은 근거가 없어요.","확인해야 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 써 본 형 — 「두 달 신었는데 발이 편하고 멀쩡해.」","㉯ 가격 비교 누리집 — 가게 ① 20,000원 · 가게 ② 17,000원 · 가게 ③ 18,500원","㉰ 가게에서 직접 신어 보니 크기가 맞고 바느질이 튼튼했다.","㉱ 광고 — 「이 운동화만 신으면 달리기 1등! 무조건!」"],"title":"지안이가 운동화를 사려고 모은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#4','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',3,'mc','auto','누리집에서 찾은 정보를 쓸 때 바른 태도는 무엇인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X12']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"mc","stem":"누리집에서 찾은 정보를 쓸 때 바른 태도는 무엇인가요?","options":[{"t":"누가 올린 정보인지 확인하고 다른 정보와 견줘 봐요","correct":true},{"t":"가장 먼저 나온 글을 그대로 믿어요","mis":"SO4-1-u3-X10"},{"t":"좋다는 말이 많으면 모두 믿어요","mis":"SO4-1-u3-X10"},{"t":"한 곳만 보고 바로 정해요","mis":"SO4-1-u3-X12"}],"explanation":["누가 올렸나요?","다른 곳과 견줘요.","확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#5','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',3,'mc','auto','정보를 찾지 않고 바로 사면 어떤 일이 생길 수 있나요?',ARRAY['SO4-1-u3-X11']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"mc","stem":"정보를 찾지 않고 바로 사면 어떤 일이 생길 수 있나요?","options":[{"t":"더 싸고 좋은 물건을 놓쳐 후회할 수 있어요","correct":true},{"t":"언제나 가장 좋은 물건을 사게 돼요","mis":"SO4-1-u3-X11"},{"t":"정보를 찾았을 때와 결과가 늘 같아요","mis":"SO4-1-u3-X11"},{"t":"시간이 들지 않으니 늘 합리적이에요","mis":"SO4-1-u3-X11"}],"explanation":["정보가 없어요.","견주지 못해요.","후회할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#6','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',3,'ox','auto','써 본 사람에게 묻기, 가격 비교, 직접 방문 가운데 한 가지만 쓰는 것이 가장 좋아요.',ARRAY['SO4-1-u3-X12']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"ox","stem":"써 본 사람에게 묻기, 가격 비교, 직접 방문 가운데 한 가지만 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"방법마다 좋은 점이 달라 함께 쓰면 더 정확하기 때문에","correct":true},{"t":"한 가지만 써야 헷갈리지 않기 때문에","mis":"SO4-1-u3-X12"}],"mis":"SO4-1-u3-X12","explanation":["방법마다 달라요.","함께 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#7','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',3,'mc','auto','「이 신발만 신으면 키가 쑥쑥 큰다!」라는 광고를 보았을 때 알맞은 행동은 무엇인가요?',ARRAY['SO4-1-u3-X10']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"mc","stem":"「이 신발만 신으면 키가 쑥쑥 큰다!」라는 광고를 보았을 때 알맞은 행동은 무엇인가요?","options":[{"t":"정말 그런지 근거와 출처를 확인해요","correct":true},{"t":"바로 사요","mis":"SO4-1-u3-X10"},{"t":"친구들에게 그대로 전해요","mis":"SO4-1-u3-X10"},{"t":"광고가 길수록 믿어요","mis":"SO4-1-u3-X10"}],"explanation":["부풀린 말 같아요.","근거가 있나요?","확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#8','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',4,'essay','teacher','지안이가 모은 정보 가운데 믿을 만한 것 하나와 조심해야 할 것 하나를 골라 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C3","difficulty":4,"kind":"essay","stem":"지안이가 모은 정보 가운데 믿을 만한 것 하나와 조심해야 할 것 하나를 골라 그 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉰는 지안이가 직접 신어 보고 크기와 바느질을 확인한 정보라 믿을 만해요. ㉱는 「무조건 1등」처럼 근거 없이 부풀린 광고라서 그대로 믿으면 안 되고 정말 그런지 확인해야 해요.","scoring_points":["믿을 만한 정보를 골라 까닭을 썼는가","조심할 정보를 골라 까닭을 썼는가","출처나 근거를 생각했는가"]},"explanation":["믿을 만한 것을 골라요.","조심할 것을 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 써 본 형 — 「두 달 신었는데 발이 편하고 멀쩡해.」","㉯ 가격 비교 누리집 — 가게 ① 20,000원 · 가게 ② 17,000원 · 가게 ③ 18,500원","㉰ 가게에서 직접 신어 보니 크기가 맞고 바느질이 튼튼했다.","㉱ 광고 — 「이 운동화만 신으면 달리기 1등! 무조건!」"],"title":"지안이가 운동화를 사려고 모은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#9','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',4,'mc','auto','지안이가 ㉮·㉯·㉰를 함께 살펴보고 고른 것이 ㉯ 하나만 본 것보다 나은 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X09','SO4-1-u3-X10','SO4-1-u3-X12']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C3","difficulty":4,"kind":"mc","stem":"지안이가 ㉮·㉯·㉰를 함께 살펴보고 고른 것이 ㉯ 하나만 본 것보다 나은 까닭은 무엇인가요?","options":[{"t":"값뿐 아니라 편한지, 크기가 맞는지, 튼튼한지까지 확인했기 때문이에요","correct":true},{"t":"가게 ①이 가장 싸기 때문이에요","mis":"SO4-1-u3-X09"},{"t":"정보가 많을수록 광고도 믿게 되기 때문이에요","mis":"SO4-1-u3-X10"},{"t":"한 가지만 보면 언제나 후회가 없기 때문이에요","mis":"SO4-1-u3-X12"}],"explanation":["㉯는 값만 알려 줘요.","㉮·㉰는 품질을 알려 줘요.","함께 보면 더 정확해요."],"asset":{"type":"passage","lines":["㉮ 써 본 형 — 「두 달 신었는데 발이 편하고 멀쩡해.」","㉯ 가격 비교 누리집 — 가게 ① 20,000원 · 가게 ② 17,000원 · 가게 ③ 18,500원","㉰ 가게에서 직접 신어 보니 크기가 맞고 바느질이 튼튼했다.","㉱ 광고 — 「이 운동화만 신으면 달리기 1등! 무조건!」"],"title":"지안이가 운동화를 사려고 모은 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L03_challenge#10','soc',4,1,'u3','L03','g4_1_soc_u3_L03_challenge','lesson_challenge','SO4-1-u3-C3',4,'essay','teacher','사고 싶은 물건을 하나 정해, 합리적 선택의 차례에 따라 무엇을 할지 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C3","difficulty":4,"kind":"essay","stem":"사고 싶은 물건을 하나 정해, 합리적 선택의 차례에 따라 무엇을 할지 차례대로 쓰세요.","answer_guide":{"answer":"예: 필통을 사고 싶어요. 먼저 지금 필통이 정말 망가졌는지 생각해요. 그다음 써 본 친구에게 묻고 누리집에서 값을 찾아요. 가게에 가서 직접 열어 보며 값과 품질을 견준 뒤 마음에 맞는 것을 골라요.","scoring_points":["물건을 정했는가","필요 → 정보 → 견주기 → 고르기 차례를 지켰는가","정보를 얻는 방법을 넣었는가"]},"explanation":["물건을 정해요.","차례를 떠올려요.","차례대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#1','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',1,'mc','auto','물건을 사기 전에 먼저 확인할 것이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X13']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"mc","stem":"물건을 사기 전에 먼저 확인할 것이 아닌 것은 무엇인가요?","options":[{"t":"광고에 나온 사람이 누구인지","correct":true},{"t":"나에게 꼭 필요한 물건인지","mis":"SO4-1-u3-X13"},{"t":"이미 있거나 빌려 쓸 수 있는지","mis":"SO4-1-u3-X13"},{"t":"가진 돈으로 살 수 있는지","mis":"SO4-1-u3-X13"}],"explanation":["필요한가요?","이미 있나요? 살 수 있나요?","광고 속 사람은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#2','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',1,'sa','auto','사람과 동물, 환경에 도움이 되는 상품을 고르는 소비를 ○○ 소비라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"sa","stem":"사람과 동물, 환경에 도움이 되는 상품을 고르는 소비를 ○○ 소비라고 해요. 두 글자로 쓰세요.","answer":["착한"],"explanation":["함께 생각해요.","도움이 되는 소비예요.","착한 소비예요."],"mis":"SO4-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#3','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',1,'ox','auto','태오는 멀쩡한 운동화보다 고장 난 자전거를 사는 것이 합리적이에요.',ARRAY['SO4-1-u3-X13']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"ox","stem":"태오는 멀쩡한 운동화보다 고장 난 자전거를 사는 것이 합리적이에요.","answer":"O","reason_options":[{"t":"지금 꼭 필요한 것은 날마다 타는 자전거이기 때문에","correct":true},{"t":"갖고 싶은 것부터 사는 것이 합리적이기 때문에","mis":"SO4-1-u3-X13"}],"mis":"SO4-1-u3-X13","explanation":["운동화는 멀쩡해요.","자전거가 필요해요.","그래서 O예요."],"asset":{"type":"passage","lines":["운동화 — 지금 신는 운동화가 아직 멀쩡하다.","자전거 — 고장 나서 탈 수 없는데, 날마다 도서관 갈 때 탄다.","모은 용돈으로는 둘 가운데 하나만 살 수 있다."],"title":"태오의 고민"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#4','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',1,'mc','auto','물건을 고르는 선택 기준이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"mc","stem":"물건을 고르는 선택 기준이 아닌 것은 무엇인가요?","options":[{"t":"가게 간판의 색깔","correct":true},{"t":"가격","mis":"SO4-1-u3-X14"},{"t":"품질","mis":"SO4-1-u3-X14"},{"t":"서비스","mis":"SO4-1-u3-X14"}],"explanation":["가격·품질·디자인을 떠올려요.","서비스·친환경도 있어요.","간판 색은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#5','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',2,'mc','auto','서비스 기준으로 보면 가장 좋은 자전거는 무엇인가요?',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"mc","stem":"서비스 기준으로 보면 가장 좋은 자전거는 무엇인가요?","options":[{"t":"자전거 ④","correct":true},{"t":"자전거 ①","mis":"SO4-1-u3-X14"},{"t":"자전거 ②","mis":"SO4-1-u3-X14"},{"t":"자전거 ③","mis":"SO4-1-u3-X14"}],"explanation":["서비스는 무상 수리예요.","가장 긴 기간을 찾아요.","3년인 ④예요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#6','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',2,'mc','auto','품질 기준에서 살펴볼 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"mc","stem":"품질 기준에서 살펴볼 점으로 알맞은 것은 무엇인가요?","options":[{"t":"필요한 기능이 있는지, 오래 쓸 수 있는지, 안전한지","correct":true},{"t":"모양과 색이 마음에 드는지","mis":"SO4-1-u3-X14"},{"t":"무상 수리 기간이 얼마인지","mis":"SO4-1-u3-X14"},{"t":"값이 적당한지","mis":"SO4-1-u3-X14"}],"explanation":["품질이에요.","기능·튼튼함·안전이에요.","살펴볼 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#7','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',2,'ox','auto','가격 기준으로 보면 자전거 ①과 ②가 가장 좋아요.',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"ox","stem":"가격 기준으로 보면 자전거 ①과 ②가 가장 좋아요.","answer":"O","reason_options":[{"t":"가장 적은 돈인 9만 원으로 살 수 있기 때문에","correct":true},{"t":"가격 기준에서는 비쌀수록 좋기 때문에","mis":"SO4-1-u3-X14"}],"mis":"SO4-1-u3-X14","explanation":["가격을 견줘요.","9만 원이 가장 적어요.","그래서 O예요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#8','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',2,'match','auto','선택 기준과 살펴볼 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"match","stem":"선택 기준과 살펴볼 점을 알맞게 이으세요.","pairs":[{"l":"디자인","r":"모양과 색이 마음에 드는지"},{"l":"친환경","r":"사람에게 해롭지 않은 소재인지"}],"mis":"SO4-1-u3-X14","explanation":["디자인은 모양과 색이에요.","친환경은 소재예요.","알맞게 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#9','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',2,'blank','auto','여러 기준 가운데 무엇을 더 중요하게 여기는지 정한 차례를 (    )라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X15','SO4-1-u3-X14']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"blank","stem":"여러 기준 가운데 무엇을 더 중요하게 여기는지 정한 차례를 (    )라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"우선순위","correct":true},{"t":"희소성","mis":"SO4-1-u3-X15"},{"t":"비용","mis":"SO4-1-u3-X14"},{"t":"출처","mis":"SO4-1-u3-X14"}],"explanation":["더 중요한 것이요.","먼저 볼 것이에요.","우선순위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_basic#10','soc',4,1,'u3','L04','g4_1_soc_u3_L04_basic','lesson_basic','SO4-1-u3-C4',3,'mc','auto','기준을 바꿀 때마다 가장 좋은 자전거가 달라지는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X15','SO4-1-u3-X14']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"mc","stem":"기준을 바꿀 때마다 가장 좋은 자전거가 달라지는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"여러 기준과 나의 우선순위를 함께 생각해야 해요","correct":true},{"t":"한 가지 기준만 보면 충분해요","mis":"SO4-1-u3-X15"},{"t":"어느 기준으로 보아도 가장 좋은 것은 같아요","mis":"SO4-1-u3-X15"},{"t":"기준은 아무것이나 정해도 돼요","mis":"SO4-1-u3-X14"}],"explanation":["가격으로는 ①·②예요.","서비스로는 ④예요.","기준마다 달라요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#1','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',2,'mc','auto','착한 소비의 예로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X16','SO4-1-u3-X13']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"mc","stem":"착한 소비의 예로 알맞은 것은 무엇인가요?","options":[{"t":"플라스틱 대신 대나무로 만든 칫솔을 골라요","correct":true},{"t":"가장 싼 칫솔을 많이 사 둬요","mis":"SO4-1-u3-X16"},{"t":"나에게만 좋으면 무엇이든 골라요","mis":"SO4-1-u3-X16"},{"t":"쓰지 않을 칫솔도 미리 사 둬요","mis":"SO4-1-u3-X13"}],"explanation":["환경을 생각해요.","대나무 칫솔이에요.","착한 소비예요."],"asset":{"type":"passage","lines":["플라스틱 대신 대나무로 만든 칫솔을 고른다.","어려운 이웃에게 일할 기회를 주는 곳에서 만든 물건을 산다."],"title":"요즘 늘어나는 물건 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#2','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',2,'ox','auto','디자인 기준은 사람마다 마음에 드는 것이 달라서 누구에게나 같은 1등이 없어요.',ARRAY['SO4-1-u3-X15']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"ox","stem":"디자인 기준은 사람마다 마음에 드는 것이 달라서 누구에게나 같은 1등이 없어요.","answer":"O","reason_options":[{"t":"모양과 색을 좋아하는 마음은 사람마다 다르기 때문에","correct":true},{"t":"디자인도 누구에게나 같은 1등이 있기 때문에","mis":"SO4-1-u3-X15"}],"mis":"SO4-1-u3-X15","explanation":["좋아하는 색이 달라요.","1등도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#3','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',3,'error','auto','자전거 기준표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X14','SO4-1-u3-X15']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"error","stem":"자전거 기준표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「무상 수리 기간은 품질 기준에서 살피는 점이야.」","correct":true,"mis_target":"SO4-1-u3-X14"},{"t":"친구 가 — 「품질을 보면 기어가 많고 튼튼한 ③이 좋아.」","mis":"SO4-1-u3-X15"},{"t":"친구 나 — 「친환경을 보면 ④가 좋아.」","mis":"SO4-1-u3-X15"}],"explanation":["무상 수리는 서비스예요.","품질이 아니에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#4','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',3,'mc','auto','「안전이 제일!」인 사람이 가장 먼저 살펴볼 기준은 무엇인가요?',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"mc","stem":"「안전이 제일!」인 사람이 가장 먼저 살펴볼 기준은 무엇인가요?","options":[{"t":"품질","correct":true},{"t":"디자인","mis":"SO4-1-u3-X14"},{"t":"서비스","mis":"SO4-1-u3-X14"},{"t":"가격","mis":"SO4-1-u3-X14"}],"explanation":["안전이에요.","튼튼하고 안전한지요.","품질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#5','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',3,'mc','auto','같은 기준표를 보고 나는 ③, 친구는 ②를 골랐어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X08','SO4-1-u3-X15','SO4-1-u3-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"mc","stem":"같은 기준표를 보고 나는 ③, 친구는 ②를 골랐어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"기준의 우선순위가 서로 다르기 때문이에요","correct":true},{"t":"한 사람이 잘못 골랐기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"기준표가 잘못 만들어졌기 때문이에요","mis":"SO4-1-u3-X15"},{"t":"비싼 것이 언제나 정답이기 때문이에요","mis":"SO4-1-u3-X06"}],"explanation":["같은 표예요.","중요한 기준이 달라요.","우선순위예요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#6','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',3,'ox','auto','지금 운동화가 멀쩡해도 새 운동화가 더 예쁘면 먼저 사는 것이 합리적이에요.',ARRAY['SO4-1-u3-X13']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"ox","stem":"지금 운동화가 멀쩡해도 새 운동화가 더 예쁘면 먼저 사는 것이 합리적이에요.","answer":"X","reason_options":[{"t":"꼭 필요한 것부터 사야 자원을 아낄 수 있기 때문에","correct":true},{"t":"갖고 싶은 마음이 크면 필요한지는 따지지 않아도 되기 때문에","mis":"SO4-1-u3-X13"}],"mis":"SO4-1-u3-X13","explanation":["지금 운동화가 있어요.","꼭 필요하지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["운동화 — 지금 신는 운동화가 아직 멀쩡하다.","자전거 — 고장 나서 탈 수 없는데, 날마다 도서관 갈 때 탄다.","모은 용돈으로는 둘 가운데 하나만 살 수 있다."],"title":"태오의 고민"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#7','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',3,'mc','auto','착한 소비가 중요해지고 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X16','SO4-1-u3-X15']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"mc","stem":"착한 소비가 중요해지고 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"환경을 지키고 어려운 이웃을 도울 수 있기 때문이에요","correct":true},{"t":"가장 싸게 살 수 있기 때문이에요","mis":"SO4-1-u3-X16"},{"t":"나에게만 좋은 선택이기 때문이에요","mis":"SO4-1-u3-X16"},{"t":"기준을 따지지 않아도 되기 때문이에요","mis":"SO4-1-u3-X15"}],"explanation":["나만 생각하지 않아요.","환경과 이웃을 생각해요.","함께 좋은 선택이에요."],"asset":{"type":"passage","lines":["플라스틱 대신 대나무로 만든 칫솔을 고른다.","어려운 이웃에게 일할 기회를 주는 곳에서 만든 물건을 산다."],"title":"요즘 늘어나는 물건 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#8','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',4,'essay','teacher','내가 가장 중요하게 여기는 기준 하나를 정하고, 그 기준으로 자전거를 하나 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C4","difficulty":4,"kind":"essay","stem":"내가 가장 중요하게 여기는 기준 하나를 정하고, 그 기준으로 자전거를 하나 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 나는 서비스를 가장 중요하게 여겨요. 자전거를 오래 타다 보면 고장이 날 수 있으니, 무상 수리가 3년으로 가장 긴 자전거 ④를 고를 거예요.","scoring_points":["기준 하나를 정했는가","기준표에서 자전거를 골랐는가","기준과 이어 까닭을 썼는가"]},"explanation":["기준을 정해요.","표를 살펴요.","까닭을 써요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#9','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',4,'mc','auto','하람이는 9만 원까지만 쓸 수 있고, 방이 좁아 보관이 편한 자전거를 원해요. 하람이에게 가장 합리적인 자전거는 무엇인가요?',ARRAY['SO4-1-u3-X14','SO4-1-u3-X13']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C4","difficulty":4,"kind":"mc","stem":"하람이는 9만 원까지만 쓸 수 있고, 방이 좁아 보관이 편한 자전거를 원해요. 하람이에게 가장 합리적인 자전거는 무엇인가요?","options":[{"t":"자전거 ①","correct":true},{"t":"자전거 ② — 값이 같아서","mis":"SO4-1-u3-X14"},{"t":"자전거 ③ — 가장 튼튼해서","mis":"SO4-1-u3-X13"},{"t":"자전거 ④ — 서비스가 가장 좋아서","mis":"SO4-1-u3-X13"}],"explanation":["9만 원까지예요.","①과 ②가 남아요.","접히는 ①이에요."],"asset":{"type":"passage","lines":["자전거 ① — 9만 원 · 반으로 접혀 보관이 편하다 · 무상 수리 1년","자전거 ② — 9만 원 · 뒤에 보조 안장이 있다 · 무상 수리 1년","자전거 ③ — 15만 원 · 기어가 많고 튼튼하다 · 무상 수리 2년","자전거 ④ — 20만 원 · 가볍고 튼튼하다 · 무상 수리 3년 · 친환경 소재"],"title":"자전거 기준표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L04_challenge#10','soc',4,1,'u3','L04','g4_1_soc_u3_L04_challenge','lesson_challenge','SO4-1-u3-C4',4,'essay','teacher','태오가 물건을 사기 전에 확인해야 할 세 가지를 쓰고, 무엇을 사는 것이 합리적인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C4","difficulty":4,"kind":"essay","stem":"태오가 물건을 사기 전에 확인해야 할 세 가지를 쓰고, 무엇을 사는 것이 합리적인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 태오는 꼭 필요한지, 이미 있거나 빌려 쓸 수 있는지, 가진 돈으로 살 수 있는지 확인해야 해요. 운동화는 멀쩡하지만 자전거는 고장 나서 날마다 탈 수 없으니 자전거를 사는 것이 합리적이에요.","scoring_points":["세 가지를 썼는가","하나를 골랐는가","필요와 이어 까닭을 썼는가"]},"explanation":["세 가지를 떠올려요.","하나를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["운동화 — 지금 신는 운동화가 아직 멀쩡하다.","자전거 — 고장 나서 탈 수 없는데, 날마다 도서관 갈 때 탄다.","모은 용돈으로는 둘 가운데 하나만 살 수 있다."],"title":"태오의 고민"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#1','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',1,'mc','auto','점수표로 고를 때 합리적 선택은 무엇인가요?',ARRAY['SO4-1-u3-X17','SO4-1-u3-X06']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C5","difficulty":1,"kind":"mc","stem":"점수표로 고를 때 합리적 선택은 무엇인가요?","options":[{"t":"점수 합계가 가장 큰 것","correct":true},{"t":"한 칸 점수가 가장 큰 것","mis":"SO4-1-u3-X17"},{"t":"값이 가장 싼 것","mis":"SO4-1-u3-X17"},{"t":"값이 가장 비싼 것","mis":"SO4-1-u3-X06"}],"explanation":["점수를 모두 더해요.","합계를 견줘요.","가장 큰 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#2','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',1,'sa','auto','지안이 점수표에서 자전거 ㉮의 점수 합계는 몇 점인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C5","difficulty":1,"kind":"sa","stem":"지안이 점수표에서 자전거 ㉮의 점수 합계는 몇 점인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["9 + 4 + 6이에요.","모두 더해요.","19점이에요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","자전거 ㉮ — 품질 9점 · 가격 4점 · 디자인 6점","자전거 ㉯ — 품질 5점 · 가격 8점 · 디자인 4점","자전거 ㉰ — 품질 10점 · 가격 3점 · 디자인 5점"],"title":"지안이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#3','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',1,'ox','auto','내가 더 중요하게 여기는 기준일수록 줄 수 있는 최대 점수를 크게 해요.',ARRAY['SO4-1-u3-X18']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C5","difficulty":1,"kind":"ox","stem":"내가 더 중요하게 여기는 기준일수록 줄 수 있는 최대 점수를 크게 해요.","answer":"O","reason_options":[{"t":"그래야 나의 우선순위가 선택에 담기기 때문에","correct":true},{"t":"모든 기준의 최대 점수는 언제나 같아야 하기 때문에","mis":"SO4-1-u3-X18"}],"mis":"SO4-1-u3-X18","explanation":["중요한 기준이에요.","점수를 크게 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#4','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',1,'mc','auto','점수표의 점수는 어떻게 정하나요?',ARRAY['SO4-1-u3-X19','SO4-1-u3-X06']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C5","difficulty":1,"kind":"mc","stem":"점수표의 점수는 어떻게 정하나요?","options":[{"t":"내가 판단해서 매겨요","correct":true},{"t":"누구나 같은 정답 점수가 있어요","mis":"SO4-1-u3-X19"},{"t":"가게 주인이 정해 줘요","mis":"SO4-1-u3-X19"},{"t":"비싼 물건에 언제나 높은 점수를 줘요","mis":"SO4-1-u3-X06"}],"explanation":["정해진 답이 있나요?","내가 생각해요.","내가 매겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#5','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',2,'mc','auto','지안이가 가장 중요하게 여기는 기준은 무엇인가요?',ARRAY['SO4-1-u3-X18']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"mc","stem":"지안이가 가장 중요하게 여기는 기준은 무엇인가요?","options":[{"t":"품질","correct":true},{"t":"가격","mis":"SO4-1-u3-X18"},{"t":"디자인","mis":"SO4-1-u3-X18"},{"t":"세 기준 모두 같아요","mis":"SO4-1-u3-X18"}],"explanation":["최대 점수를 봐요.","10점이 가장 커요.","품질이에요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","자전거 ㉮ — 품질 9점 · 가격 4점 · 디자인 6점","자전거 ㉯ — 품질 5점 · 가격 8점 · 디자인 4점","자전거 ㉰ — 품질 10점 · 가격 3점 · 디자인 5점"],"title":"지안이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#6','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',2,'mc','auto','지안이 점수표로 고른 합리적 선택은 무엇인가요?',ARRAY['SO4-1-u3-X17']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"mc","stem":"지안이 점수표로 고른 합리적 선택은 무엇인가요?","options":[{"t":"자전거 ㉮","correct":true},{"t":"자전거 ㉰ — 품질 점수가 가장 높아서","mis":"SO4-1-u3-X17"},{"t":"자전거 ㉯ — 가격 점수가 가장 높아서","mis":"SO4-1-u3-X17"},{"t":"셋 모두 합계가 같아요","mis":"SO4-1-u3-X17"}],"explanation":["㉮ 19점이에요.","㉯ 17점, ㉰ 18점이에요.","㉮가 가장 커요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","자전거 ㉮ — 품질 9점 · 가격 4점 · 디자인 6점","자전거 ㉯ — 품질 5점 · 가격 8점 · 디자인 4점","자전거 ㉰ — 품질 10점 · 가격 3점 · 디자인 5점"],"title":"지안이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#7','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',2,'ox','auto','나연이도 지안이와 같은 자전거를 고르게 돼요.',ARRAY['SO4-1-u3-X19']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"ox","stem":"나연이도 지안이와 같은 자전거를 고르게 돼요.","answer":"X","reason_options":[{"t":"나연이는 가격을 더 중요하게 여겨 합계가 가장 큰 자전거가 다르기 때문에","correct":true},{"t":"같은 자전거를 보면 누구나 같은 점수를 매기기 때문에","mis":"SO4-1-u3-X19"}],"mis":"SO4-1-u3-X19","explanation":["나연이는 ㉯가 20점이에요.","지안이는 ㉮예요.","그래서 X예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 가격 10점 · 품질 8점 · 디자인 6점","자전거 ㉮ — 가격 5점 · 품질 6점 · 디자인 4점","자전거 ㉯ — 가격 10점 · 품질 5점 · 디자인 5점","자전거 ㉰ — 가격 3점 · 품질 8점 · 디자인 3점"],"title":"나연이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#8','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',2,'match','auto','친구와 큰 점수를 줄 기준을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"match","stem":"친구와 큰 점수를 줄 기준을 알맞게 이으세요.","pairs":[{"l":"「안전이 제일!」인 친구","r":"품질에 큰 점수"},{"l":"「아껴 써야지!」인 친구","r":"가격에 큰 점수"}],"mis":"SO4-1-u3-X18","explanation":["안전은 품질이에요.","아끼기는 가격이에요.","우선순위를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#9','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',2,'blank','auto','기준마다 매긴 점수를 모두 더한 것을 (    )라고 하고, 이것이 가장 큰 것을 골라요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X18','SO4-1-u3-X17']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"blank","stem":"기준마다 매긴 점수를 모두 더한 것을 (    )라고 하고, 이것이 가장 큰 것을 골라요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"합계","correct":true},{"t":"최대 점수","mis":"SO4-1-u3-X18"},{"t":"한 칸 점수","mis":"SO4-1-u3-X17"},{"t":"우선순위","mis":"SO4-1-u3-X18"}],"explanation":["모두 더해요.","더한 값이에요.","합계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_basic#10','soc',4,1,'u3','L05','g4_1_soc_u3_L05_basic','lesson_basic','SO4-1-u3-C5',3,'mc','auto','나연이 점수표로 고른 합리적 선택과 그 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X17']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"mc","stem":"나연이 점수표로 고른 합리적 선택과 그 까닭은 무엇인가요?","options":[{"t":"자전거 ㉯ — 합계가 20점으로 가장 커서","correct":true},{"t":"자전거 ㉰ — 품질 점수가 8점으로 가장 높아서","mis":"SO4-1-u3-X17"},{"t":"자전거 ㉮ — 디자인 점수가 4점이라서","mis":"SO4-1-u3-X17"},{"t":"자전거 ㉯ — 가장 싸 보여서","mis":"SO4-1-u3-X17"}],"explanation":["㉮ 15점, ㉯ 20점이에요.","㉰는 14점이에요.","㉯예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 가격 10점 · 품질 8점 · 디자인 6점","자전거 ㉮ — 가격 5점 · 품질 6점 · 디자인 4점","자전거 ㉯ — 가격 10점 · 품질 5점 · 디자인 5점","자전거 ㉰ — 가격 3점 · 품질 8점 · 디자인 3점"],"title":"나연이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#1','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',2,'mc','auto','점수표로 골라 보면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u3-X15','SO4-1-u3-X19','SO4-1-u3-X06']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"mc","stem":"점수표로 골라 보면 좋은 점은 무엇인가요?","options":[{"t":"여러 기준을 견주어 나에게 맞는 것이 또렷해져요","correct":true},{"t":"한 가지 기준만 보면 돼요","mis":"SO4-1-u3-X15"},{"t":"누구나 같은 답이 나와요","mis":"SO4-1-u3-X19"},{"t":"가장 비싼 것이 늘 1등이 돼요","mis":"SO4-1-u3-X06"}],"explanation":["여러 기준을 봐요.","점수로 견줘요.","나에게 맞는 것이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#2','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',2,'ox','auto','나연이는 가격을 가장 중요하게 여겨요.',ARRAY['SO4-1-u3-X18']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"ox","stem":"나연이는 가격을 가장 중요하게 여겨요.","answer":"O","reason_options":[{"t":"가격의 최대 점수를 10점으로 가장 크게 했기 때문에","correct":true},{"t":"디자인의 최대 점수가 가장 크기 때문에","mis":"SO4-1-u3-X18"}],"mis":"SO4-1-u3-X18","explanation":["최대 점수를 봐요.","가격이 10점이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 가격 10점 · 품질 8점 · 디자인 6점","자전거 ㉮ — 가격 5점 · 품질 6점 · 디자인 4점","자전거 ㉯ — 가격 10점 · 품질 5점 · 디자인 5점","자전거 ㉰ — 가격 3점 · 품질 8점 · 디자인 3점"],"title":"나연이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#3','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',3,'error','auto','지안이 점수표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X17','SO4-1-u3-X18','SO4-1-u3-X08']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"error","stem":"지안이 점수표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉰가 품질 10점이니 지안이에게 합리적인 건 ㉰야.」","correct":true,"mis_target":"SO4-1-u3-X17"},{"t":"친구 나 — 「지안이는 품질을 가장 중요하게 여겨.」","mis":"SO4-1-u3-X18"},{"t":"친구 다 — 「나연이와 고른 게 달라도 괜찮아.」","mis":"SO4-1-u3-X08"}],"explanation":["한 칸만 봤어요.","합계로 견줘요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","자전거 ㉮ — 품질 9점 · 가격 4점 · 디자인 6점","자전거 ㉯ — 품질 5점 · 가격 8점 · 디자인 4점","자전거 ㉰ — 품질 10점 · 가격 3점 · 디자인 5점"],"title":"지안이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
