INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#7','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',3,'mc','auto','용돈이 넉넉하지 않은 친구가 점수표를 만든다면 어떻게 하는 것이 알맞은가요?',ARRAY['SO4-1-u3-X18','SO4-1-u3-X06']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"mc","stem":"용돈이 넉넉하지 않은 친구가 점수표를 만든다면 어떻게 하는 것이 알맞은가요?","options":[{"t":"가격의 최대 점수를 가장 크게 해요","correct":true},{"t":"디자인의 최대 점수를 가장 크게 해요","mis":"SO4-1-u3-X18"},{"t":"모든 기준의 최대 점수를 똑같이 해요","mis":"SO4-1-u3-X18"},{"t":"가장 비싼 자전거에 큰 점수를 줘요","mis":"SO4-1-u3-X06"}],"explanation":["돈이 넉넉하지 않아요.","가격이 중요해요.","가격 점수를 크게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#8','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',4,'essay','teacher','점수표로 합리적 선택을 하는 방법을 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C5","difficulty":4,"kind":"essay","stem":"점수표로 합리적 선택을 하는 방법을 차례대로 쓰세요.","answer_guide":{"answer":"예: 먼저 가격·품질·디자인 같은 기준을 정해요. 그다음 더 중요한 기준일수록 최대 점수를 크게 정해요. 물건마다 기준별로 점수를 매긴 뒤, 모두 더한 합계가 가장 큰 것을 골라요.","scoring_points":["기준을 정한다고 썼는가","중요할수록 최대 점수를 크게 한다고 썼는가","합계를 견줘 고른다고 썼는가"]},"explanation":["기준부터요.","최대 점수를 정해요.","합계로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#9','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',4,'mc','auto','품질을 따지지 않는 친구가 지안이 점수표에서 가격과 디자인 점수만 더한다면 어느 자전거를 고르게 되나요?',ARRAY['SO4-1-u3-X17','SO4-1-u3-X15']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C5","difficulty":4,"kind":"mc","stem":"품질을 따지지 않는 친구가 지안이 점수표에서 가격과 디자인 점수만 더한다면 어느 자전거를 고르게 되나요?","options":[{"t":"자전거 ㉯ — 12점","correct":true},{"t":"자전거 ㉮ — 10점","mis":"SO4-1-u3-X17"},{"t":"자전거 ㉰ — 품질이 10점이라서","mis":"SO4-1-u3-X17"},{"t":"셋 모두 같아요","mis":"SO4-1-u3-X15"}],"explanation":["㉮ 4 + 6 = 10이에요.","㉯ 8 + 4 = 12, ㉰ 3 + 5 = 8이에요.","㉯예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","자전거 ㉮ — 품질 9점 · 가격 4점 · 디자인 6점","자전거 ㉯ — 품질 5점 · 가격 8점 · 디자인 4점","자전거 ㉰ — 품질 10점 · 가격 3점 · 디자인 5점"],"title":"지안이의 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L05_challenge#10','soc',4,1,'u3','L05','g4_1_soc_u3_L05_challenge','lesson_challenge','SO4-1-u3-C5',4,'essay','teacher','가방을 고른다고 할 때 나만의 기준 세 가지와 최대 점수를 정하고, 그렇게 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C5","difficulty":4,"kind":"essay","stem":"가방을 고른다고 할 때 나만의 기준 세 가지와 최대 점수를 정하고, 그렇게 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 품질 10점, 가격 8점, 디자인 6점으로 정할래요. 가방은 날마다 무거운 책을 넣으니 튼튼한 것이 가장 중요하고, 그다음은 용돈으로 살 수 있는지, 마지막으로 모양을 보려고 해요.","scoring_points":["기준 세 가지를 썼는가","최대 점수를 다르게 정했는가","우선순위의 까닭을 썼는가"]},"explanation":["기준을 정해요.","점수를 나눠요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#1','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',1,'mc','auto','낱말 사다리의 ㉠에 들어갈 말은 무엇인가요?',ARRAY['SO4-1-u3-X20']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C6","difficulty":1,"kind":"mc","stem":"낱말 사다리의 ㉠에 들어갈 말은 무엇인가요?","options":[{"t":"자원의 희소성","correct":true},{"t":"합리적 선택","mis":"SO4-1-u3-X20"},{"t":"착한 소비","mis":"SO4-1-u3-X20"},{"t":"선택 기준","mis":"SO4-1-u3-X20"}],"explanation":["원하는 것이 많아요.","자원은 부족해요.","희소성이에요."],"asset":{"type":"passage","lines":["원하는 것은 많은데 자원이 부족해요. → ㉠","그래서 무엇을 고르고 무엇을 포기할지 고민해요. → ㉡","기준과 정보를 살펴 적은 비용으로 큰 만족을 얻어요. → ㉢","사람·동물·환경에 도움이 되는 것까지 생각해요. → ㉣"],"title":"주제① 낱말 사다리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#2','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',1,'sa','auto','낱말 사다리의 ㉢에 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C6","difficulty":1,"kind":"sa","stem":"낱말 사다리의 ㉢에 들어갈 말을 쓰세요.","answer":["합리적 선택","합리적선택"],"explanation":["적은 비용이에요.","큰 만족이에요.","합리적 선택이에요."],"asset":{"type":"passage","lines":["원하는 것은 많은데 자원이 부족해요. → ㉠","그래서 무엇을 고르고 무엇을 포기할지 고민해요. → ㉡","기준과 정보를 살펴 적은 비용으로 큰 만족을 얻어요. → ㉢","사람·동물·환경에 도움이 되는 것까지 생각해요. → ㉣"],"title":"주제① 낱말 사다리"},"mis":"SO4-1-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#3','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C1',1,'ox','auto','경제활동에서 선택의 문제가 생기는 까닭은 자원이 부족하기 때문이에요.',ARRAY['SO4-1-u3-X03']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"ox","stem":"경제활동에서 선택의 문제가 생기는 까닭은 자원이 부족하기 때문이에요.","answer":"O","reason_options":[{"t":"원하는 것을 다 가질 만큼 자원이 넉넉하지 않기 때문에","correct":true},{"t":"고를 물건이 너무 많기 때문에","mis":"SO4-1-u3-X03"}],"mis":"SO4-1-u3-X03","explanation":["자원이 모자라요.","다 가질 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
