INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#5','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',2,'mc','auto','나연이가 머리핀 홍보 문구에 살리면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X10']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C6","difficulty":2,"kind":"mc","stem":"나연이가 머리핀 홍보 문구에 살리면 좋은 점은 무엇인가요?","options":[{"t":"세상에 하나뿐이라는 희소성","correct":true},{"t":"아무도 원하지 않는다는 점","mis":"SO4-1-u3-X21"},{"t":"무조건 세계 1등이라는 말","mis":"SO4-1-u3-X10"},{"t":"값이 가장 싸다는 점만","mis":"SO4-1-u3-X21"}],"explanation":["하나뿐이에요.","귀해요.","희소성을 살려요."],"asset":{"type":"speech","turns":[{"who":"나연","text":"나는 손수 만든 머리핀을 팔 거야. 세상에 하나뿐이야."},{"who":"민재","text":"나는 바퀴를 고친 중고 자전거를 팔래."},{"who":"나연","text":"값은 얼마로 하고, 홍보 문구는 어떻게 쓸까?"},{"who":"민재","text":"배운 것을 살려서 정해 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#6','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',2,'mc','auto','민재가 중고 자전거 값을 정할 때 생각할 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X08']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C6","difficulty":2,"kind":"mc","stem":"민재가 중고 자전거 값을 정할 때 생각할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"쓸모와 상태, 사려는 친구가 원하는 정도","correct":true},{"t":"아무 값이나 마음대로","mis":"SO4-1-u3-X21"},{"t":"새것보다 훨씬 비싸게","mis":"SO4-1-u3-X21"},{"t":"친구가 정한 값을 그대로","mis":"SO4-1-u3-X08"}],"explanation":["쓸모가 있나요?","상태는 어떤가요?","원하는 정도도 봐요."],"asset":{"type":"speech","turns":[{"who":"나연","text":"나는 손수 만든 머리핀을 팔 거야. 세상에 하나뿐이야."},{"who":"민재","text":"나는 바퀴를 고친 중고 자전거를 팔래."},{"who":"나연","text":"값은 얼마로 하고, 홍보 문구는 어떻게 쓸까?"},{"who":"민재","text":"배운 것을 살려서 정해 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#7','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C3',2,'ox','auto','시장 놀이 홍보 문구에는 「무조건 세계 1등!」처럼 부풀려 써도 괜찮아요.',ARRAY['SO4-1-u3-X10']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"ox","stem":"시장 놀이 홍보 문구에는 「무조건 세계 1등!」처럼 부풀려 써도 괜찮아요.","answer":"X","reason_options":[{"t":"근거 없이 부풀린 말은 사는 사람이 합리적으로 고르지 못하게 하기 때문에","correct":true},{"t":"홍보 문구는 사실과 관계없기 때문에","mis":"SO4-1-u3-X10"}],"mis":"SO4-1-u3-X10","explanation":["근거가 있나요?","부풀린 말이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#8','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',2,'match','auto','주제①의 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C6","difficulty":2,"kind":"match","stem":"주제①의 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"자원의 희소성","r":"원하는 것에 비해 자원이 부족해요"},{"l":"착한 소비","r":"사람·동물·환경까지 생각해 골라요"},{"l":"선택 기준","r":"가격·품질·디자인처럼 고를 때 따지는 것"}],"mis":"SO4-1-u3-X20","explanation":["희소성은 부족함이에요.","착한 소비는 함께예요.","기준은 따지는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#9','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',2,'blank','auto','새 상품을 제안할 때는 생활 속에서 겪은 선택의 문제나 (    )한 점을 바탕으로 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X21']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C6","difficulty":2,"kind":"blank","stem":"새 상품을 제안할 때는 생활 속에서 겪은 선택의 문제나 (    )한 점을 바탕으로 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"불편","correct":true},{"t":"유행","mis":"SO4-1-u3-X21"},{"t":"화려","mis":"SO4-1-u3-X21"},{"t":"비싸게","mis":"SO4-1-u3-X21"}],"explanation":["생활에서 겪었어요.","불편했어요.","그것을 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_basic#10','soc',4,1,'u3','L06','g4_1_soc_u3_L06_basic','lesson_basic','SO4-1-u3-C6',3,'mc','auto','주제①의 낱말이 이어지는 차례로 바른 것은 무엇인가요?',ARRAY['SO4-1-u3-X20']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"mc","stem":"주제①의 낱말이 이어지는 차례로 바른 것은 무엇인가요?","options":[{"t":"희소성 → 선택의 문제 → 합리적 선택 → 착한 소비","correct":true},{"t":"합리적 선택 → 희소성 → 착한 소비 → 선택의 문제","mis":"SO4-1-u3-X20"},{"t":"선택의 문제 → 착한 소비 → 희소성 → 합리적 선택","mis":"SO4-1-u3-X20"},{"t":"착한 소비 → 합리적 선택 → 선택의 문제 → 희소성","mis":"SO4-1-u3-X20"}],"explanation":["부족함에서 시작해요.","고민하고 따져요.","함께까지 생각해요."],"asset":{"type":"passage","lines":["원하는 것은 많은데 자원이 부족해요. → ㉠","그래서 무엇을 고르고 무엇을 포기할지 고민해요. → ㉡","기준과 정보를 살펴 적은 비용으로 큰 만족을 얻어요. → ㉢","사람·동물·환경에 도움이 되는 것까지 생각해요. → ㉣"],"title":"주제① 낱말 사다리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#1','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C2',2,'mc','auto','주제①에서 배운 합리적 선택을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X08','SO4-1-u3-X07']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"mc","stem":"주제①에서 배운 합리적 선택을 바르게 말한 것은 무엇인가요?","options":[{"t":"적은 비용과 노력으로 가장 큰 만족을 얻는 선택","correct":true},{"t":"가장 비싼 것을 고르는 선택","mis":"SO4-1-u3-X06"},{"t":"다른 사람이 고른 대로 따르는 선택","mis":"SO4-1-u3-X08"},{"t":"아무렇게나 빨리 고르는 선택","mis":"SO4-1-u3-X07"}],"explanation":["비용은 적게요.","만족은 크게요.","합리적 선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#2','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C5',2,'ox','auto','점수표 결과가 친구와 다르면 다시 매겨 똑같이 맞춰야 해요.',ARRAY['SO4-1-u3-X19']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"ox","stem":"점수표 결과가 친구와 다르면 다시 매겨 똑같이 맞춰야 해요.","answer":"X","reason_options":[{"t":"점수는 저마다 판단해 매기므로 결과가 달라도 되기 때문에","correct":true},{"t":"점수표의 정답은 하나뿐이기 때문에","mis":"SO4-1-u3-X19"}],"mis":"SO4-1-u3-X19","explanation":["점수는 내가 매겨요.","달라도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#3','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C6',3,'error','auto','시장 놀이를 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X20']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"error","stem":"시장 놀이를 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「머리핀 값은 아무렇게나 정해도 돼. 배운 것과는 관계없어.」","correct":true,"mis_target":"SO4-1-u3-X21"},{"t":"친구 가 — 「하나뿐이니 희소성을 살려 홍보하자.」","mis":"SO4-1-u3-X20"},{"t":"친구 다 — 「사는 친구는 쓸모를 기준으로 따져 볼 거야.」","mis":"SO4-1-u3-X20"}],"explanation":["배운 것을 살려요.","희소성과 기준이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"나연","text":"나는 손수 만든 머리핀을 팔 거야. 세상에 하나뿐이야."},{"who":"민재","text":"나는 바퀴를 고친 중고 자전거를 팔래."},{"who":"나연","text":"값은 얼마로 하고, 홍보 문구는 어떻게 쓸까?"},{"who":"민재","text":"배운 것을 살려서 정해 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#4','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C6',3,'mc','auto','「비 오는 날 젖은 우산을 들고 다니기 불편해요」라는 경험을 바탕으로 한 새 상품 제안으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X10']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"mc","stem":"「비 오는 날 젖은 우산을 들고 다니기 불편해요」라는 경험을 바탕으로 한 새 상품 제안으로 알맞은 것은 무엇인가요?","options":[{"t":"젖은 우산을 따로 넣는 칸이 달린 책가방","correct":true},{"t":"지금 쓰는 우산과 똑같은 우산","mis":"SO4-1-u3-X21"},{"t":"불편과 관계없이 값만 비싼 필통","mis":"SO4-1-u3-X21"},{"t":"광고에서 본 아무 장난감","mis":"SO4-1-u3-X10"}],"explanation":["무엇이 불편했나요?","젖은 우산이에요.","그것을 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#5','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C3',3,'mc','auto','시장 놀이에서 물건을 사는 친구가 합리적으로 고르는 방법은 무엇인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X11','SO4-1-u3-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C3","difficulty":3,"kind":"mc","stem":"시장 놀이에서 물건을 사는 친구가 합리적으로 고르는 방법은 무엇인가요?","options":[{"t":"물건을 직접 살펴보고 판 친구에게 물어보며 값과 품질을 견줘요","correct":true},{"t":"홍보 문구만 보고 바로 사요","mis":"SO4-1-u3-X10"},{"t":"처음 본 가게에서 바로 사요","mis":"SO4-1-u3-X11"},{"t":"가장 비싼 것을 사요","mis":"SO4-1-u3-X06"}],"explanation":["직접 봐요.","물어봐요.","견주고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#6','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C4',3,'ox','auto','착한 소비는 나에게만 좋은 것을 고르는 소비예요.',ARRAY['SO4-1-u3-X16']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"ox","stem":"착한 소비는 나에게만 좋은 것을 고르는 소비예요.","answer":"X","reason_options":[{"t":"사람·동물·환경에 도움이 되는지 함께 생각하는 소비이기 때문에","correct":true},{"t":"착한 소비는 나에게 좋은 것만 따지기 때문에","mis":"SO4-1-u3-X16"}],"mis":"SO4-1-u3-X16","explanation":["나만 생각하나요?","함께 생각해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#7','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C1',3,'mc','auto','주제①을 배우고 알게 된 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u3-X20']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C1","difficulty":3,"kind":"mc","stem":"주제①을 배우고 알게 된 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"원하는 것은 언제나 모두 가질 수 있어요","correct":true},{"t":"자원이 부족해 선택의 문제가 생겨요","mis":"SO4-1-u3-X20"},{"t":"기준을 세워 고르면 후회가 줄어요","mis":"SO4-1-u3-X20"},{"t":"정보는 출처를 확인하고 써요","mis":"SO4-1-u3-X20"}],"explanation":["자원은 부족해요.","다 가질 수 없어요.","알맞지 않은 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#8','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C6',4,'essay','teacher','시장 놀이에서 팔 물건을 하나 정해 값과 홍보 문구를 쓰고, 희소성이나 선택 기준을 어떻게 살렸는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C6","difficulty":4,"kind":"essay","stem":"시장 놀이에서 팔 물건을 하나 정해 값과 홍보 문구를 쓰고, 희소성이나 선택 기준을 어떻게 살렸는지 쓰세요.","answer_guide":{"answer":"예: 직접 그린 그림 엽서를 팔래요. 값은 500원으로 하고, 홍보 문구는 「세상에 단 한 장, 손으로 그린 엽서!」로 정해요. 하나뿐이라는 희소성을 살렸고, 두꺼운 종이라 오래 둘 수 있다는 품질도 함께 알렸어요.","scoring_points":["물건·값·홍보 문구를 썼는가","희소성이나 기준을 살렸는가","부풀리지 않고 사실대로 썼는가"]},"explanation":["물건을 정해요.","값과 문구를 써요.","살린 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#9','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C6',4,'mc','auto','어떤 친구가 낱말 사다리의 ㉡과 ㉢ 사이에 「광고를 그대로 믿기」를 넣었어요. 무엇으로 고쳐야 하나요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X08','SO4-1-u3-X10']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C6","difficulty":4,"kind":"mc","stem":"어떤 친구가 낱말 사다리의 ㉡과 ㉢ 사이에 「광고를 그대로 믿기」를 넣었어요. 무엇으로 고쳐야 하나요?","options":[{"t":"「출처와 정확성을 확인해 정보 찾기」","correct":true},{"t":"「가장 비싼 것 고르기」","mis":"SO4-1-u3-X06"},{"t":"「친구가 고른 대로 따라 하기」","mis":"SO4-1-u3-X08"},{"t":"「고치지 않고 그대로 두기」","mis":"SO4-1-u3-X10"}],"explanation":["광고를 믿으면 안 돼요.","확인해야 해요.","정보 찾기로 고쳐요."],"asset":{"type":"passage","lines":["원하는 것은 많은데 자원이 부족해요. → ㉠","그래서 무엇을 고르고 무엇을 포기할지 고민해요. → ㉡","기준과 정보를 살펴 적은 비용으로 큰 만족을 얻어요. → ㉢","사람·동물·환경에 도움이 되는 것까지 생각해요. → ㉣"],"title":"주제① 낱말 사다리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L06_challenge#10','soc',4,1,'u3','L06','g4_1_soc_u3_L06_challenge','lesson_challenge','SO4-1-u3-C6',4,'essay','teacher','희소성, 선택의 문제, 합리적 선택을 모두 넣어 내 생활의 예를 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C6","difficulty":4,"kind":"essay","stem":"희소성, 선택의 문제, 합리적 선택을 모두 넣어 내 생활의 예를 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 용돈은 정해져 있는데 사고 싶은 것은 많아요. 그래서 공책과 스티커 가운데 무엇을 살지 고민하는 선택의 문제가 생겼어요. 나는 꼭 필요한지 따져 보고 공책을 골라 합리적 선택을 했어요.","scoring_points":["희소성을 넣었는가","선택의 문제를 넣었는가","합리적 선택을 넣었는가"]},"explanation":["부족함을 써요.","고민을 써요.","따져 본 선택을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#1','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',1,'mc','auto','생활에 필요한 물건을 만들거나 생활을 편리하고 즐겁게 해 주는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"mc","stem":"생활에 필요한 물건을 만들거나 생활을 편리하고 즐겁게 해 주는 것을 무엇이라고 하나요?","options":[{"t":"생산","correct":true},{"t":"소비","mis":"SO4-1-u3-X23"},{"t":"저축","mis":"SO4-1-u3-X23"},{"t":"선물","mis":"SO4-1-u3-X23"}],"explanation":["만들어요.","해 주기도 해요.","생산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#2','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',1,'sa','auto','생산한 것을 사거나 이용하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"sa","stem":"생산한 것을 사거나 이용하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["소비"],"explanation":["사요.","이용해요.","소비예요."],"mis":"SO4-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#3','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',1,'ox','auto','㉮ 빵집 주인이 빵을 구워 파는 것은 생산이에요.',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"ox","stem":"㉮ 빵집 주인이 빵을 구워 파는 것은 생산이에요.","answer":"O","reason_options":[{"t":"생활에 필요한 빵을 만들기 때문에","correct":true},{"t":"빵을 파는 사람은 소비를 하기 때문에","mis":"SO4-1-u3-X23"}],"mis":"SO4-1-u3-X23","explanation":["빵을 구워요.","만들어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#4','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',1,'mc','auto','㉯ 손님이 빵을 사 가는 것은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X24','SO4-1-u3-X22']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"mc","stem":"㉯ 손님이 빵을 사 가는 것은 무엇인가요?","options":[{"t":"소비","correct":true},{"t":"생산","mis":"SO4-1-u3-X23"},{"t":"생산도 소비도 아님","mis":"SO4-1-u3-X24"},{"t":"편리하게 해 주는 생산","mis":"SO4-1-u3-X22"}],"explanation":["손님이에요.","빵을 사요.","소비예요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#5','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',2,'mc','auto','㉰ 미용사가 머리를 다듬어 주는 것은 무엇인가요?',ARRAY['SO4-1-u3-X22','SO4-1-u3-X23']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"mc","stem":"㉰ 미용사가 머리를 다듬어 주는 것은 무엇인가요?","options":[{"t":"생산 — 생활을 편리하게 해 주기 때문에","correct":true},{"t":"소비 — 물건을 만들지 않았기 때문에","mis":"SO4-1-u3-X22"},{"t":"생산이 아님 — 눈에 보이는 물건이 없기 때문에","mis":"SO4-1-u3-X22"},{"t":"소비 — 돈을 받기 때문에","mis":"SO4-1-u3-X23"}],"explanation":["머리를 다듬어 줘요.","편리하게 해 줘요.","생산이에요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#6','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',2,'mc','auto','시장에서 생산과 소비를 함께 볼 수 있는 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X24']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"mc","stem":"시장에서 생산과 소비를 함께 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"파는 사람과 사는 사람이 한곳에 모이기 때문에","correct":true},{"t":"사는 사람만 모이기 때문에","mis":"SO4-1-u3-X24"},{"t":"파는 사람만 모이기 때문에","mis":"SO4-1-u3-X24"},{"t":"물건을 공짜로 나누기 때문에","mis":"SO4-1-u3-X24"}],"explanation":["파는 쪽이 있어요.","사는 쪽도 있어요.","함께 일어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#7','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',2,'ox','auto','㉲ 가수의 노래는 물건이 아니니 생산이 아니에요.',ARRAY['SO4-1-u3-X22']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"ox","stem":"㉲ 가수의 노래는 물건이 아니니 생산이 아니에요.","answer":"X","reason_options":[{"t":"사람들의 생활을 즐겁게 해 주는 것도 생산이기 때문에","correct":true},{"t":"눈에 보이는 물건을 만들어야만 생산이기 때문에","mis":"SO4-1-u3-X22"}],"mis":"SO4-1-u3-X22","explanation":["노래는 물건이 아니에요.","즐겁게 해 줘요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#8','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',2,'match','auto','장터의 모습과 알맞은 활동을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"match","stem":"장터의 모습과 알맞은 활동을 이으세요.","pairs":[{"l":"㉰ 미용사가 머리를 다듬어 준다","r":"생산"},{"l":"㉱ 손님이 머리 손질을 받는다","r":"소비"}],"mis":"SO4-1-u3-X23","explanation":["해 주는 쪽이에요.","받는 쪽이에요.","생산과 소비예요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#9','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',2,'blank','auto','생산이 있어야 소비할 수 있고, 소비가 있어야 생산을 이어 갈 수 있어요. 생산과 소비는 서로 (    ) 활동이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X24','SO4-1-u3-X23']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"blank","stem":"생산이 있어야 소비할 수 있고, 소비가 있어야 생산을 이어 갈 수 있어요. 생산과 소비는 서로 (    ) 활동이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"이어진","correct":true},{"t":"관계없는","mis":"SO4-1-u3-X24"},{"t":"똑같은","mis":"SO4-1-u3-X23"},{"t":"다투는","mis":"SO4-1-u3-X24"}],"explanation":["생산이 있어야 소비해요.","소비가 있어야 생산해요.","이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_basic#10','soc',4,1,'u3','L07','g4_1_soc_u3_L07_basic','lesson_basic','SO4-1-u3-C7',3,'mc','auto','생산과 소비가 짝을 이루는 것은 무엇인가요?',ARRAY['SO4-1-u3-X24','SO4-1-u3-X23']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C7","difficulty":3,"kind":"mc","stem":"생산과 소비가 짝을 이루는 것은 무엇인가요?","options":[{"t":"진료하는 의사와 진료받는 사람","correct":true},{"t":"빵을 굽는 주인과 옆 가게에서 빵을 굽는 주인","mis":"SO4-1-u3-X24"},{"t":"빵을 사는 손님과 머리 손질을 받는 손님","mis":"SO4-1-u3-X23"},{"t":"혼자 공원을 산책하는 사람","mis":"SO4-1-u3-X24"}],"explanation":["해 주는 쪽을 찾아요.","받는 쪽도 찾아요.","의사와 환자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#1','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',2,'mc','auto','물건을 만들지 않고 생활을 편리하고 즐겁게 해 주는 일을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"mc","stem":"물건을 만들지 않고 생활을 편리하고 즐겁게 해 주는 일을 무엇이라고 하나요?","options":[{"t":"서비스","correct":true},{"t":"소비","mis":"SO4-1-u3-X23"},{"t":"공장 생산","mis":"SO4-1-u3-X22"},{"t":"저축","mis":"SO4-1-u3-X22"}],"explanation":["물건은 없어요.","해 주는 일이에요.","서비스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#2','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',2,'ox','auto','버스를 타고 요금을 내는 것은 소비예요.',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"ox","stem":"버스를 타고 요금을 내는 것은 소비예요.","answer":"O","reason_options":[{"t":"운전해 주는 서비스를 이용하는 것이기 때문에","correct":true},{"t":"버스를 타는 것은 생산이기 때문에","mis":"SO4-1-u3-X23"}],"mis":"SO4-1-u3-X23","explanation":["버스를 타요.","이용해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#3','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',3,'error','auto','장터의 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X22','SO4-1-u3-X24']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C7","difficulty":3,"kind":"error","stem":"장터의 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉳ 공연을 보는 사람들은 생산을 하고 있어.」","correct":true,"mis_target":"SO4-1-u3-X23"},{"t":"친구 가 — 「㉲는 즐겁게 해 주는 생산이야.」","mis":"SO4-1-u3-X22"},{"t":"친구 다 — 「㉮와 ㉯는 짝을 이뤄.」","mis":"SO4-1-u3-X24"}],"explanation":["공연을 봐요.","이용하는 쪽이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
