INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#6','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',3,'ox','auto','빵을 사는 사람이 아무도 없으면 빵집은 생산을 이어 가기 어려워요.',ARRAY['SO4-1-u3-X24']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C7","difficulty":3,"kind":"ox","stem":"빵을 사는 사람이 아무도 없으면 빵집은 생산을 이어 가기 어려워요.","answer":"O","reason_options":[{"t":"생산과 소비는 서로 이어진 활동이기 때문에","correct":true},{"t":"생산과 소비는 서로 관계없기 때문에","mis":"SO4-1-u3-X24"}],"mis":"SO4-1-u3-X24","explanation":["사는 사람이 없어요.","빵을 팔 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#7','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',3,'mc','auto','한 사람이 생산도 하고 소비도 하는 것을 바르게 보여 준 것은 무엇인가요?',ARRAY['SO4-1-u3-X24','SO4-1-u3-X23','SO4-1-u3-X22']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C7","difficulty":3,"kind":"mc","stem":"한 사람이 생산도 하고 소비도 하는 것을 바르게 보여 준 것은 무엇인가요?","options":[{"t":"빵집 주인이 낮에는 빵을 팔고, 저녁에는 미용실에서 머리 손질을 받아요","correct":true},{"t":"사람은 생산만 하거나 소비만 할 수 있어요","mis":"SO4-1-u3-X24"},{"t":"빵집 주인은 소비를 할 수 없어요","mis":"SO4-1-u3-X23"},{"t":"미용사는 생산을 할 수 없어요","mis":"SO4-1-u3-X22"}],"explanation":["낮에는 팔아요.","저녁에는 받아요.","둘 다 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#8','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',4,'essay','teacher','생산과 소비의 뜻을 쓰고, 장터의 모습에서 생산과 소비의 예를 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C7","difficulty":4,"kind":"essay","stem":"생산과 소비의 뜻을 쓰고, 장터의 모습에서 생산과 소비의 예를 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 생산은 물건을 만들거나 생활을 편리하고 즐겁게 해 주는 것이고, 소비는 생산한 것을 사거나 이용하는 것이에요. ㉰ 미용사가 머리를 다듬어 주는 것은 생산이고, ㉱ 손님이 머리 손질을 받는 것은 소비예요.","scoring_points":["생산의 뜻을 썼는가","소비의 뜻을 썼는가","예를 하나씩 바르게 찾았는가"]},"explanation":["뜻을 써요.","예를 찾아요.","짝지어 써요."],"asset":{"type":"passage","lines":["㉮ 빵집 주인이 빵을 구워 판다.","㉯ 손님이 빵을 사 간다.","㉰ 미용사가 손님의 머리를 다듬어 준다.","㉱ 손님이 머리 손질을 받는다.","㉲ 가수가 장터 무대에서 노래를 부른다.","㉳ 사람들이 공연을 보며 즐긴다."],"title":"물결시 장터의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#9','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',4,'mc','auto','놀이공원에서 일어나는 생산과 소비를 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X22']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C7","difficulty":4,"kind":"mc","stem":"놀이공원에서 일어나는 생산과 소비를 바르게 말한 것은 무엇인가요?","options":[{"t":"놀이 기구를 운행해 주는 것은 생산, 표를 사서 타는 것은 소비예요","correct":true},{"t":"놀이 기구를 운행해 주는 것은 소비, 표를 사서 타는 것은 생산이에요","mis":"SO4-1-u3-X23"},{"t":"둘 다 소비예요","mis":"SO4-1-u3-X22"},{"t":"놀이라서 생산도 소비도 아니에요","mis":"SO4-1-u3-X22"}],"explanation":["운행해 줘요.","타며 이용해요.","생산과 소비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L07_challenge#10','soc',4,1,'u3','L07','g4_1_soc_u3_L07_challenge','lesson_challenge','SO4-1-u3-C7',4,'essay','teacher','오늘 하루 내가 한 소비 두 가지를 쓰고, 그 소비와 이어진 생산을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C7","difficulty":4,"kind":"essay","stem":"오늘 하루 내가 한 소비 두 가지를 쓰고, 그 소비와 이어진 생산을 하나씩 쓰세요.","answer_guide":{"answer":"예: 아침에 우유를 마셨어요. 이 우유는 목장에서 소를 기르고 공장에서 우유를 만든 생산과 이어져요. 학교에 갈 때 버스를 탔어요. 이것은 버스 기사님이 운전해 주는 생산과 이어져요.","scoring_points":["소비 두 가지를 썼는가","이어진 생산을 썼는가","생산과 소비가 이어진다는 것을 드러냈는가"]},"explanation":["하루를 떠올려요.","소비를 찾아요.","생산과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#1','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',1,'mc','auto','생산 활동은 크게 몇 가지 종류로 나눌 수 있나요?',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"mc","stem":"생산 활동은 크게 몇 가지 종류로 나눌 수 있나요?","options":[{"t":"세 가지","correct":true},{"t":"두 가지","mis":"SO4-1-u3-X25"},{"t":"네 가지","mis":"SO4-1-u3-X25"},{"t":"한 가지","mis":"SO4-1-u3-X25"}],"explanation":["자연에서 얻기예요.","만들기, 해 주기도 있어요.","세 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#2','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',1,'sa','auto','진료·공연·배달처럼 생활을 편리하고 즐겁게 해 주는 생산을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"sa","stem":"진료·공연·배달처럼 생활을 편리하고 즐겁게 해 주는 생산을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["서비스"],"explanation":["물건은 아니에요.","해 주는 일이에요.","서비스예요."],"mis":"SO4-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#3','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',1,'ox','auto','산에서 버섯을 따는 것은 자연에서 얻는 생산 활동이에요.',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"ox","stem":"산에서 버섯을 따는 것은 자연에서 얻는 생산 활동이에요.","answer":"O","reason_options":[{"t":"자연에서 필요한 것을 바로 얻기 때문에","correct":true},{"t":"버섯 따기는 물건을 만드는 활동이기 때문에","mis":"SO4-1-u3-X25"}],"mis":"SO4-1-u3-X25","explanation":["산에서 따요.","자연에서 얻어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#4','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',1,'mc','auto','필요한 것을 만드는 생산 활동은 무엇인가요?',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"mc","stem":"필요한 것을 만드는 생산 활동은 무엇인가요?","options":[{"t":"빵 만들기","correct":true},{"t":"벼농사","mis":"SO4-1-u3-X25"},{"t":"진료","mis":"SO4-1-u3-X25"},{"t":"고기잡이","mis":"SO4-1-u3-X25"}],"explanation":["없던 것을 만들어요.","빵을 만들어요.","만드는 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#5','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',2,'mc','auto','자연에서 얻는 생산 활동끼리 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X22']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"mc","stem":"자연에서 얻는 생산 활동끼리 묶은 것은 무엇인가요?","options":[{"t":"㉮ · ㉯ · ㉰","correct":true},{"t":"㉱ · ㉲","mis":"SO4-1-u3-X25"},{"t":"㉳ · ㉴","mis":"SO4-1-u3-X22"},{"t":"㉮ · ㉱ · ㉳","mis":"SO4-1-u3-X25"}],"explanation":["논·바다·산이에요.","자연에서 얻어요.","㉮·㉯·㉰예요."],"asset":{"type":"passage","lines":["㉮ 너른들군 — 논에서 벼농사를 짓는다.","㉯ 물결시 — 바다에서 고기를 잡는다.","㉰ 구름군 — 산에서 버섯을 딴다.","㉱ 별가람시 — 공장에서 옷을 만든다.","㉲ 목수가 마을 회관을 짓는다.","㉳ 택배 기사가 물건을 집까지 배달한다.","㉴ 의사가 아픈 사람을 진료한다."],"title":"여러 지역의 생산 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#6','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',2,'mc','auto','㉳ 택배 배달은 어떤 생산 활동인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X22']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"mc","stem":"㉳ 택배 배달은 어떤 생산 활동인가요?","options":[{"t":"편리하게 해 주는 활동","correct":true},{"t":"만드는 활동","mis":"SO4-1-u3-X25"},{"t":"자연에서 얻는 활동","mis":"SO4-1-u3-X25"},{"t":"생산이 아닌 활동","mis":"SO4-1-u3-X22"}],"explanation":["물건을 옮겨 줘요.","편리해져요.","해 주는 활동이에요."],"asset":{"type":"passage","lines":["㉮ 너른들군 — 논에서 벼농사를 짓는다.","㉯ 물결시 — 바다에서 고기를 잡는다.","㉰ 구름군 — 산에서 버섯을 딴다.","㉱ 별가람시 — 공장에서 옷을 만든다.","㉲ 목수가 마을 회관을 짓는다.","㉳ 택배 기사가 물건을 집까지 배달한다.","㉴ 의사가 아픈 사람을 진료한다."],"title":"여러 지역의 생산 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#7','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',2,'ox','auto','슈퍼마켓에서 채소를 사는 것은 생산 활동이에요.',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"ox","stem":"슈퍼마켓에서 채소를 사는 것은 생산 활동이에요.","answer":"X","reason_options":[{"t":"생산한 채소를 사는 것은 소비 활동이기 때문에","correct":true},{"t":"채소를 고르는 것도 만드는 활동이기 때문에","mis":"SO4-1-u3-X23"}],"mis":"SO4-1-u3-X23","explanation":["채소를 사요.","사는 것은 소비예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#8','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',2,'match','auto','생산 활동과 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"match","stem":"생산 활동과 종류를 알맞게 이으세요.","pairs":[{"l":"벼농사","r":"자연에서 얻는 활동"},{"l":"건물 짓기","r":"만드는 활동"},{"l":"진료","r":"편리하게 해 주는 활동"}],"mis":"SO4-1-u3-X25","explanation":["논에서 얻어요.","지어서 만들어요.","돌봐 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#9','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',2,'blank','auto','내가 하는 소비는 누군가의 (    )과 이어져 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X24']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"blank","stem":"내가 하는 소비는 누군가의 (    )과 이어져 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"생산","correct":true},{"t":"소비","mis":"SO4-1-u3-X23"},{"t":"저축","mis":"SO4-1-u3-X24"},{"t":"놀이","mis":"SO4-1-u3-X24"}],"explanation":["누가 만들었나요?","누가 해 주었나요?","생산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_basic#10','soc',4,1,'u3','L08','g4_1_soc_u3_L08_basic','lesson_basic','SO4-1-u3-C8',3,'mc','auto','같은 종류의 생산 활동끼리 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"같은 종류의 생산 활동끼리 묶은 것은 무엇인가요?","options":[{"t":"고기잡이 · 버섯 따기","correct":true},{"t":"고기잡이 · 옷 만들기","mis":"SO4-1-u3-X25"},{"t":"공연 · 건물 짓기","mis":"SO4-1-u3-X25"},{"t":"배달 · 벼농사","mis":"SO4-1-u3-X25"}],"explanation":["어디서 얻나요?","바다와 산이에요.","자연에서 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#1','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',2,'mc','auto','소비 활동은 무엇인가요?',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"mc","stem":"소비 활동은 무엇인가요?","options":[{"t":"버스를 타요","correct":true},{"t":"벼농사를 지어요","mis":"SO4-1-u3-X23"},{"t":"옷을 만들어요","mis":"SO4-1-u3-X23"},{"t":"공연을 해요","mis":"SO4-1-u3-X23"}],"explanation":["이용하는 쪽을 찾아요.","버스를 타요.","소비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#2','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',2,'ox','auto','㉲ 목수가 마을 회관을 짓는 것은 만드는 활동이에요.',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"ox","stem":"㉲ 목수가 마을 회관을 짓는 것은 만드는 활동이에요.","answer":"O","reason_options":[{"t":"없던 건물을 지어 만들어 내기 때문에","correct":true},{"t":"집 짓기는 자연에서 얻는 활동이기 때문에","mis":"SO4-1-u3-X25"}],"mis":"SO4-1-u3-X25","explanation":["회관을 지어요.","만들어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 너른들군 — 논에서 벼농사를 짓는다.","㉯ 물결시 — 바다에서 고기를 잡는다.","㉰ 구름군 — 산에서 버섯을 딴다.","㉱ 별가람시 — 공장에서 옷을 만든다.","㉲ 목수가 마을 회관을 짓는다.","㉳ 택배 기사가 물건을 집까지 배달한다.","㉴ 의사가 아픈 사람을 진료한다."],"title":"여러 지역의 생산 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#3','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',3,'error','auto','여러 지역의 생산 활동을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X22']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"error","stem":"여러 지역의 생산 활동을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉯ 고기잡이는 물건을 만드는 활동이야.」","correct":true,"mis_target":"SO4-1-u3-X25"},{"t":"친구 가 — 「㉴ 진료도 생산이야.」","mis":"SO4-1-u3-X22"},{"t":"친구 나 — 「㉱는 만드는 활동이야.」","mis":"SO4-1-u3-X25"}],"explanation":["바다에서 잡아요.","자연에서 얻어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 너른들군 — 논에서 벼농사를 짓는다.","㉯ 물결시 — 바다에서 고기를 잡는다.","㉰ 구름군 — 산에서 버섯을 딴다.","㉱ 별가람시 — 공장에서 옷을 만든다.","㉲ 목수가 마을 회관을 짓는다.","㉳ 택배 기사가 물건을 집까지 배달한다.","㉴ 의사가 아픈 사람을 진료한다."],"title":"여러 지역의 생산 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#4','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',3,'mc','auto','자연에서 얻은 것으로 무엇인가를 만드는 활동은 무엇인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X23','SO4-1-u3-X22']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"자연에서 얻은 것으로 무엇인가를 만드는 활동은 무엇인가요?","options":[{"t":"쌀로 떡을 만들어요","correct":true},{"t":"논에서 벼를 길러요","mis":"SO4-1-u3-X25"},{"t":"가게에서 떡을 사 먹어요","mis":"SO4-1-u3-X23"},{"t":"떡 가게까지 길을 안내해 줘요","mis":"SO4-1-u3-X22"}],"explanation":["쌀은 자연에서 얻었어요.","떡을 만들어요.","만드는 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#5','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',3,'mc','auto','편리하고 즐겁게 해 주는 생산이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X22']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"편리하고 즐겁게 해 주는 생산이 아닌 것은 무엇인가요?","options":[{"t":"공장에서 신발을 만들어요","correct":true},{"t":"아픈 사람을 진료해요","mis":"SO4-1-u3-X22"},{"t":"물건을 배달해요","mis":"SO4-1-u3-X22"},{"t":"머리를 다듬어 줘요","mis":"SO4-1-u3-X22"}],"explanation":["물건이 생기나요?","신발이 생겨요.","만드는 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#6','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',3,'ox','auto','우리 생활은 많은 생산 활동 덕분에 이뤄지고, 생산은 소비로 이어져요.',ARRAY['SO4-1-u3-X24']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"ox","stem":"우리 생활은 많은 생산 활동 덕분에 이뤄지고, 생산은 소비로 이어져요.","answer":"O","reason_options":[{"t":"누군가 생산한 것을 우리가 사서 쓰거나 이용하기 때문에","correct":true},{"t":"생산과 소비는 서로 관계없기 때문에","mis":"SO4-1-u3-X24"}],"mis":"SO4-1-u3-X24","explanation":["누가 만들었나요?","우리가 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#7','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',3,'mc','auto','떡 한 접시가 우리에게 오기까지 「벼농사 → 떡 만들기 → 배달 → 사 먹기」를 거쳐요. 이 가운데 소비는 무엇인가요?',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"떡 한 접시가 우리에게 오기까지 「벼농사 → 떡 만들기 → 배달 → 사 먹기」를 거쳐요. 이 가운데 소비는 무엇인가요?","options":[{"t":"사 먹기","correct":true},{"t":"벼농사","mis":"SO4-1-u3-X23"},{"t":"떡 만들기","mis":"SO4-1-u3-X23"},{"t":"배달","mis":"SO4-1-u3-X23"}],"explanation":["사는 쪽을 찾아요.","사 먹어요.","소비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#8','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',4,'essay','teacher','생산 활동의 세 종류를 쓰고, 우리 주변에서 볼 수 있는 예를 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C8","difficulty":4,"kind":"essay","stem":"생산 활동의 세 종류를 쓰고, 우리 주변에서 볼 수 있는 예를 하나씩 쓰세요.","answer_guide":{"answer":"예: 자연에서 얻는 활동으로는 바다에서 고기를 잡는 일이 있어요. 만드는 활동으로는 빵집에서 빵을 만드는 일이 있어요. 편리하고 즐겁게 해 주는 활동으로는 택배 기사님이 물건을 배달해 주는 일이 있어요.","scoring_points":["세 종류를 썼는가","종류마다 예를 들었는가","예가 종류에 알맞은가"]},"explanation":["세 종류를 떠올려요.","예를 찾아요.","짝지어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#9','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',4,'mc','auto','너른들군의 한 어른이 아침에는 논에서 벼를 돌보고, 오후에는 가게에서 운동화를 사고, 저녁에는 학원 버스를 운전했어요. 차례대로 바르게 나타낸 것은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X25','SO4-1-u3-X22']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C8","difficulty":4,"kind":"mc","stem":"너른들군의 한 어른이 아침에는 논에서 벼를 돌보고, 오후에는 가게에서 운동화를 사고, 저녁에는 학원 버스를 운전했어요. 차례대로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"자연에서 얻는 생산 → 소비 → 편리하게 해 주는 생산","correct":true},{"t":"자연에서 얻는 생산 → 만드는 생산 → 소비","mis":"SO4-1-u3-X23"},{"t":"만드는 생산 → 소비 → 만드는 생산","mis":"SO4-1-u3-X25"},{"t":"자연에서 얻는 생산 → 소비 → 소비","mis":"SO4-1-u3-X22"}],"explanation":["벼를 돌봐요.","운동화를 사요.","버스를 운전해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L08_challenge#10','soc',4,1,'u3','L08','g4_1_soc_u3_L08_challenge','lesson_challenge','SO4-1-u3-C8',4,'essay','teacher','택배 배달이 생산인 까닭을 쓰고, 배달과 이어진 소비의 예를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C8","difficulty":4,"kind":"essay","stem":"택배 배달이 생산인 까닭을 쓰고, 배달과 이어진 소비의 예를 쓰세요.","answer_guide":{"answer":"예: 택배 기사님은 물건을 만들지는 않지만 필요한 물건을 집까지 옮겨 주어 생활을 편리하게 해 주니 생산이에요. 우리 가족이 주문한 책을 받아 읽는 것은 이 배달과 이어진 소비예요.","scoring_points":["배달이 생산인 까닭을 썼는가","편리하게 해 준다는 것을 드러냈는가","이어진 소비의 예를 썼는가"]},"explanation":["물건을 만드나요?","편리하게 해 줘요.","소비와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#1','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',1,'mc','auto','지역끼리 서로 필요한 것을 주고받는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X27']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"mc","stem":"지역끼리 서로 필요한 것을 주고받는 것을 무엇이라고 하나요?","options":[{"t":"교류","correct":true},{"t":"소비","mis":"SO4-1-u3-X27"},{"t":"생산","mis":"SO4-1-u3-X27"},{"t":"선택","mis":"SO4-1-u3-X27"}],"explanation":["서로 줘요.","서로 받아요.","교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#2','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',1,'sa','auto','지역들이 서로 의지하며 함께 살아가는 것을 상호 ○○이라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"sa","stem":"지역들이 서로 의지하며 함께 살아가는 것을 상호 ○○이라고 해요. 두 글자로 쓰세요.","answer":["의존"],"explanation":["서로 기대요.","함께 살아가요.","상호 의존이에요."],"mis":"SO4-1-u3-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#3','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',1,'ox','auto','지역마다 자연환경과 생산 기술이 달라서 잘 나는 것이 서로 달라요.',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"ox","stem":"지역마다 자연환경과 생산 기술이 달라서 잘 나는 것이 서로 달라요.","answer":"O","reason_options":[{"t":"땅·날씨·바다와 기술에 따라 잘 나는 것이 달라지기 때문에","correct":true},{"t":"지역 이름이 다르기 때문에","mis":"SO4-1-u3-X26"}],"mis":"SO4-1-u3-X26","explanation":["땅과 날씨가 달라요.","기술도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#4','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',1,'mc','auto','김밥의 김은 어느 지역에서 왔나요?',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"mc","stem":"김밥의 김은 어느 지역에서 왔나요?","options":[{"t":"물결시","correct":true},{"t":"너른들군","mis":"SO4-1-u3-X26"},{"t":"구름군","mis":"SO4-1-u3-X26"},{"t":"별가람시","mis":"SO4-1-u3-X26"}],"explanation":["김은 바다에서 나요.","바다가 가까워요.","물결시예요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#5','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',2,'mc','auto','김밥 한 줄의 재료가 온 곳으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X27','SO4-1-u3-X26']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"mc","stem":"김밥 한 줄의 재료가 온 곳으로 알 수 있는 것은 무엇인가요?","options":[{"t":"여러 지역의 재료가 교류로 모였어요","correct":true},{"t":"재료가 모두 한 지역에서 났어요","mis":"SO4-1-u3-X27"},{"t":"재료는 모두 바다에서 났어요","mis":"SO4-1-u3-X26"},{"t":"김밥은 교류와 관계없어요","mis":"SO4-1-u3-X27"}],"explanation":["네 지역이에요.","재료가 모였어요.","교류 덕분이에요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#6','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',2,'mc','auto','우리 지역에서 나지 않는 것이 필요할 때 어떻게 하나요?',ARRAY['SO4-1-u3-X27','SO4-1-u3-X28']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"mc","stem":"우리 지역에서 나지 않는 것이 필요할 때 어떻게 하나요?","options":[{"t":"그것이 잘 나는 다른 지역과 교류해 얻어요","correct":true},{"t":"없으면 그냥 지내요","mis":"SO4-1-u3-X27"},{"t":"우리 지역에서 억지로 모두 만들어요","mis":"SO4-1-u3-X27"},{"t":"다른 지역은 나눠 줄 수 없어요","mis":"SO4-1-u3-X28"}],"explanation":["우리 지역에 없어요.","다른 지역에 있어요.","교류해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#7','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',2,'ox','auto','물결시와 구름군이 교류하면 물결시만 이로워요.',ARRAY['SO4-1-u3-X28']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"ox","stem":"물결시와 구름군이 교류하면 물결시만 이로워요.","answer":"X","reason_options":[{"t":"두 지역 모두 필요한 것을 얻어 이롭기 때문에","correct":true},{"t":"주는 지역은 손해를 보기 때문에","mis":"SO4-1-u3-X28"}],"mis":"SO4-1-u3-X28","explanation":["물결시는 과일을 얻어요.","구름군은 생선을 얻어요.","그래서 X예요."],"asset":{"type":"passage","lines":["물결시 — 바다가 있어 생선이 많이 나지만, 과일은 잘 나지 않는다.","구름군 — 산과 밭이 많아 버섯과 과일이 잘 나지만, 바다가 없다."],"title":"두 지역 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#8','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',2,'match','auto','지역과 잘 나는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"match","stem":"지역과 잘 나는 것을 알맞게 이으세요.","pairs":[{"l":"물결시","r":"생선"},{"l":"구름군","r":"버섯과 과일"}],"mis":"SO4-1-u3-X26","explanation":["바다가 있어요.","산과 밭이 있어요.","자연환경이 달라요."],"asset":{"type":"passage","lines":["물결시 — 바다가 있어 생선이 많이 나지만, 과일은 잘 나지 않는다.","구름군 — 산과 밭이 많아 버섯과 과일이 잘 나지만, 바다가 없다."],"title":"두 지역 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#9','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',2,'blank','auto','지역들은 교류로 서로 도움을 주고받으며 함께 (    )해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X33']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"blank","stem":"지역들은 교류로 서로 도움을 주고받으며 함께 (    )해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"발전","correct":true},{"t":"손해","mis":"SO4-1-u3-X28"},{"t":"다툼","mis":"SO4-1-u3-X28"},{"t":"고립","mis":"SO4-1-u3-X33"}],"explanation":["서로 도와요.","함께 나아가요.","발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_basic#10','soc',4,1,'u3','L09','g4_1_soc_u3_L09_basic','lesson_basic','SO4-1-u3-C9',3,'mc','auto','교류가 하나도 없다면 너른들군 사람들이 만들 수 있는 김밥은 어떤 모습일까요?',ARRAY['SO4-1-u3-X27','SO4-1-u3-X26']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"mc","stem":"교류가 하나도 없다면 너른들군 사람들이 만들 수 있는 김밥은 어떤 모습일까요?","options":[{"t":"쌀밥은 있지만 김·햄·버섯이 없는 김밥","correct":true},{"t":"지금과 똑같은 김밥","mis":"SO4-1-u3-X27"},{"t":"재료가 더 많은 김밥","mis":"SO4-1-u3-X27"},{"t":"김만 있고 밥이 없는 김밥","mis":"SO4-1-u3-X26"}],"explanation":["너른들군은 쌀이 나요.","다른 재료는 없어요.","쌀밥만 남아요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#1','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',2,'mc','auto','상호 의존을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X27']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"mc","stem":"상호 의존을 바르게 말한 것은 무엇인가요?","options":[{"t":"지역들이 서로 의지하며 함께 살아가는 것","correct":true},{"t":"한 지역이 혼자서 살아가는 것","mis":"SO4-1-u3-X33"},{"t":"한 지역만 다른 지역에 기대는 것","mis":"SO4-1-u3-X33"},{"t":"지역끼리 아무것도 주고받지 않는 것","mis":"SO4-1-u3-X27"}],"explanation":["서로예요.","의지해요.","함께 살아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#2','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',2,'ox','auto','햄이 별가람시에서 온 것처럼, 물건을 만드는 기술도 지역마다 달라요.',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"ox","stem":"햄이 별가람시에서 온 것처럼, 물건을 만드는 기술도 지역마다 달라요.","answer":"O","reason_options":[{"t":"지역마다 생산 기술이 달라 잘 만드는 것이 다르기 때문에","correct":true},{"t":"지역마다 다른 것은 날씨뿐이기 때문에","mis":"SO4-1-u3-X26"}],"mis":"SO4-1-u3-X26","explanation":["공장이 많아요.","만드는 기술이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#3','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',3,'error','auto','두 지역을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X27','SO4-1-u3-X28','SO4-1-u3-X26']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"error","stem":"두 지역을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「구름군은 바다가 없으니 생선을 먹을 방법이 없어.」","correct":true,"mis_target":"SO4-1-u3-X27"},{"t":"친구 나 — 「두 지역은 서로 필요한 것을 줄 수 있어.」","mis":"SO4-1-u3-X28"},{"t":"친구 다 — 「바다와 산 때문에 잘 나는 것이 달라.」","mis":"SO4-1-u3-X26"}],"explanation":["생선은 물결시에 있어요.","교류하면 얻어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["물결시 — 바다가 있어 생선이 많이 나지만, 과일은 잘 나지 않는다.","구름군 — 산과 밭이 많아 버섯과 과일이 잘 나지만, 바다가 없다."],"title":"두 지역 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#4','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',3,'mc','auto','바닷가 지역의 생선과 산골 지역의 버섯을 서로 주고받으면 어떻게 되나요?',ARRAY['SO4-1-u3-X28']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"mc","stem":"바닷가 지역의 생선과 산골 지역의 버섯을 서로 주고받으면 어떻게 되나요?","options":[{"t":"두 지역 모두 필요한 것을 얻어 이로워요","correct":true},{"t":"바닷가 지역만 이로워요","mis":"SO4-1-u3-X28"},{"t":"산골 지역만 이로워요","mis":"SO4-1-u3-X28"},{"t":"두 지역 모두 손해를 봐요","mis":"SO4-1-u3-X28"}],"explanation":["서로 줘요.","서로 받아요.","모두 이로워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#5','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',3,'mc','auto','지역마다 잘 나는 것이 다른 까닭으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"mc","stem":"지역마다 잘 나는 것이 다른 까닭으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"지역 이름의 글자 수가 달라서","correct":true},{"t":"땅의 생김새가 달라서","mis":"SO4-1-u3-X26"},{"t":"날씨가 달라서","mis":"SO4-1-u3-X26"},{"t":"생산 기술이 달라서","mis":"SO4-1-u3-X26"}],"explanation":["자연환경을 떠올려요.","기술도 떠올려요.","이름은 까닭이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#6','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',3,'ox','auto','지역들이 교류하면 서로 의지하게 되어 함께 발전할 수 있어요.',ARRAY['SO4-1-u3-X28']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"ox","stem":"지역들이 교류하면 서로 의지하게 되어 함께 발전할 수 있어요.","answer":"O","reason_options":[{"t":"서로 부족한 것을 채워 주며 함께 나아가기 때문에","correct":true},{"t":"교류하면 한 지역만 앞서고 다른 지역은 뒤처지기 때문에","mis":"SO4-1-u3-X28"}],"mis":"SO4-1-u3-X28","explanation":["부족함을 채워요.","서로 의지해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#7','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',3,'mc','auto','구름군에서 버섯이 잘 나는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":3,"kind":"mc","stem":"구름군에서 버섯이 잘 나는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"산이 많고 날씨가 서늘한 자연환경 때문이에요","correct":true},{"t":"사람이 많이 살기 때문이에요","mis":"SO4-1-u3-X26"},{"t":"가게가 많기 때문이에요","mis":"SO4-1-u3-X26"},{"t":"이름이 구름군이기 때문이에요","mis":"SO4-1-u3-X26"}],"explanation":["산이 많아요.","날씨가 서늘해요.","자연환경이에요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#8','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',4,'essay','teacher','김밥 재료가 온 곳을 예로 들어, 지역 간 교류가 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C9","difficulty":4,"kind":"essay","stem":"김밥 재료가 온 곳을 예로 들어, 지역 간 교류가 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 김밥의 쌀은 너른들군, 김은 물결시, 버섯은 구름군, 햄은 별가람시에서 왔어요. 지역마다 자연환경과 생산 기술이 달라 잘 나는 것이 다르고, 한 지역이 모두 만들 수 없어요. 그래서 서로 필요한 것을 주고받는 교류가 필요해요.","scoring_points":["김밥 재료를 예로 들었는가","잘 나는 것이 다른 까닭을 썼는가","한 지역이 모두 만들 수 없음을 썼는가"]},"explanation":["재료를 떠올려요.","까닭을 찾아요.","교류와 이어요."],"asset":{"type":"passage","lines":["쌀 — 너른들군(넓은 들판에서 벼가 잘 자란다)","김·어묵 — 물결시(바다가 가깝다)","버섯·당근 — 구름군(산이 많고 날씨가 서늘하다)","햄 — 별가람시(먹을거리를 만드는 공장이 많다)"],"title":"김밥 한 줄의 재료가 온 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#9','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',4,'mc','auto','구름군에 큰비가 와서 버섯 밭이 망가졌어요. 물결시 사람들에게는 어떤 일이 생길 수 있나요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X28','SO4-1-u3-X27']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C9","difficulty":4,"kind":"mc","stem":"구름군에 큰비가 와서 버섯 밭이 망가졌어요. 물결시 사람들에게는 어떤 일이 생길 수 있나요?","options":[{"t":"버섯을 구하기 어려워져요 — 두 지역이 서로 의존하기 때문이에요","correct":true},{"t":"아무 일도 없어요 — 물결시와 구름군은 관계없기 때문이에요","mis":"SO4-1-u3-X33"},{"t":"버섯을 더 많이 얻어요 — 구름군이 손해를 보기 때문이에요","mis":"SO4-1-u3-X28"},{"t":"물결시가 버섯을 혼자 다 만들 수 있어요 — 한 지역이 모두 만들 수 있기 때문이에요","mis":"SO4-1-u3-X27"}],"explanation":["버섯은 구름군에서 와요.","구름군이 어려워요.","물결시도 영향을 받아요."],"asset":{"type":"passage","lines":["물결시 — 바다가 있어 생선이 많이 나지만, 과일은 잘 나지 않는다.","구름군 — 산과 밭이 많아 버섯과 과일이 잘 나지만, 바다가 없다."],"title":"두 지역 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L09_challenge#10','soc',4,1,'u3','L09','g4_1_soc_u3_L09_challenge','lesson_challenge','SO4-1-u3-C9',4,'essay','teacher','상호 의존의 뜻을 쓰고, 우리 생활에서 다른 지역과 서로 의지하는 예를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C9","difficulty":4,"kind":"essay","stem":"상호 의존의 뜻을 쓰고, 우리 생활에서 다른 지역과 서로 의지하는 예를 쓰세요.","answer_guide":{"answer":"예: 상호 의존은 지역들이 서로 의지하며 함께 살아가는 것이에요. 우리 집 밥상의 생선은 바닷가 지역에서 오고, 우리 지역의 과일은 다른 지역으로 가요. 이렇게 서로 주고받아야 모두 필요한 것을 누릴 수 있어요.","scoring_points":["상호 의존의 뜻을 썼는가","생활 속 예를 썼는가","서로 주고받는다는 것을 드러냈는가"]},"explanation":["뜻을 써요.","예를 찾아요.","서로를 드러내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#1','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',1,'mc','auto','생산물이나 상품을 주고받는 교류를 무엇이라고 하나요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"mc","stem":"생산물이나 상품을 주고받는 교류를 무엇이라고 하나요?","options":[{"t":"물자 교류","correct":true},{"t":"기술 교류","mis":"SO4-1-u3-X30"},{"t":"문화 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["생산물이에요.","상품이에요.","물자 교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#2','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',1,'sa','auto','공연·축제·전통·예술을 함께 나누는 교류를 ○○ 교류라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"sa","stem":"공연·축제·전통·예술을 함께 나누는 교류를 ○○ 교류라고 해요. 두 글자로 쓰세요.","answer":["문화"],"explanation":["공연이에요.","축제예요.","문화 교류예요."],"mis":"SO4-1-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#3','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',1,'ox','auto','지역끼리 교류로 주고받는 것은 물건뿐이에요.',ARRAY['SO4-1-u3-X29']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"ox","stem":"지역끼리 교류로 주고받는 것은 물건뿐이에요.","answer":"X","reason_options":[{"t":"기술·정보·사람과 공연·축제도 주고받기 때문에","correct":true},{"t":"교류는 물건을 주고받는 것만 뜻하기 때문에","mis":"SO4-1-u3-X29"}],"mis":"SO4-1-u3-X29","explanation":["물건만일까요?","기술과 문화도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#4','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',1,'mc','auto','㉯는 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"mc","stem":"㉯는 어떤 교류인가요?","options":[{"t":"기술 교류","correct":true},{"t":"물자 교류","mis":"SO4-1-u3-X30"},{"t":"문화 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["농사법을 알려 줘요.","기술이에요.","기술 교류예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#5','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',2,'mc','auto','㉰는 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"mc","stem":"㉰는 어떤 교류인가요?","options":[{"t":"문화 교류","correct":true},{"t":"물자 교류","mis":"SO4-1-u3-X30"},{"t":"기술 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["함께 축제를 열어요.","즐거움을 나눠요.","문화 교류예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#6','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',2,'mc','auto','㉱처럼 의료진이 다른 지역에 가서 돕는 것은 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"mc","stem":"㉱처럼 의료진이 다른 지역에 가서 돕는 것은 어떤 교류인가요?","options":[{"t":"기술 교류 — 기술과 사람을 주고받아서","correct":true},{"t":"물자 교류 — 물건을 보내서","mis":"SO4-1-u3-X30"},{"t":"문화 교류 — 공연을 해서","mis":"SO4-1-u3-X30"},{"t":"교류가 아님 — 물건이 오가지 않아서","mis":"SO4-1-u3-X29"}],"explanation":["의료진이 가요.","기술과 사람이에요.","기술 교류예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#7','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',2,'ox','auto','㉲처럼 봉사 활동으로 도움을 주고받는 것도 교류예요.',ARRAY['SO4-1-u3-X29']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"ox","stem":"㉲처럼 봉사 활동으로 도움을 주고받는 것도 교류예요.","answer":"O","reason_options":[{"t":"어려울 때 서로 돕는 것도 지역끼리 주고받는 일이기 때문에","correct":true},{"t":"교류는 물자를 주고받는 것만이기 때문에","mis":"SO4-1-u3-X29"}],"mis":"SO4-1-u3-X29","explanation":["봉사단이 가요.","도움을 줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_basic#8','soc',4,1,'u3','L10','g4_1_soc_u3_L10_basic','lesson_basic','SO4-1-u3-C10',2,'match','auto','교류 사례와 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"match","stem":"교류 사례와 종류를 알맞게 이으세요.","pairs":[{"l":"㉮ 생선 보내기","r":"물자 교류"},{"l":"㉯ 농사법 알려 주기","r":"기술 교류"},{"l":"㉰ 함께 축제 열기","r":"문화 교류"}],"mis":"SO4-1-u3-X30","explanation":["생선은 물자예요.","농사법은 기술이에요.","축제는 문화예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
