INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#4','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',3,'mc','auto','두 지역 학생들이 서로의 전통 놀이를 배우는 행사는 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C10","difficulty":3,"kind":"mc","stem":"두 지역 학생들이 서로의 전통 놀이를 배우는 행사는 어떤 교류인가요?","options":[{"t":"문화 교류","correct":true},{"t":"물자 교류","mis":"SO4-1-u3-X30"},{"t":"기술 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["전통 놀이예요.","함께 나눠요.","문화 교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
