INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#6','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',3,'ox','auto','물자·기술·문화 교류가 함께 이뤄질수록 지역들은 더 밀접하게 이어져요.',ARRAY['SO4-1-u3-X29']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C10","difficulty":3,"kind":"ox","stem":"물자·기술·문화 교류가 함께 이뤄질수록 지역들은 더 밀접하게 이어져요.","answer":"O","reason_options":[{"t":"여러 방법으로 주고받으며 서로 의지하기 때문에","correct":true},{"t":"교류가 많아질수록 지역끼리 멀어지기 때문에","mis":"SO4-1-u3-X29"}],"mis":"SO4-1-u3-X29","explanation":["여러 가지를 주고받아요.","서로 의지해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#7','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',3,'mc','auto','물건을 주고받지 않는 교류만 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X29','SO4-1-u3-X30']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C10","difficulty":3,"kind":"mc","stem":"물건을 주고받지 않는 교류만 묶은 것은 무엇인가요?","options":[{"t":"㉯ · ㉰ · ㉱ · ㉲","correct":true},{"t":"㉮ · ㉳","mis":"SO4-1-u3-X29"},{"t":"㉮ · ㉯ · ㉰","mis":"SO4-1-u3-X30"},{"t":"㉰만","mis":"SO4-1-u3-X29"}],"explanation":["㉮·㉳는 생선과 쌀이에요.","나머지는 기술·문화·봉사예요.","㉯·㉰·㉱·㉲예요."],"asset":{"type":"passage","lines":["㉮ 물결시의 생선을 구름군 시장으로 보낸다.","㉯ 너른들군 농업 연구소가 구름군 농부들에게 새 농사법을 알려 준다.","㉰ 물결시와 구름군이 함께 바다·산 축제를 연다.","㉱ 별가람시 의료진이 너른들군에 가서 아픈 사람을 돌본다.","㉲ 태풍 피해를 입은 물결시에 구름군 봉사단이 가서 복구를 돕는다.","㉳ 너른들군 쌀을 별가람시 학교 급식으로 보낸다."],"title":"여러 가지 교류 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#8','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',4,'essay','teacher','물자 교류, 기술 교류, 문화 교류가 무엇인지 쓰고, 예를 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":4,"kind":"essay","stem":"물자 교류, 기술 교류, 문화 교류가 무엇인지 쓰고, 예를 하나씩 쓰세요.","answer_guide":{"answer":"예: 물자 교류는 생산물이나 상품을 주고받는 것으로, 바닷가 지역의 생선을 산골 지역에 보내는 것이 있어요. 기술 교류는 기술·정보·사람을 주고받는 것으로, 농사법을 알려 주는 것이 있어요. 문화 교류는 공연·축제를 나누는 것으로, 두 지역이 함께 축제를 여는 것이 있어요.","scoring_points":["세 교류의 뜻을 썼는가","예를 하나씩 들었는가","예가 종류에 알맞은가"]},"explanation":["뜻을 써요.","예를 찾아요.","짝지어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#9','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',4,'mc','auto','구름군 버섯 축제에 물결시 공연단이 와서 공연하고, 물결시 상인들은 생선을 팔았어요. 어떤 교류가 이뤄졌나요?',ARRAY['SO4-1-u3-X29','SO4-1-u3-X30']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C10","difficulty":4,"kind":"mc","stem":"구름군 버섯 축제에 물결시 공연단이 와서 공연하고, 물결시 상인들은 생선을 팔았어요. 어떤 교류가 이뤄졌나요?","options":[{"t":"문화 교류와 물자 교류가 함께 이뤄졌어요","correct":true},{"t":"문화 교류만 이뤄졌어요","mis":"SO4-1-u3-X29"},{"t":"기술 교류만 이뤄졌어요","mis":"SO4-1-u3-X30"},{"t":"교류가 아니에요","mis":"SO4-1-u3-X29"}],"explanation":["공연은 문화예요.","생선은 물자예요.","둘 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L10_challenge#10','soc',4,1,'u3','L10','g4_1_soc_u3_L10_challenge','lesson_challenge','SO4-1-u3-C10',4,'essay','teacher','우리 지역에 큰 어려움이 생겼을 때 다른 지역과 할 수 있는 교류를 두 가지 쓰고, 각각 어떤 교류인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C10","difficulty":4,"kind":"essay","stem":"우리 지역에 큰 어려움이 생겼을 때 다른 지역과 할 수 있는 교류를 두 가지 쓰고, 각각 어떤 교류인지 쓰세요.","answer_guide":{"answer":"예: 홍수가 나면 다른 지역 봉사단이 와서 흙을 치우는 봉사 활동으로 도움을 받을 수 있어요. 또 먹을거리가 부족하면 다른 지역에서 쌀과 물을 보내 주는 물자 교류를 할 수 있어요.","scoring_points":["어려움을 정했는가","교류 두 가지를 썼는가","각각 어떤 교류인지 썼는가"]},"explanation":["어려움을 떠올려요.","도움을 찾아요.","종류를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#1','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',1,'mc','auto','우리 지역 교류 지도는 무엇을 가운데에 두고 만드나요?',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C11","difficulty":1,"kind":"mc","stem":"우리 지역 교류 지도는 무엇을 가운데에 두고 만드나요?","options":[{"t":"우리 지역","correct":true},{"t":"가장 큰 도시","mis":"SO4-1-u3-X31"},{"t":"가장 먼 지역","mis":"SO4-1-u3-X31"},{"t":"아무 지역이나","mis":"SO4-1-u3-X31"}],"explanation":["우리 지역 지도예요.","가운데에 둬요.","우리 지역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#2','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',1,'sa','auto','교류 지도를 만들기 전에 먼저 교류 사례를 ○○해야 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C11","difficulty":1,"kind":"sa","stem":"교류 지도를 만들기 전에 먼저 교류 사례를 ○○해야 해요. 두 글자로 쓰세요.","answer":["조사"],"explanation":["사례를 찾아요.","알아봐요.","조사예요."],"mis":"SO4-1-u3-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#3','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',1,'ox','auto','교류 지도에서 다른 지역에서 우리 지역으로 들어오는 교류는 노란색으로 나타내요.',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C11","difficulty":1,"kind":"ox","stem":"교류 지도에서 다른 지역에서 우리 지역으로 들어오는 교류는 노란색으로 나타내요.","answer":"O","reason_options":[{"t":"들어오는 교류는 노란색, 나가는 교류는 파란색으로 정했기 때문에","correct":true},{"t":"들어오는 교류는 파란색이기 때문에","mis":"SO4-1-u3-X32"}],"mis":"SO4-1-u3-X32","explanation":["들어와요.","노란색이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#4','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',1,'mc','auto','교류 사례를 조사하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C11","difficulty":1,"kind":"mc","stem":"교류 사례를 조사하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"지역 누리집에 들어가 보고 주요 생산물을 알아봐요","correct":true},{"t":"상상해서 마음대로 적어요","mis":"SO4-1-u3-X31"},{"t":"아무 지역 이름이나 적어요","mis":"SO4-1-u3-X31"},{"t":"지도부터 그리고 나중에 생각해요","mis":"SO4-1-u3-X31"}],"explanation":["누리집을 봐요.","생산물을 알아봐요.","조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#5','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',2,'mc','auto','물결시로 들어오는 교류는 무엇인가요?',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"mc","stem":"물결시로 들어오는 교류는 무엇인가요?","options":[{"t":"너른들군의 쌀","correct":true},{"t":"별가람시로 가는 멸치","mis":"SO4-1-u3-X32"},{"t":"구름군으로 가는 공연단","mis":"SO4-1-u3-X32"},{"t":"들어오는 교류는 없어요","mis":"SO4-1-u3-X32"}],"explanation":["노란 화살표를 봐요.","물결시로 와요.","쌀이에요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#6','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',2,'mc','auto','물결시에서 다른 지역으로 나가는 물자는 무엇인가요?',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"mc","stem":"물결시에서 다른 지역으로 나가는 물자는 무엇인가요?","options":[{"t":"멸치","correct":true},{"t":"쌀","mis":"SO4-1-u3-X32"},{"t":"버섯","mis":"SO4-1-u3-X32"},{"t":"배 고치는 기술","mis":"SO4-1-u3-X32"}],"explanation":["파란 화살표를 봐요.","물자를 찾아요.","멸치예요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#7','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',2,'ox','auto','물결시와 구름군 사이에는 물자 교류와 문화 교류가 함께 있어요.',ARRAY['SO4-1-u3-X30']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"ox","stem":"물결시와 구름군 사이에는 물자 교류와 문화 교류가 함께 있어요.","answer":"O","reason_options":[{"t":"버섯이 들어오고 공연단이 나가기 때문에","correct":true},{"t":"두 지역 사이에는 한 가지 교류만 있기 때문에","mis":"SO4-1-u3-X30"}],"mis":"SO4-1-u3-X30","explanation":["버섯은 물자예요.","공연단은 문화예요.","그래서 O예요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#8','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',2,'match','auto','교류 지도의 화살표와 교류 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"match","stem":"교류 지도의 화살표와 교류 종류를 알맞게 이으세요.","pairs":[{"l":"별가람시 → 물결시 : 배 고치는 기술","r":"기술 교류"},{"l":"물결시 → 구름군 : 바다 노래 공연단","r":"문화 교류"}],"mis":"SO4-1-u3-X30","explanation":["기술이 들어와요.","공연단이 나가요.","종류를 이어요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#9','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',2,'blank','auto','우리 지역에서 다른 지역으로 나가는 교류는 (    )으로 나타내요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"blank","stem":"우리 지역에서 다른 지역으로 나가는 교류는 (    )으로 나타내요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"파란색","correct":true},{"t":"노란색","mis":"SO4-1-u3-X32"},{"t":"검은색","mis":"SO4-1-u3-X32"},{"t":"아무 색","mis":"SO4-1-u3-X32"}],"explanation":["나가요.","들어오는 것과 달라요.","파란색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_basic#10','soc',4,1,'u3','L11','g4_1_soc_u3_L11_basic','lesson_basic','SO4-1-u3-C11',3,'mc','auto','물결시 교류 지도로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X32','SO4-1-u3-X29']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"물결시 교류 지도로 알 수 있는 것은 무엇인가요?","options":[{"t":"물결시는 여러 지역과 물자·기술·문화를 주고받으며 서로 의존해요","correct":true},{"t":"물결시는 혼자서 모든 것을 해결해요","mis":"SO4-1-u3-X33"},{"t":"물결시는 받기만 하고 주지는 않아요","mis":"SO4-1-u3-X32"},{"t":"물결시는 물자만 주고받아요","mis":"SO4-1-u3-X29"}],"explanation":["화살표가 여러 개예요.","들어오고 나가요.","서로 의존해요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#1','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',2,'mc','auto','물결시 교류 지도에서 물결시의 주요 생산물로 짐작할 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"mc","stem":"물결시 교류 지도에서 물결시의 주요 생산물로 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"멸치","correct":true},{"t":"쌀","mis":"SO4-1-u3-X32"},{"t":"버섯","mis":"SO4-1-u3-X32"},{"t":"배 고치는 기술","mis":"SO4-1-u3-X32"}],"explanation":["나가는 것을 봐요.","물결시에서 나요.","멸치예요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#2','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',2,'ox','auto','교류 지도는 만드는 사람마다 조금씩 다를 수 있어요.',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"ox","stem":"교류 지도는 만드는 사람마다 조금씩 다를 수 있어요.","answer":"O","reason_options":[{"t":"조사한 사례와 나타내는 방법이 사람마다 다를 수 있기 때문에","correct":true},{"t":"교류 지도는 누가 만들어도 꼭 같아야 하기 때문에","mis":"SO4-1-u3-X31"}],"mis":"SO4-1-u3-X31","explanation":["조사한 것이 달라요.","그리는 방법도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#3','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',3,'error','auto','물결시 교류 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X31','SO4-1-u3-X30']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"error","stem":"물결시 교류 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「구름군에서 버섯이 들어오니 파란색으로 그려야 해.」","correct":true,"mis_target":"SO4-1-u3-X32"},{"t":"친구 가 — 「물결시를 가운데에 두었어.」","mis":"SO4-1-u3-X31"},{"t":"친구 나 — 「별가람시와는 기술을 주고받아.」","mis":"SO4-1-u3-X30"}],"explanation":["들어오는 교류예요.","노란색이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#4','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',3,'mc','auto','교류 지도를 만드는 차례로 바른 것은 무엇인가요?',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"교류 지도를 만드는 차례로 바른 것은 무엇인가요?","options":[{"t":"교류 사례 조사 → 우리 지역을 가운데에 → 둘레에 교류 지역 → 색 화살표로 방향","correct":true},{"t":"색 화살표로 방향 → 교류 사례 조사 → 우리 지역을 가운데에 → 둘레에 교류 지역","mis":"SO4-1-u3-X31"},{"t":"둘레에 교류 지역 → 색 화살표로 방향 → 교류 사례 조사 → 우리 지역을 가운데에","mis":"SO4-1-u3-X31"},{"t":"우리 지역을 가운데에 → 색 화살표로 방향 → 둘레에 교류 지역 → 교류 사례 조사","mis":"SO4-1-u3-X31"}],"explanation":["조사가 먼저예요.","가운데에 우리 지역이에요.","마지막에 화살표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#5','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',3,'mc','auto','교류 지도를 만들 때 유의할 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X31']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"교류 지도를 만들 때 유의할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"들어오고 나가는 것을 색으로 나누고, 무엇을 주고받는지 적어요","correct":true},{"t":"화살표 색을 마음대로 섞어요","mis":"SO4-1-u3-X32"},{"t":"우리 지역은 구석에 작게 그려요","mis":"SO4-1-u3-X31"},{"t":"조사하지 않고 떠오르는 대로 그려요","mis":"SO4-1-u3-X31"}],"explanation":["색을 정해요.","무엇인지 적어요.","한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#6','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',3,'ox','auto','물결시 교류 지도를 보면 물결시는 다른 지역에 주기만 하고 받지는 않아요.',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"ox","stem":"물결시 교류 지도를 보면 물결시는 다른 지역에 주기만 하고 받지는 않아요.","answer":"X","reason_options":[{"t":"노란 화살표로 쌀·버섯·기술이 들어오기 때문에","correct":true},{"t":"물결시에서 나가는 화살표만 있기 때문에","mis":"SO4-1-u3-X32"}],"mis":"SO4-1-u3-X32","explanation":["노란 화살표가 있어요.","들어오는 것도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#7','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',3,'mc','auto','교류 지도를 만들면 좋은 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X31','SO4-1-u3-X33']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"교류 지도를 만들면 좋은 까닭은 무엇인가요?","options":[{"t":"우리 지역이 어느 지역과 무엇을 주고받는지 한눈에 알 수 있어서","correct":true},{"t":"지역 이름을 외우기 쉬워서","mis":"SO4-1-u3-X31"},{"t":"그림 그리기 연습만 할 수 있어서","mis":"SO4-1-u3-X31"},{"t":"교류를 줄일 수 있어서","mis":"SO4-1-u3-X33"}],"explanation":["한 장에 담겨요.","주고받는 것이 보여요.","한눈에 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#8','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',4,'essay','teacher','물결시 교류 지도에서 들어오는 교류와 나가는 교류를 하나씩 찾아, 어떤 교류인지와 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C11","difficulty":4,"kind":"essay","stem":"물결시 교류 지도에서 들어오는 교류와 나가는 교류를 하나씩 찾아, 어떤 교류인지와 함께 쓰세요.","answer_guide":{"answer":"예: 너른들군에서 물결시로 쌀이 들어오는 것은 노란 화살표로 나타낸 물자 교류예요. 물결시에서 구름군으로 바다 노래 공연단이 가는 것은 파란 화살표로 나타낸 문화 교류예요.","scoring_points":["들어오는 교류를 찾았는가","나가는 교류를 찾았는가","교류 종류를 바르게 썼는가"]},"explanation":["노란 화살표를 봐요.","파란 화살표를 봐요.","종류를 써요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#9','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',4,'mc','auto','물결시가 너른들군 농부들에게 바다 풀로 거름 만드는 법을 알려 주는 교류를 지도에 더하려고 해요. 어떻게 나타내야 하나요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X30']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C11","difficulty":4,"kind":"mc","stem":"물결시가 너른들군 농부들에게 바다 풀로 거름 만드는 법을 알려 주는 교류를 지도에 더하려고 해요. 어떻게 나타내야 하나요?","options":[{"t":"물결시에서 너른들군으로 파란 화살표 — 기술 교류","correct":true},{"t":"너른들군에서 물결시로 노란 화살표 — 기술 교류","mis":"SO4-1-u3-X32"},{"t":"물결시에서 너른들군으로 파란 화살표 — 물자 교류","mis":"SO4-1-u3-X30"},{"t":"너른들군에서 물결시로 노란 화살표 — 문화 교류","mis":"SO4-1-u3-X32"}],"explanation":["물결시가 알려 줘요.","나가는 교류예요.","기술 교류예요."],"asset":{"type":"passage","lines":["가운데 — 물결시","노란 화살표 — 너른들군 → 물결시 : 쌀","노란 화살표 — 구름군 → 물결시 : 버섯","노란 화살표 — 별가람시 → 물결시 : 배 고치는 기술","파란 화살표 — 물결시 → 별가람시 : 멸치","파란 화살표 — 물결시 → 구름군 : 바다 노래 공연단"],"title":"물결시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L11_challenge#10','soc',4,1,'u3','L11','g4_1_soc_u3_L11_challenge','lesson_challenge','SO4-1-u3-C11',4,'essay','teacher','내가 사는 지역의 교류 지도를 만든다면 무엇을 어떤 차례로 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C11","difficulty":4,"kind":"essay","stem":"내가 사는 지역의 교류 지도를 만든다면 무엇을 어떤 차례로 할지 쓰세요.","answer_guide":{"answer":"예: 먼저 우리 지역 누리집에 들어가 주요 생산물과 교류 사례를 조사해요. 그다음 종이 가운데에 우리 지역을 그리고, 둘레에 교류하는 지역을 그려요. 마지막으로 들어오는 교류는 노란색, 나가는 교류는 파란색 화살표로 잇고 무엇을 주고받는지 적어요.","scoring_points":["조사를 먼저 한다고 썼는가","우리 지역을 가운데에 둔다고 썼는가","색으로 방향을 나타낸다고 썼는가"]},"explanation":["조사해요.","가운데에 둬요.","화살표로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#1','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',1,'mc','auto','두 지역이 강점은 주고 부족함은 받으며 교류하면 어떻게 되나요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X34']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C12","difficulty":1,"kind":"mc","stem":"두 지역이 강점은 주고 부족함은 받으며 교류하면 어떻게 되나요?","options":[{"t":"두 지역 모두 만족하며 함께 발전해요","correct":true},{"t":"한 지역만 손해를 봐요","mis":"SO4-1-u3-X28"},{"t":"두 지역 모두 손해를 봐요","mis":"SO4-1-u3-X28"},{"t":"아무것도 달라지지 않아요","mis":"SO4-1-u3-X34"}],"explanation":["강점을 줘요.","부족함을 받아요.","모두 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#2','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',1,'sa','auto','서로 다른 두 지역이 가까운 사이가 되기로 약속하고 꾸준히 교류하는 것을 ○○결연이라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C12","difficulty":1,"kind":"sa","stem":"서로 다른 두 지역이 가까운 사이가 되기로 약속하고 꾸준히 교류하는 것을 ○○결연이라고 해요. 두 글자로 쓰세요.","answer":["자매"],"explanation":["두 지역이에요.","가까운 사이예요.","자매결연이에요."],"mis":"SO4-1-u3-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#3','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C7',1,'ox','auto','공연처럼 사람들의 생활을 즐겁게 해 주는 것도 생산이에요.',ARRAY['SO4-1-u3-X22']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"ox","stem":"공연처럼 사람들의 생활을 즐겁게 해 주는 것도 생산이에요.","answer":"O","reason_options":[{"t":"물건을 만드는 것뿐 아니라 즐겁게 해 주는 것도 생산이기 때문에","correct":true},{"t":"물건을 만들어야만 생산이기 때문에","mis":"SO4-1-u3-X22"}],"mis":"SO4-1-u3-X22","explanation":["공연이에요.","즐겁게 해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#4','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C9',1,'mc','auto','지역끼리 물자·기술·문화를 주고받는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X27']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"mc","stem":"지역끼리 물자·기술·문화를 주고받는 것을 무엇이라고 하나요?","options":[{"t":"지역 간 교류","correct":true},{"t":"소비","mis":"SO4-1-u3-X23"},{"t":"선택","mis":"SO4-1-u3-X27"},{"t":"희소성","mis":"SO4-1-u3-X27"}],"explanation":["주고받아요.","지역끼리예요.","교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#5','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',2,'mc','auto','물결시가 자매결연을 맺기에 가장 알맞은 곳과 그 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X34']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C12","difficulty":2,"kind":"mc","stem":"물결시가 자매결연을 맺기에 가장 알맞은 곳과 그 까닭은 무엇인가요?","options":[{"t":"후보 ㉮ — 서로의 부족함을 채워 줄 수 있어서","correct":true},{"t":"후보 ㉯ — 물결시와 똑같은 것이 나서","mis":"SO4-1-u3-X34"},{"t":"후보 ㉰ — 이름이 널리 알려져서","mis":"SO4-1-u3-X34"},{"t":"아무 곳이나 — 상관없어서","mis":"SO4-1-u3-X34"}],"explanation":["물결시는 쌀이 부족해요.","㉮는 바다가 없어요.","서로 채워 줘요."],"asset":{"type":"passage","lines":["물결시 — 생선이 많이 나고 바다 축제가 유명하지만, 쌀이 부족하다.","후보 ㉮ — 쌀이 많이 나고 농사 기술이 뛰어나지만, 바다가 없다.","후보 ㉯ — 물결시처럼 생선이 많이 나고, 쌀은 나지 않는다.","후보 ㉰ — 이름은 널리 알려졌지만 서로 주고받을 것이 거의 없다."],"title":"물결시의 자매결연 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#6','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',2,'mc','auto','지역끼리 아무것도 주고받지 않는다면 우리 생활은 어떻게 될까요?',ARRAY['SO4-1-u3-X34','SO4-1-u3-X27','SO4-1-u3-X24']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C12","difficulty":2,"kind":"mc","stem":"지역끼리 아무것도 주고받지 않는다면 우리 생활은 어떻게 될까요?","options":[{"t":"우리 지역에서 나는 것만 써야 해서 여러 음식과 물건을 누리기 어려워요","correct":true},{"t":"지금과 똑같이 지낼 수 있어요","mis":"SO4-1-u3-X34"},{"t":"더 많은 것을 누리게 돼요","mis":"SO4-1-u3-X27"},{"t":"생산을 하지 않아도 돼요","mis":"SO4-1-u3-X24"}],"explanation":["다른 지역 것이 안 와요.","우리 지역 것만 남아요.","누리기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#7','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C8',2,'ox','auto','생산 활동은 자연에서 얻기, 만들기, 편리하고 즐겁게 해 주기의 세 종류로 나눌 수 있어요.',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"ox","stem":"생산 활동은 자연에서 얻기, 만들기, 편리하고 즐겁게 해 주기의 세 종류로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"벼농사·빵 만들기·진료처럼 세 갈래로 나뉘기 때문에","correct":true},{"t":"생산 활동은 물건 만들기 한 종류뿐이기 때문에","mis":"SO4-1-u3-X25"}],"mis":"SO4-1-u3-X25","explanation":["자연에서 얻어요.","만들고 해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#8','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',2,'match','auto','주제②의 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C12","difficulty":2,"kind":"match","stem":"주제②의 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"생산","r":"만들거나 편리하고 즐겁게 해 주기"},{"l":"소비","r":"사거나 이용하기"},{"l":"상호 의존","r":"서로 의지하며 함께 살아가기"}],"mis":"SO4-1-u3-X33","explanation":["생산은 해 주는 쪽이에요.","소비는 이용하는 쪽이에요.","상호 의존은 서로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#9','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',2,'blank','auto','지역마다 나는 것이 달라 교류하고, 지역들은 서로 (    )하며 함께 발전해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X33','SO4-1-u3-X27']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C12","difficulty":2,"kind":"blank","stem":"지역마다 나는 것이 달라 교류하고, 지역들은 서로 (    )하며 함께 발전해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"의존","correct":true},{"t":"경쟁만","mis":"SO4-1-u3-X28"},{"t":"고립","mis":"SO4-1-u3-X33"},{"t":"포기","mis":"SO4-1-u3-X27"}],"explanation":["서로 기대요.","의지해요.","의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_basic#10','soc',4,1,'u3','L12','g4_1_soc_u3_L12_basic','lesson_basic','SO4-1-u3-C12',3,'mc','auto','주제②를 배우고 알게 된 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X29','SO4-1-u3-X24']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"mc","stem":"주제②를 배우고 알게 된 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역들은 생산·소비와 교류로 서로 의존하며 함께 발전해요","correct":true},{"t":"지역은 혼자서도 무엇이든 해결해요","mis":"SO4-1-u3-X33"},{"t":"교류는 물건을 주고받는 것뿐이에요","mis":"SO4-1-u3-X29"},{"t":"생산과 소비는 서로 관계없어요","mis":"SO4-1-u3-X24"}],"explanation":["생산과 소비예요.","교류예요.","함께 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#1','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C7',2,'mc','auto','버스를 타고 요금을 내는 것은 어떤 활동인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X25','SO4-1-u3-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"mc","stem":"버스를 타고 요금을 내는 것은 어떤 활동인가요?","options":[{"t":"서비스를 이용하는 소비","correct":true},{"t":"물건을 만드는 생산","mis":"SO4-1-u3-X23"},{"t":"자연에서 얻는 생산","mis":"SO4-1-u3-X25"},{"t":"경제활동이 아닌 일","mis":"SO4-1-u3-X22"}],"explanation":["버스를 타요.","이용해요.","소비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#2','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C9',2,'ox','auto','우리가 쓰는 물건과 먹을거리 가운데에는 교류로 다른 지역에서 온 것이 많아요.',ARRAY['SO4-1-u3-X27']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"ox","stem":"우리가 쓰는 물건과 먹을거리 가운데에는 교류로 다른 지역에서 온 것이 많아요.","answer":"O","reason_options":[{"t":"지역마다 나는 것이 달라 교류로 주고받기 때문에","correct":true},{"t":"우리가 쓰는 것은 모두 우리 지역에서 나기 때문에","mis":"SO4-1-u3-X27"}],"mis":"SO4-1-u3-X27","explanation":["김밥 재료를 떠올려요.","여러 지역에서 와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#3','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',3,'error','auto','자매결연 후보를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X34','SO4-1-u3-X26','SO4-1-u3-X28']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"error","stem":"자매결연 후보를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「후보 ㉰는 이름이 널리 알려졌으니 가장 좋은 짝이야.」","correct":true,"mis_target":"SO4-1-u3-X34"},{"t":"친구 가 — 「후보 ㉮에서는 물결시에 부족한 쌀이 나.」","mis":"SO4-1-u3-X26"},{"t":"친구 다 — 「물결시는 후보 ㉮에 생선을 줄 수 있어.」","mis":"SO4-1-u3-X28"}],"explanation":["이름보다 주고받을 것이에요.","㉰는 주고받을 것이 없어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["물결시 — 생선이 많이 나고 바다 축제가 유명하지만, 쌀이 부족하다.","후보 ㉮ — 쌀이 많이 나고 농사 기술이 뛰어나지만, 바다가 없다.","후보 ㉯ — 물결시처럼 생선이 많이 나고, 쌀은 나지 않는다.","후보 ㉰ — 이름은 널리 알려졌지만 서로 주고받을 것이 거의 없다."],"title":"물결시의 자매결연 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#4','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',3,'mc','auto','자매결연을 맺은 두 지역이 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X34']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"mc","stem":"자매결연을 맺은 두 지역이 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"서로의 축제에 공연단을 보내고 잘 나는 것을 나눠요","correct":true},{"t":"한 지역만 선물을 받아요","mis":"SO4-1-u3-X28"},{"t":"이름만 걸어 두고 아무것도 주고받지 않아요","mis":"SO4-1-u3-X34"},{"t":"서로 이기려고 다퉈요","mis":"SO4-1-u3-X28"}],"explanation":["가까운 사이예요.","주고받아요.","함께 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#5','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C10',3,'mc','auto','태풍 피해를 입은 지역에 다른 지역 사람들이 가서 복구를 돕는 것은 무엇인가요?',ARRAY['SO4-1-u3-X29','SO4-1-u3-X30','SO4-1-u3-X23']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C10","difficulty":3,"kind":"mc","stem":"태풍 피해를 입은 지역에 다른 지역 사람들이 가서 복구를 돕는 것은 무엇인가요?","options":[{"t":"봉사 활동으로 도움을 주고받는 교류","correct":true},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"},{"t":"문화 교류","mis":"SO4-1-u3-X30"},{"t":"소비 활동","mis":"SO4-1-u3-X23"}],"explanation":["어려움을 도와요.","지역끼리예요.","교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#6','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C11',3,'ox','auto','교류 지도에서 노란 화살표가 많으면 우리 지역이 다른 지역에 주는 것이 많다는 뜻이에요.',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"ox","stem":"교류 지도에서 노란 화살표가 많으면 우리 지역이 다른 지역에 주는 것이 많다는 뜻이에요.","answer":"X","reason_options":[{"t":"노란 화살표는 우리 지역으로 들어오는 교류이기 때문에","correct":true},{"t":"노란 화살표는 나가는 교류이기 때문에","mis":"SO4-1-u3-X32"}],"mis":"SO4-1-u3-X32","explanation":["노란색은 들어와요.","받는 것이 많아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#7','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',3,'mc','auto','생산·소비와 교류의 관계를 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u3-X24','SO4-1-u3-X27','SO4-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"mc","stem":"생산·소비와 교류의 관계를 바르게 말한 것은 무엇인가요?","options":[{"t":"지역마다 생산하는 것이 달라서, 교류로 다른 지역의 생산물을 소비할 수 있어요","correct":true},{"t":"생산과 교류는 서로 관계없어요","mis":"SO4-1-u3-X24"},{"t":"교류하면 생산할 필요가 없어요","mis":"SO4-1-u3-X27"},{"t":"소비는 우리 지역 생산물로만 해요","mis":"SO4-1-u3-X26"}],"explanation":["생산이 달라요.","교류로 와요.","소비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#8','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',4,'essay','teacher','바다가 있는 지역과 과일이 잘 나는 지역이 교류하면 무엇을 기대할 수 있는지 쓰고, 상호 의존과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C12","difficulty":4,"kind":"essay","stem":"바다가 있는 지역과 과일이 잘 나는 지역이 교류하면 무엇을 기대할 수 있는지 쓰고, 상호 의존과 이어 쓰세요.","answer_guide":{"answer":"예: 바다가 있는 지역은 과일을, 과일이 잘 나는 지역은 생선을 얻을 수 있어요. 서로 부족한 것을 채워 주니 두 지역 모두 이로워요. 이렇게 서로 의지하며 함께 살아가는 것이 상호 의존이고, 두 지역은 함께 발전해요.","scoring_points":["두 지역이 얻는 것을 썼는가","모두 이롭다는 것을 썼는가","상호 의존과 이어 썼는가"]},"explanation":["주고받는 것을 써요.","모두 이로워요.","상호 의존과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#9','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',4,'mc','auto','물결시가 후보 ㉮와 자매결연을 맺은 뒤의 교류 계획으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X26','SO4-1-u3-X34']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C12","difficulty":4,"kind":"mc","stem":"물결시가 후보 ㉮와 자매결연을 맺은 뒤의 교류 계획으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"물결시는 생선과 바다 축제 공연을 보내고, ㉮에서는 쌀과 농사 기술을 받아요","correct":true},{"t":"물결시가 ㉮에 쌀을 보내요","mis":"SO4-1-u3-X26"},{"t":"㉮가 물결시에 생선을 보내요","mis":"SO4-1-u3-X26"},{"t":"아무것도 주고받지 않고 이름만 걸어 두어요","mis":"SO4-1-u3-X34"}],"explanation":["물결시는 생선이 많아요.","㉮는 쌀이 많아요.","서로 채워요."],"asset":{"type":"passage","lines":["물결시 — 생선이 많이 나고 바다 축제가 유명하지만, 쌀이 부족하다.","후보 ㉮ — 쌀이 많이 나고 농사 기술이 뛰어나지만, 바다가 없다.","후보 ㉯ — 물결시처럼 생선이 많이 나고, 쌀은 나지 않는다.","후보 ㉰ — 이름은 널리 알려졌지만 서로 주고받을 것이 거의 없다."],"title":"물결시의 자매결연 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_L12_challenge#10','soc',4,1,'u3','L12','g4_1_soc_u3_L12_challenge','lesson_challenge','SO4-1-u3-C12',4,'essay','teacher','지역 간 교류가 없다면 내 생활이 어떻게 달라질지 두 가지를 쓰고, 그래서 교류가 왜 소중한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u3-C12","difficulty":4,"kind":"essay","stem":"지역 간 교류가 없다면 내 생활이 어떻게 달라질지 두 가지를 쓰고, 그래서 교류가 왜 소중한지 쓰세요.","answer_guide":{"answer":"예: 교류가 없다면 우리 지역에서 나지 않는 생선을 먹을 수 없을 거예요. 또 다른 지역의 축제나 공연도 즐기기 어려워요. 교류 덕분에 여러 지역의 좋은 것을 함께 누리며 살 수 있으니 교류는 소중해요.","scoring_points":["달라질 점 두 가지를 썼는가","생활과 이어 썼는가","교류가 소중한 까닭을 썼는가"]},"explanation":["없다고 상상해요.","두 가지를 써요.","소중한 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#1','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C1',1,'mc','auto','물건을 고르고 사는 일도 들어가는, 생활에 필요한 것을 만들고 사고팔고 쓰는 모든 활동은 무엇인가요?',ARRAY['SO4-1-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"mc","stem":"물건을 고르고 사는 일도 들어가는, 생활에 필요한 것을 만들고 사고팔고 쓰는 모든 활동은 무엇인가요?","options":[{"t":"경제활동","correct":true},{"t":"여가 활동","mis":"SO4-1-u3-X01"},{"t":"봉사 활동","mis":"SO4-1-u3-X01"},{"t":"체육 활동","mis":"SO4-1-u3-X01"}],"explanation":["사는 일도 들어가요.","만들고 쓰는 일도요.","경제활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#2','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C2',1,'mc','auto','돈과 노력은 적게 들이고 만족은 가장 크게 얻는 선택은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07','SO4-1-u3-X08']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"mc","stem":"돈과 노력은 적게 들이고 만족은 가장 크게 얻는 선택은 무엇인가요?","options":[{"t":"합리적 선택","correct":true},{"t":"가장 비싼 선택","mis":"SO4-1-u3-X06"},{"t":"아무렇게나 한 선택","mis":"SO4-1-u3-X07"},{"t":"친구를 따라 한 선택","mis":"SO4-1-u3-X08"}],"explanation":["비용은 적게요.","만족은 크게요.","합리적 선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#3','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C3',1,'mc','auto','일지 ②의 ㉮처럼 써 본 사람에게 얻은 정보의 좋은 점은 무엇인가요?',ARRAY['SO4-1-u3-X09','SO4-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"mc","stem":"일지 ②의 ㉮처럼 써 본 사람에게 얻은 정보의 좋은 점은 무엇인가요?","options":[{"t":"실제로 써 본 생생한 경험을 알 수 있어요","correct":true},{"t":"여러 가게 값을 한눈에 볼 수 있어요","mis":"SO4-1-u3-X09"},{"t":"직접 열고 닫아 볼 수 있어요","mis":"SO4-1-u3-X09"},{"t":"언제나 가장 싼 값을 알려 줘요","mis":"SO4-1-u3-X10"}],"explanation":["써 본 언니예요.","1년 썼어요.","생생한 경험이에요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#4','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C4',1,'mc','auto','물건을 고를 때 생각하는 선택 기준끼리 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X14','SO4-1-u3-X15']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"mc","stem":"물건을 고를 때 생각하는 선택 기준끼리 묶은 것은 무엇인가요?","options":[{"t":"가격 · 품질 · 디자인 · 서비스 · 친환경","correct":true},{"t":"광고 모델 · 가게 이름 · 간판 색","mis":"SO4-1-u3-X14"},{"t":"친구 수 · 날씨 · 요일","mis":"SO4-1-u3-X14"},{"t":"가격 하나뿐","mis":"SO4-1-u3-X15"}],"explanation":["값과 품질이에요.","디자인·서비스도요.","친환경도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#5','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C7',1,'mc','auto','일지 ④의 ㉰ 손님이 김치를 사는 것은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X24','SO4-1-u3-X25']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"mc","stem":"일지 ④의 ㉰ 손님이 김치를 사는 것은 무엇인가요?","options":[{"t":"소비","correct":true},{"t":"생산","mis":"SO4-1-u3-X23"},{"t":"생산도 소비도 아님","mis":"SO4-1-u3-X24"},{"t":"만드는 생산","mis":"SO4-1-u3-X25"}],"explanation":["손님이에요.","사요.","소비예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#6','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C8',1,'mc','auto','일지 ④의 ㉮ 농부가 밭에서 무를 기르는 것은 어떤 생산 활동인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X23']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"mc","stem":"일지 ④의 ㉮ 농부가 밭에서 무를 기르는 것은 어떤 생산 활동인가요?","options":[{"t":"자연에서 얻는 활동","correct":true},{"t":"만드는 활동","mis":"SO4-1-u3-X25"},{"t":"편리하게 해 주는 활동","mis":"SO4-1-u3-X25"},{"t":"소비 활동","mis":"SO4-1-u3-X23"}],"explanation":["밭에서 길러요.","자연에서 얻어요.","자연에서 얻는 활동이에요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#7','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C9',1,'mc','auto','일지 ⑤에서 푸른내시에서 많이 나는 것은 무엇인가요?',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"mc","stem":"일지 ⑤에서 푸른내시에서 많이 나는 것은 무엇인가요?","options":[{"t":"쌀","correct":true},{"t":"조개","mis":"SO4-1-u3-X26"},{"t":"사과","mis":"SO4-1-u3-X26"},{"t":"생선","mis":"SO4-1-u3-X26"}],"explanation":["강과 들이 있어요.","벼가 잘 자라요.","쌀이에요."],"asset":{"type":"passage","lines":["푸른내시 — 넓은 강과 들이 있어 쌀이 많이 나지만, 바다가 없다.","갯벌군 — 갯벌이 넓어 조개와 생선이 많이 나지만, 쌀이 부족하다.","산마루군 — 산비탈에 과수원이 많아 사과가 잘 난다."],"title":"일지 ⑤ — 세 지역 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#8','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C10',1,'mc','auto','일지 ⑥의 ㉮는 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"mc","stem":"일지 ⑥의 ㉮는 어떤 교류인가요?","options":[{"t":"물자 교류","correct":true},{"t":"기술 교류","mis":"SO4-1-u3-X30"},{"t":"문화 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["쌀을 보내요.","생산물이에요.","물자 교류예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
