INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#10','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C3',2,'mc','auto','일지 ②의 ㉰처럼 가게에 직접 가서 살펴보면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u3-X09','SO4-1-u3-X10']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"mc","stem":"일지 ②의 ㉰처럼 가게에 직접 가서 살펴보면 좋은 점은 무엇인가요?","options":[{"t":"직접 열고 닫아 보며 궁금한 것을 물어볼 수 있어요","correct":true},{"t":"여러 가게 값을 한눈에 볼 수 있어요","mis":"SO4-1-u3-X09"},{"t":"1년 써 본 경험을 들을 수 있어요","mis":"SO4-1-u3-X09"},{"t":"광고가 맞는지 저절로 알게 돼요","mis":"SO4-1-u3-X10"}],"explanation":["가게에 갔어요.","직접 열어 봤어요.","보고 물어봐요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#11','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C5',2,'mc','auto','일지 ③에서 하람이가 가장 중요하게 여기는 기준은 무엇인가요?',ARRAY['SO4-1-u3-X18']::text[],false,'{"seq":11,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"mc","stem":"일지 ③에서 하람이가 가장 중요하게 여기는 기준은 무엇인가요?","options":[{"t":"품질","correct":true},{"t":"가격","mis":"SO4-1-u3-X18"},{"t":"디자인","mis":"SO4-1-u3-X18"},{"t":"세 기준 모두 같아요","mis":"SO4-1-u3-X18"}],"explanation":["최대 점수를 봐요.","10점이 가장 커요.","품질이에요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#12','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C4',2,'mc','auto','일지 ⑧에서 하람이가 대나무 칫솔을 고른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X16','SO4-1-u3-X13']::text[],false,'{"seq":12,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"mc","stem":"일지 ⑧에서 하람이가 대나무 칫솔을 고른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"환경에 도움이 되는 상품을 고르려고","correct":true},{"t":"가장 싸서","mis":"SO4-1-u3-X16"},{"t":"나에게만 좋아서","mis":"SO4-1-u3-X16"},{"t":"필요 없어도 사 두려고","mis":"SO4-1-u3-X13"}],"explanation":["대나무예요.","플라스틱을 줄여요.","환경을 생각했어요."],"asset":{"type":"passage","lines":["장터에서 하람이는 플라스틱 칫솔 대신 대나무 칫솔을 골랐다.","푸른내시는 쌀이 많지만 생선이 부족하다.","갯벌군은 생선이 많지만 쌀이 부족하다.","두 지역은 자매결연을 맺으려고 한다."],"title":"일지 ⑧ — 하람이네 반 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#13','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C8',2,'mc','auto','일지 ④에서 편리하거나 즐겁게 해 주는 생산끼리 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X23']::text[],false,'{"seq":13,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"mc","stem":"일지 ④에서 편리하거나 즐겁게 해 주는 생산끼리 묶은 것은 무엇인가요?","options":[{"t":"㉱ · ㉲","correct":true},{"t":"㉮ · ㉯","mis":"SO4-1-u3-X25"},{"t":"㉰ · ㉱","mis":"SO4-1-u3-X23"},{"t":"㉮ · ㉲","mis":"SO4-1-u3-X25"}],"explanation":["태워 줘요.","공연해요.","㉱·㉲예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#14','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C9',2,'mc','auto','일지 ⑤의 갯벌군과 푸른내시가 교류하면 어떻게 되나요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X27']::text[],false,'{"seq":14,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"mc","stem":"일지 ⑤의 갯벌군과 푸른내시가 교류하면 어떻게 되나요?","options":[{"t":"갯벌군은 쌀을, 푸른내시는 조개와 생선을 얻어 모두 이로워요","correct":true},{"t":"갯벌군만 이로워요","mis":"SO4-1-u3-X28"},{"t":"푸른내시만 손해를 봐요","mis":"SO4-1-u3-X28"},{"t":"아무것도 달라지지 않아요","mis":"SO4-1-u3-X27"}],"explanation":["서로 줘요.","서로 받아요.","모두 이로워요."],"asset":{"type":"passage","lines":["푸른내시 — 넓은 강과 들이 있어 쌀이 많이 나지만, 바다가 없다.","갯벌군 — 갯벌이 넓어 조개와 생선이 많이 나지만, 쌀이 부족하다.","산마루군 — 산비탈에 과수원이 많아 사과가 잘 난다."],"title":"일지 ⑤ — 세 지역 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#15','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C10',2,'mc','auto','일지 ⑥에서 물자 교류끼리 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":15,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"mc","stem":"일지 ⑥에서 물자 교류끼리 묶은 것은 무엇인가요?","options":[{"t":"㉮ · ㉯","correct":true},{"t":"㉰ · ㉱","mis":"SO4-1-u3-X30"},{"t":"㉮ · ㉰","mis":"SO4-1-u3-X30"},{"t":"㉱ · ㉲","mis":"SO4-1-u3-X29"}],"explanation":["쌀이에요.","조개예요.","㉮·㉯예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#16','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C11',2,'mc','auto','일지 ⑦에서 푸른내시로 들어오는 교류는 무엇인가요?',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":16,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"mc","stem":"일지 ⑦에서 푸른내시로 들어오는 교류는 무엇인가요?","options":[{"t":"갯벌군의 조개","correct":true},{"t":"갯벌군으로 가는 쌀","mis":"SO4-1-u3-X32"},{"t":"산마루군으로 가는 공연단","mis":"SO4-1-u3-X32"},{"t":"들어오는 교류는 없어요","mis":"SO4-1-u3-X32"}],"explanation":["노란 화살표를 봐요.","푸른내시로 와요.","조개예요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
