INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#18','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C6',3,'mc','auto','「자원이 부족해요 → (    ) → 기준과 정보로 합리적 선택」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X20','SO4-1-u3-X10']::text[],false,'{"seq":18,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"mc","stem":"「자원이 부족해요 → (    ) → 기준과 정보로 합리적 선택」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"무엇을 고를지 고민하는 선택의 문제","correct":true},{"t":"사람·동물·환경을 생각하는 착한 소비","mis":"SO4-1-u3-X20"},{"t":"적은 비용으로 큰 만족","mis":"SO4-1-u3-X20"},{"t":"광고를 그대로 믿기","mis":"SO4-1-u3-X10"}],"explanation":["부족해요.","고민해요.","선택의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#19','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C8',3,'mc','auto','일지 ④에서 무가 김치가 되어 손님에게 가기까지 일어난 활동을 차례대로 나타낸 것은 무엇인가요?',ARRAY['SO4-1-u3-X25','SO4-1-u3-X23']::text[],false,'{"seq":19,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"일지 ④에서 무가 김치가 되어 손님에게 가기까지 일어난 활동을 차례대로 나타낸 것은 무엇인가요?","options":[{"t":"자연에서 얻는 생산 → 만드는 생산 → 소비","correct":true},{"t":"만드는 생산 → 자연에서 얻는 생산 → 소비","mis":"SO4-1-u3-X25"},{"t":"소비 → 만드는 생산 → 자연에서 얻는 생산","mis":"SO4-1-u3-X23"},{"t":"자연에서 얻는 생산 → 소비 → 만드는 생산","mis":"SO4-1-u3-X23"}],"explanation":["무를 길러요.","김치를 만들어요.","손님이 사요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#20','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C11',3,'mc','auto','일지 ⑦을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X29','SO4-1-u3-X33']::text[],false,'{"seq":20,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"일지 ⑦을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"푸른내시는 물자를 주고받고, 기술을 받고, 문화를 나눠요","correct":true},{"t":"푸른내시는 주기만 해요","mis":"SO4-1-u3-X32"},{"t":"푸른내시는 물자만 주고받아요","mis":"SO4-1-u3-X29"},{"t":"푸른내시는 혼자서도 모두 해결해요","mis":"SO4-1-u3-X33"}],"explanation":["화살표를 모두 봐요.","들어오고 나가요.","여러 교류예요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#21','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C12',3,'mc','auto','일지 ⑧의 두 지역이 자매결연을 맺으면 좋은 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X34','SO4-1-u3-X28']::text[],false,'{"seq":21,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"mc","stem":"일지 ⑧의 두 지역이 자매결연을 맺으면 좋은 까닭은 무엇인가요?","options":[{"t":"서로 부족한 쌀과 생선을 채워 줄 수 있어서","correct":true},{"t":"두 지역 모두 같은 것이 나서","mis":"SO4-1-u3-X34"},{"t":"한 지역만 이로워서","mis":"SO4-1-u3-X28"},{"t":"이름이 비슷해서","mis":"SO4-1-u3-X34"}],"explanation":["푸른내시는 쌀이 많아요.","갯벌군은 생선이 많아요.","서로 채워요."],"asset":{"type":"passage","lines":["장터에서 하람이는 플라스틱 칫솔 대신 대나무 칫솔을 골랐다.","푸른내시는 쌀이 많지만 생선이 부족하다.","갯벌군은 생선이 많지만 쌀이 부족하다.","두 지역은 자매결연을 맺으려고 한다."],"title":"일지 ⑧ — 하람이네 반 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#22','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C2',3,'mc','auto','다음 가운데 합리적 선택이라고 보기 어려운 것은 무엇인가요?',ARRAY['SO4-1-u3-X07','SO4-1-u3-X06','SO4-1-u3-X13']::text[],false,'{"seq":22,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"mc","stem":"다음 가운데 합리적 선택이라고 보기 어려운 것은 무엇인가요?","options":[{"t":"광고 문구만 보고 비싼 운동화를 바로 사요","correct":true},{"t":"여러 가게 값을 견주고 사요","mis":"SO4-1-u3-X07"},{"t":"조금만 고치면 되는 의자를 고쳐 써요","mis":"SO4-1-u3-X06"},{"t":"꼭 필요한지 생각하고 사요","mis":"SO4-1-u3-X13"}],"explanation":["따져 봤나요?","광고만 봤어요.","합리적이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#23','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C3',4,'essay','teacher','일지 ②의 정보를 살펴 하람이가 어느 가게에서 필통을 사면 좋을지 쓰고, 믿을 만한 정보와 조심할 정보를 근거로 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u3-C3","difficulty":4,"kind":"essay","stem":"일지 ②의 정보를 살펴 하람이가 어느 가게에서 필통을 사면 좋을지 쓰고, 믿을 만한 정보와 조심할 정보를 근거로 까닭을 쓰세요.","answer_guide":{"answer":"예: 가게 ②에서 사면 좋겠어요. ㉯를 보면 같은 필통이 가게 ②에서 더 싸고, ㉮와 ㉰로 지퍼가 튼튼하고 칸이 넉넉하다는 것을 확인했어요. ㉱는 「무조건」처럼 근거 없이 부풀린 광고라 믿지 않아요.","scoring_points":["가게를 골랐는가","믿을 만한 정보를 근거로 썼는가","조심할 정보를 가려냈는가"]},"explanation":["값을 견줘요.","품질을 확인해요.","광고를 가려요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#24','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C12',4,'essay','teacher','일지 ⑤~⑦을 보고 푸른내시가 다른 두 지역과 무엇을 주고받는지 쓰고, 상호 의존과 함께 발전을 넣어 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u3-C12","difficulty":4,"kind":"essay","stem":"일지 ⑤~⑦을 보고 푸른내시가 다른 두 지역과 무엇을 주고받는지 쓰고, 상호 의존과 함께 발전을 넣어 정리하세요.","answer_guide":{"answer":"예: 푸른내시는 갯벌군에 쌀을 보내고 조개를 받아요. 산마루군에서는 사과 기르는 기술을 받고 강변 축제 공연단을 보내요. 이렇게 세 지역은 서로 의지하는 상호 의존 관계이고, 부족함을 채워 주며 함께 발전해요.","scoring_points":["갯벌군과 주고받는 것을 썼는가","산마루군과 주고받는 것을 썼는가","상호 의존과 함께 발전을 넣었는가"]},"explanation":["지도를 봐요.","주고받는 것을 써요.","상호 의존으로 정리해요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_a#25','soc',4,1,'u3','','g4_1_soc_u3_review_a','unit_review','SO4-1-u3-C6',4,'essay','teacher','3단원에서 배운 희소성·합리적 선택·생산과 소비·교류 가운데 세 가지를 넣어 푸른내시 장터 이야기를 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u3-C6","difficulty":4,"kind":"essay","stem":"3단원에서 배운 희소성·합리적 선택·생산과 소비·교류 가운데 세 가지를 넣어 푸른내시 장터 이야기를 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 하람이는 용돈이 부족해 사고 싶은 것을 다 살 수 없어서 꼭 필요한 것부터 합리적 선택을 했어요. 장터에서는 할머니가 김치를 담가 팔고 손님이 사는 생산과 소비가 함께 일어나요. 장터의 조개는 갯벌군에서 교류로 온 것이에요.","scoring_points":["세 가지를 넣었는가","뜻에 맞게 썼는가","세 문장으로 장터 이야기를 썼는가"]},"explanation":["세 가지를 골라요.","장터를 떠올려요.","이야기를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#1','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C1',1,'sa','auto','일지 ①처럼 원하는 것에 비해 돈이 부족한 상태를 자원의 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"sa","stem":"일지 ①처럼 원하는 것에 비해 돈이 부족한 상태를 자원의 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["희소성"],"explanation":["원하는 것이 많아요.","돈이 부족해요.","희소성이에요."],"asset":{"type":"passage","lines":["하람이의 용돈 — 6,000원","책 — 4,000원","모자 — 3,000원","공 — 2,500원","스티커 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"일지 ① — 하람이의 장바구니"},"mis":"SO4-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#2','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C2',1,'sa','auto','고쳐 쓸지 새로 살지 정할 때 견주는 두 가지 가운데 하나는 비용이에요. 다른 하나는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"sa","stem":"고쳐 쓸지 새로 살지 정할 때 견주는 두 가지 가운데 하나는 비용이에요. 다른 하나는 무엇인가요? 두 글자로 쓰세요.","answer":["만족","만족감"],"explanation":["비용과 견줘요.","얼마나 좋은가요?","만족이에요."],"mis":"SO4-1-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#3','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C3',1,'sa','auto','일지 ②에서 같은 필통을 더 싸게 파는 곳은 가게 몇 번인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"sa","stem":"일지 ②에서 같은 필통을 더 싸게 파는 곳은 가게 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["값을 견줘요.","5,500원이 더 싸요.","가게 ②예요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"},"mis":"SO4-1-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#4','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C4',1,'sa','auto','일지 ⑧에서 하람이가 대나무 칫솔을 고른 것처럼 사람·동물·환경을 생각하는 소비를 무엇이라고 하나요?','{}'::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"sa","stem":"일지 ⑧에서 하람이가 대나무 칫솔을 고른 것처럼 사람·동물·환경을 생각하는 소비를 무엇이라고 하나요?","answer":["착한 소비","착한소비"],"explanation":["환경을 생각해요.","함께 좋은 소비예요.","착한 소비예요."],"asset":{"type":"passage","lines":["장터에서 하람이는 플라스틱 칫솔 대신 대나무 칫솔을 골랐다.","푸른내시는 쌀이 많지만 생선이 부족하다.","갯벌군은 생선이 많지만 쌀이 부족하다.","두 지역은 자매결연을 맺으려고 한다."],"title":"일지 ⑧ — 하람이네 반 소식"},"mis":"SO4-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#5','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C7',1,'sa','auto','일지 ④의 ㉯처럼 김치를 담가 파는 것은 생산과 소비 가운데 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"sa","stem":"일지 ④의 ㉯처럼 김치를 담가 파는 것은 생산과 소비 가운데 무엇인가요? 두 글자로 쓰세요.","answer":["생산"],"explanation":["김치를 담가요.","만들어요.","생산이에요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"},"mis":"SO4-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#6','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C8',1,'sa','auto','일지 ④의 ㉱처럼 손님을 태워 주어 편리하게 해 주는 생산을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"sa","stem":"일지 ④의 ㉱처럼 손님을 태워 주어 편리하게 해 주는 생산을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["서비스"],"explanation":["태워 줘요.","편리해요.","서비스예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"},"mis":"SO4-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#7','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C9',1,'sa','auto','지역끼리 서로 필요한 것을 주고받는 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"sa","stem":"지역끼리 서로 필요한 것을 주고받는 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["교류"],"explanation":["서로 줘요.","서로 받아요.","교류예요."],"mis":"SO4-1-u3-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#8','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C10',1,'sa','auto','일지 ⑥의 ㉰처럼 기술이나 정보를 주고받는 교류를 ○○ 교류라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"sa","stem":"일지 ⑥의 ㉰처럼 기술이나 정보를 주고받는 교류를 ○○ 교류라고 해요. 두 글자로 쓰세요.","answer":["기술"],"explanation":["기르는 법이에요.","기술이에요.","기술 교류예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"},"mis":"SO4-1-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#9','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C1',2,'ox','auto','숙소 요금처럼 같은 것이라도 원하는 사람이 많아지면 더 귀해질 수 있어요.',ARRAY['SO4-1-u3-X02']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"ox","stem":"숙소 요금처럼 같은 것이라도 원하는 사람이 많아지면 더 귀해질 수 있어요.","answer":"O","reason_options":[{"t":"희소성은 원하는 정도에 따라서도 달라지기 때문에","correct":true},{"t":"희소성은 물건의 양으로만 정해지기 때문에","mis":"SO4-1-u3-X02"}],"mis":"SO4-1-u3-X02","explanation":["원하는 사람이 늘어요.","더 귀해져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#10','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C3',2,'ox','auto','일지 ②의 ㉮·㉯·㉰를 함께 살펴보면 더 정확하게 고를 수 있어요.',ARRAY['SO4-1-u3-X12']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"ox","stem":"일지 ②의 ㉮·㉯·㉰를 함께 살펴보면 더 정확하게 고를 수 있어요.","answer":"O","reason_options":[{"t":"방법마다 알 수 있는 것이 달라 서로 보태지기 때문에","correct":true},{"t":"정보는 하나만 보는 것이 가장 정확하기 때문에","mis":"SO4-1-u3-X12"}],"mis":"SO4-1-u3-X12","explanation":["경험·값·직접 확인이에요.","서로 보태져요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#11','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C5',2,'sa','auto','일지 ③에서 운동화 ㉮의 점수 합계는 몇 점인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"sa","stem":"일지 ③에서 운동화 ㉮의 점수 합계는 몇 점인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["8 + 6 + 6이에요.","모두 더해요.","20점이에요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"},"mis":"SO4-1-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#12','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C4',2,'ox','auto','기준에 따라 가장 좋은 물건이 달라질 수 있어요.',ARRAY['SO4-1-u3-X15']::text[],false,'{"seq":12,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"ox","stem":"기준에 따라 가장 좋은 물건이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"가격·품질·서비스마다 앞서는 물건이 다르기 때문에","correct":true},{"t":"어느 기준으로 보아도 가장 좋은 물건은 같기 때문에","mis":"SO4-1-u3-X15"}],"mis":"SO4-1-u3-X15","explanation":["기준을 바꿔요.","앞서는 것이 바뀌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#13','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C7',2,'ox','auto','일지 ④의 ㉯와 ㉰는 생산과 소비가 짝을 이룬 모습이에요.',ARRAY['SO4-1-u3-X24']::text[],false,'{"seq":13,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"ox","stem":"일지 ④의 ㉯와 ㉰는 생산과 소비가 짝을 이룬 모습이에요.","answer":"O","reason_options":[{"t":"할머니가 담가 판 김치를 손님이 사기 때문에","correct":true},{"t":"생산과 소비는 서로 관계없기 때문에","mis":"SO4-1-u3-X24"}],"mis":"SO4-1-u3-X24","explanation":["할머니가 팔아요.","손님이 사요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#14','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C9',2,'ox','auto','일지 ⑤의 푸른내시는 바다가 없어도 생선을 혼자서 넉넉히 얻을 수 있어요.',ARRAY['SO4-1-u3-X27']::text[],false,'{"seq":14,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"ox","stem":"일지 ⑤의 푸른내시는 바다가 없어도 생선을 혼자서 넉넉히 얻을 수 있어요.","answer":"X","reason_options":[{"t":"바다가 없어 생선은 교류로 얻어야 하기 때문에","correct":true},{"t":"한 지역이 필요한 것을 모두 만들 수 있기 때문에","mis":"SO4-1-u3-X27"}],"mis":"SO4-1-u3-X27","explanation":["바다가 없어요.","생선은 갯벌군에 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["푸른내시 — 넓은 강과 들이 있어 쌀이 많이 나지만, 바다가 없다.","갯벌군 — 갯벌이 넓어 조개와 생선이 많이 나지만, 쌀이 부족하다.","산마루군 — 산비탈에 과수원이 많아 사과가 잘 난다."],"title":"일지 ⑤ — 세 지역 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#15','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C10',2,'ox','auto','일지 ⑥의 ㉰는 사과를 주고받는 물자 교류예요.',ARRAY['SO4-1-u3-X30']::text[],false,'{"seq":15,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"ox","stem":"일지 ⑥의 ㉰는 사과를 주고받는 물자 교류예요.","answer":"X","reason_options":[{"t":"사과 기르는 법을 알려 주는 기술 교류이기 때문에","correct":true},{"t":"농사와 관계있으면 모두 물자 교류이기 때문에","mis":"SO4-1-u3-X30"}],"mis":"SO4-1-u3-X30","explanation":["기르는 법이에요.","기술이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#16','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C11',2,'ox','auto','일지 ⑦에서 푸른내시에서 갯벌군으로 가는 쌀은 파란 화살표로 그렸어요.',ARRAY['SO4-1-u3-X32']::text[],false,'{"seq":16,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"ox","stem":"일지 ⑦에서 푸른내시에서 갯벌군으로 가는 쌀은 파란 화살표로 그렸어요.","answer":"O","reason_options":[{"t":"우리 지역에서 나가는 교류이기 때문에","correct":true},{"t":"나가는 교류는 노란색이기 때문에","mis":"SO4-1-u3-X32"}],"mis":"SO4-1-u3-X32","explanation":["쌀이 나가요.","나가는 교류예요.","그래서 O예요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#17','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C5',3,'error','auto','일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X18','SO4-1-u3-X19']::text[],false,'{"seq":17,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"error","stem":"일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「모든 기준의 최대 점수를 똑같이 해야 바른 점수표야.」","correct":true,"mis_target":"SO4-1-u3-X18"},{"t":"친구 가 — 「하람이는 품질을 가장 중요하게 여겨.」","mis":"SO4-1-u3-X18"},{"t":"친구 다 — 「점수는 하람이가 판단해서 매긴 거야.」","mis":"SO4-1-u3-X19"}],"explanation":["중요한 기준이 있어요.","최대 점수를 크게 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#18','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C6',3,'error','auto','하람이네 반이 시장 놀이를 준비하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X20','SO4-1-u3-X10']::text[],false,'{"seq":18,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"error","stem":"하람이네 반이 시장 놀이를 준비하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「물건 값은 배운 것과 관계없이 아무렇게나 정하면 돼.」","correct":true,"mis_target":"SO4-1-u3-X21"},{"t":"친구 가 — 「직접 만든 하나뿐인 엽서는 희소성을 살려 홍보하자.」","mis":"SO4-1-u3-X20"},{"t":"친구 나 — 「홍보 문구는 부풀리지 말고 사실대로 쓰자.」","mis":"SO4-1-u3-X10"}],"explanation":["배운 것을 살려요.","희소성과 쓸모예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#19','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C8',3,'error','auto','일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X22','SO4-1-u3-X25','SO4-1-u3-X23']::text[],false,'{"seq":19,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"error","stem":"일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉱ 버스 기사는 물건을 만들지 않으니 생산이 아니야.」","correct":true,"mis_target":"SO4-1-u3-X22"},{"t":"친구 나 — 「㉮는 자연에서 얻는 활동이야.」","mis":"SO4-1-u3-X25"},{"t":"친구 다 — 「㉰는 소비야.」","mis":"SO4-1-u3-X23"}],"explanation":["태워 주는 일이에요.","편리하게 해 줘요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#20','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C11',3,'error','auto','일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X30','SO4-1-u3-X31']::text[],false,'{"seq":20,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"error","stem":"일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「산마루군에서 오는 사과 기르는 기술은 파란 화살표야.」","correct":true,"mis_target":"SO4-1-u3-X32"},{"t":"친구 가 — 「갯벌군과는 물자를 주고받아.」","mis":"SO4-1-u3-X30"},{"t":"친구 다 — 「푸른내시를 가운데에 두었어.」","mis":"SO4-1-u3-X31"}],"explanation":["들어오는 교류예요.","노란색이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#21','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C12',3,'error','auto','일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X28','SO4-1-u3-X26']::text[],false,'{"seq":21,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"error","stem":"일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「푸른내시는 갯벌군에게서 받기만 하고 줄 것은 없어.」","correct":true,"mis_target":"SO4-1-u3-X28"},{"t":"친구 가 — 「푸른내시는 쌀을 보낼 수 있어.」","mis":"SO4-1-u3-X26"},{"t":"친구 나 — 「갯벌군은 생선을 보낼 수 있어.」","mis":"SO4-1-u3-X26"}],"explanation":["푸른내시도 줄 것이 있어요.","쌀이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["장터에서 하람이는 플라스틱 칫솔 대신 대나무 칫솔을 골랐다.","푸른내시는 쌀이 많지만 생선이 부족하다.","갯벌군은 생선이 많지만 쌀이 부족하다.","두 지역은 자매결연을 맺으려고 한다."],"title":"일지 ⑧ — 하람이네 반 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#22','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C4',3,'error','auto','물건 고르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u3-X16','SO4-1-u3-X14','SO4-1-u3-X08']::text[],false,'{"seq":22,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"error","stem":"물건 고르기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「착한 소비는 가장 싼 것을 사는 거야.」","correct":true,"mis_target":"SO4-1-u3-X16"},{"t":"친구 나 — 「무상 수리 기간은 서비스 기준이야.」","mis":"SO4-1-u3-X14"},{"t":"친구 다 — 「우선순위가 다르면 고른 것도 달라.」","mis":"SO4-1-u3-X08"}],"explanation":["착한 소비는 함께예요.","싼 것이 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#23','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C5',4,'mc','auto','하람이가 디자인을 가장 중요하게 여기기로 바꾸어 디자인 10점 · 품질 8점 · 가격 6점으로 다시 매겼어요. ㉮ 9·6·4, ㉯ 5·8·2, ㉰ 6·5·6(디자인·품질·가격 차례)이라면 어느 운동화를 고르나요?',ARRAY['SO4-1-u3-X17','SO4-1-u3-X15']::text[],false,'{"seq":23,"concept":"SO4-1-u3-C5","difficulty":4,"kind":"mc","stem":"하람이가 디자인을 가장 중요하게 여기기로 바꾸어 디자인 10점 · 품질 8점 · 가격 6점으로 다시 매겼어요. ㉮ 9·6·4, ㉯ 5·8·2, ㉰ 6·5·6(디자인·품질·가격 차례)이라면 어느 운동화를 고르나요?","options":[{"t":"㉮ — 19점","correct":true},{"t":"㉯ — 품질이 8점이라서","mis":"SO4-1-u3-X17"},{"t":"㉰ — 가격이 6점이라서","mis":"SO4-1-u3-X17"},{"t":"셋 모두 같아요","mis":"SO4-1-u3-X15"}],"explanation":["㉮ 9 + 6 + 4 = 19예요.","㉯ 15점, ㉰ 17점이에요.","㉮예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#24','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C9',4,'mc','auto','산마루군에 우박이 내려 사과 농사가 어려워졌어요. 일지 ⑦을 볼 때 푸른내시가 할 수 있는 일과 그 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X28','SO4-1-u3-X27']::text[],false,'{"seq":24,"concept":"SO4-1-u3-C9","difficulty":4,"kind":"mc","stem":"산마루군에 우박이 내려 사과 농사가 어려워졌어요. 일지 ⑦을 볼 때 푸른내시가 할 수 있는 일과 그 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"봉사단과 쌀을 보내 도와요 — 서로 의존하며 함께 살아가기 때문에","correct":true},{"t":"모른 척해요 — 다른 지역 일이기 때문에","mis":"SO4-1-u3-X33"},{"t":"받은 기술을 돌려줘요 — 손해를 보면 안 되기 때문에","mis":"SO4-1-u3-X28"},{"t":"교류를 끊어요 — 혼자서도 다 만들 수 있기 때문에","mis":"SO4-1-u3-X27"}],"explanation":["산마루군이 어려워요.","서로 의지해요.","도와요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_b#25','soc',4,1,'u3','','g4_1_soc_u3_review_b','unit_review','SO4-1-u3-C12',4,'mc','auto','3단원 「경제활동과 지역 간 교류」에서 배운 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u3-X20','SO4-1-u3-X24','SO4-1-u3-X33']::text[],false,'{"seq":25,"concept":"SO4-1-u3-C12","difficulty":4,"kind":"mc","stem":"3단원 「경제활동과 지역 간 교류」에서 배운 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"한 지역이 필요한 것을 모두 만들 수 있어 교류는 필요 없어요","correct":true},{"t":"자원이 부족해 선택의 문제가 생겨요","mis":"SO4-1-u3-X20"},{"t":"생산과 소비는 짝을 이뤄요","mis":"SO4-1-u3-X24"},{"t":"지역들은 서로 의존하며 발전해요","mis":"SO4-1-u3-X33"}],"explanation":["한 지역이 다 만들까요?","아니에요.","알맞지 않은 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#1','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C1',1,'ox','auto','일지 ①에서 하람이는 용돈으로 네 가지를 모두 살 수 있어요.',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"ox","stem":"일지 ①에서 하람이는 용돈으로 네 가지를 모두 살 수 있어요.","answer":"X","reason_options":[{"t":"네 가지를 사려면 10,500원이 들어 용돈보다 많기 때문에","correct":true},{"t":"원하는 것은 언제나 모두 살 수 있기 때문에","mis":"SO4-1-u3-X04"}],"mis":"SO4-1-u3-X04","explanation":["10,500원이 들어요.","용돈은 6,000원이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["하람이의 용돈 — 6,000원","책 — 4,000원","모자 — 3,000원","공 — 2,500원","스티커 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"일지 ① — 하람이의 장바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#2','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C2',1,'ox','auto','여러 가지를 따져 보지 않고 고르면 후회하기 쉬워요.',ARRAY['SO4-1-u3-X07']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"ox","stem":"여러 가지를 따져 보지 않고 고르면 후회하기 쉬워요.","answer":"O","reason_options":[{"t":"중요한 것을 놓쳐 만족하지 못할 수 있기 때문에","correct":true},{"t":"따져 보지 않아도 언제나 만족하기 때문에","mis":"SO4-1-u3-X07"}],"mis":"SO4-1-u3-X07","explanation":["한 가지만 봐요.","놓친 것이 생겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#3','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C3',1,'ox','auto','일지 ②의 ㉱ 광고는 정말 그런지 확인해야 해요.',ARRAY['SO4-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"ox","stem":"일지 ②의 ㉱ 광고는 정말 그런지 확인해야 해요.","answer":"O","reason_options":[{"t":"근거 없이 부풀린 과장된 광고일 수 있기 때문에","correct":true},{"t":"광고에 나온 말은 모두 사실이기 때문에","mis":"SO4-1-u3-X10"}],"mis":"SO4-1-u3-X10","explanation":["「무조건」이라고 해요.","근거가 없어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#4','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C4',1,'ox','auto','물건을 사기 전에 이미 가지고 있거나 빌려 쓸 수 있는지 확인해요.',ARRAY['SO4-1-u3-X13']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"ox","stem":"물건을 사기 전에 이미 가지고 있거나 빌려 쓸 수 있는지 확인해요.","answer":"O","reason_options":[{"t":"이미 있으면 사지 않아도 되어 자원을 아낄 수 있기 때문에","correct":true},{"t":"갖고 싶으면 이미 있어도 사야 하기 때문에","mis":"SO4-1-u3-X13"}],"mis":"SO4-1-u3-X13","explanation":["이미 있나요?","빌릴 수 있나요?","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#5','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C7',1,'ox','auto','일지 ④의 ㉲ 마술 공연도 생산이에요.',ARRAY['SO4-1-u3-X22']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"ox","stem":"일지 ④의 ㉲ 마술 공연도 생산이에요.","answer":"O","reason_options":[{"t":"사람들의 생활을 즐겁게 해 주기 때문에","correct":true},{"t":"물건을 만들지 않으면 생산이 아니기 때문에","mis":"SO4-1-u3-X22"}],"mis":"SO4-1-u3-X22","explanation":["공연이에요.","즐겁게 해 줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#6','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C8',1,'ox','auto','일지 ④의 ㉯ 김치 담그기는 만드는 활동이에요.',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"ox","stem":"일지 ④의 ㉯ 김치 담그기는 만드는 활동이에요.","answer":"O","reason_options":[{"t":"무로 김치를 만들어 내기 때문에","correct":true},{"t":"김치 담그기는 자연에서 얻는 활동이기 때문에","mis":"SO4-1-u3-X25"}],"mis":"SO4-1-u3-X25","explanation":["무로 만들어요.","김치가 생겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#7','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C9',1,'ox','auto','일지 ⑤의 세 지역은 잘 나는 것이 서로 달라요.',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"ox","stem":"일지 ⑤의 세 지역은 잘 나는 것이 서로 달라요.","answer":"O","reason_options":[{"t":"강과 들, 갯벌, 산비탈처럼 자연환경이 다르기 때문에","correct":true},{"t":"지역마다 나는 것은 모두 같기 때문에","mis":"SO4-1-u3-X26"}],"mis":"SO4-1-u3-X26","explanation":["자연환경이 달라요.","나는 것도 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["푸른내시 — 넓은 강과 들이 있어 쌀이 많이 나지만, 바다가 없다.","갯벌군 — 갯벌이 넓어 조개와 생선이 많이 나지만, 쌀이 부족하다.","산마루군 — 산비탈에 과수원이 많아 사과가 잘 난다."],"title":"일지 ⑤ — 세 지역 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#8','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C10',1,'ox','auto','일지 ⑥의 ㉲처럼 어려운 지역에 가서 돕는 것도 교류예요.',ARRAY['SO4-1-u3-X29']::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"ox","stem":"일지 ⑥의 ㉲처럼 어려운 지역에 가서 돕는 것도 교류예요.","answer":"O","reason_options":[{"t":"봉사 활동으로 도움을 주고받기 때문에","correct":true},{"t":"교류는 물건을 주고받는 것뿐이기 때문에","mis":"SO4-1-u3-X29"}],"mis":"SO4-1-u3-X29","explanation":["봉사단이 가요.","도와요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#9','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C1',2,'match','auto','일지 ①과 관련된 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"match","stem":"일지 ①과 관련된 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"선택","r":"무엇을 고를지 정하는 것"},{"l":"포기","r":"고르지 못한 것을 내려놓는 것"}],"mis":"SO4-1-u3-X04","explanation":["고르는 것이에요.","내려놓는 것이에요.","뜻을 이어요."],"asset":{"type":"passage","lines":["하람이의 용돈 — 6,000원","책 — 4,000원","모자 — 3,000원","공 — 2,500원","스티커 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"일지 ① — 하람이의 장바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#10','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C3',2,'blank','auto','정보를 쓸 때는 (    )가 믿을 만한지, 정확한 정보인지 확인해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X09']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C3","difficulty":2,"kind":"blank","stem":"정보를 쓸 때는 (    )가 믿을 만한지, 정확한 정보인지 확인해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출처","correct":true},{"t":"광고 모델","mis":"SO4-1-u3-X10"},{"t":"글자 크기","mis":"SO4-1-u3-X10"},{"t":"가격","mis":"SO4-1-u3-X09"}],"explanation":["어디서 나왔나요?","나온 곳이에요.","출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#11','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C5',2,'ox','auto','일지 ③에서 하람이에게 합리적인 운동화는 품질 점수가 가장 높은 ㉯예요.',ARRAY['SO4-1-u3-X17']::text[],false,'{"seq":11,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"ox","stem":"일지 ③에서 하람이에게 합리적인 운동화는 품질 점수가 가장 높은 ㉯예요.","answer":"X","reason_options":[{"t":"합계를 견주면 ㉮가 20점으로 가장 크기 때문에","correct":true},{"t":"한 칸 점수가 가장 높은 것을 고르면 되기 때문에","mis":"SO4-1-u3-X17"}],"mis":"SO4-1-u3-X17","explanation":["㉯는 17점이에요.","㉮는 20점이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#12','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C4',2,'match','auto','가격과 품질 기준에서 살펴볼 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"match","stem":"가격과 품질 기준에서 살펴볼 점을 알맞게 이으세요.","pairs":[{"l":"가격","r":"가진 돈으로 살 수 있는지"},{"l":"품질","r":"오래 쓸 수 있고 안전한지"}],"mis":"SO4-1-u3-X14","explanation":["가격은 돈이에요.","품질은 튼튼함이에요.","알맞게 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#13','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C8',2,'match','auto','일지 ④의 모습과 생산 활동의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO4-1-u3-C8","difficulty":2,"kind":"match","stem":"일지 ④의 모습과 생산 활동의 종류를 알맞게 이으세요.","pairs":[{"l":"㉮ 무 기르기","r":"자연에서 얻는 활동"},{"l":"㉯ 김치 담그기","r":"만드는 활동"},{"l":"㉱ 손님 태워 주기","r":"편리하게 해 주는 활동"}],"mis":"SO4-1-u3-X25","explanation":["밭에서 길러요.","김치를 만들어요.","태워 줘요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#14','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C9',2,'blank','auto','지역마다 자연환경과 생산 (    )이 달라 잘 나는 것이 서로 달라요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X26']::text[],false,'{"seq":14,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"blank","stem":"지역마다 자연환경과 생산 (    )이 달라 잘 나는 것이 서로 달라요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기술","correct":true},{"t":"이름","mis":"SO4-1-u3-X26"},{"t":"인구","mis":"SO4-1-u3-X26"},{"t":"간판","mis":"SO4-1-u3-X26"}],"explanation":["자연환경이 달라요.","만드는 힘도 달라요.","기술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#15','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C10',2,'match','auto','일지 ⑥의 교류와 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"match","stem":"일지 ⑥의 교류와 종류를 알맞게 이으세요.","pairs":[{"l":"㉯ 조개가 시장에 온다","r":"물자 교류"},{"l":"㉰ 사과 기르는 법을 알려 준다","r":"기술 교류"},{"l":"㉱ 함께 강변 축제를 연다","r":"문화 교류"}],"mis":"SO4-1-u3-X30","explanation":["조개는 물자예요.","기르는 법은 기술이에요.","축제는 문화예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#16','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C11',2,'blank','auto','교류 지도를 만들 때는 먼저 지역 누리집이나 주요 (    )을 살펴 교류 사례를 조사해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":16,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"blank","stem":"교류 지도를 만들 때는 먼저 지역 누리집이나 주요 (    )을 살펴 교류 사례를 조사해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"생산물","correct":true},{"t":"간판","mis":"SO4-1-u3-X31"},{"t":"놀이터","mis":"SO4-1-u3-X31"},{"t":"날씨 예보","mis":"SO4-1-u3-X31"}],"explanation":["무엇이 나나요?","많이 나는 것이에요.","생산물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#17','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C5',3,'ox','auto','가격을 가장 중요하게 여기는 친구가 같은 운동화로 점수표를 만들면 ㉰를 고를 수도 있어요.',ARRAY['SO4-1-u3-X19']::text[],false,'{"seq":17,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"ox","stem":"가격을 가장 중요하게 여기는 친구가 같은 운동화로 점수표를 만들면 ㉰를 고를 수도 있어요.","answer":"O","reason_options":[{"t":"우선순위가 다르면 합계가 가장 큰 것이 달라질 수 있기 때문에","correct":true},{"t":"점수표의 답은 누가 만들어도 같기 때문에","mis":"SO4-1-u3-X19"}],"mis":"SO4-1-u3-X19","explanation":["㉰는 가격 점수가 높아요.","우선순위가 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#18','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C6',3,'ox','auto','희소성 때문에 선택의 문제가 생기고, 그래서 합리적 선택이 필요해요.',ARRAY['SO4-1-u3-X20']::text[],false,'{"seq":18,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"ox","stem":"희소성 때문에 선택의 문제가 생기고, 그래서 합리적 선택이 필요해요.","answer":"O","reason_options":[{"t":"자원이 부족해 다 가질 수 없으니 따져 보고 골라야 하기 때문에","correct":true},{"t":"합리적 선택을 하면 희소성이 생기기 때문에","mis":"SO4-1-u3-X20"}],"mis":"SO4-1-u3-X20","explanation":["부족해요.","골라야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#19','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C8',3,'ox','auto','손님이 장터에 오려고 버스를 타는 것은 소비예요.',ARRAY['SO4-1-u3-X23']::text[],false,'{"seq":19,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"ox","stem":"손님이 장터에 오려고 버스를 타는 것은 소비예요.","answer":"O","reason_options":[{"t":"버스 기사가 해 주는 서비스를 이용하기 때문에","correct":true},{"t":"버스를 타는 것은 만드는 활동이기 때문에","mis":"SO4-1-u3-X23"}],"mis":"SO4-1-u3-X23","explanation":["버스를 타요.","이용해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#20','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C11',3,'ox','auto','일지 ⑦에서 푸른내시와 산마루군은 기술 교류와 문화 교류를 함께 해요.',ARRAY['SO4-1-u3-X30']::text[],false,'{"seq":20,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"ox","stem":"일지 ⑦에서 푸른내시와 산마루군은 기술 교류와 문화 교류를 함께 해요.","answer":"O","reason_options":[{"t":"사과 기르는 기술이 들어오고 축제 공연단이 나가기 때문에","correct":true},{"t":"두 지역은 한 가지 교류만 하기 때문에","mis":"SO4-1-u3-X30"}],"mis":"SO4-1-u3-X30","explanation":["기술이 들어와요.","공연단이 나가요.","그래서 O예요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#21','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C12',3,'ox','auto','교류하며 서로 의지하면 두 지역이 함께 발전할 수 있어요.',ARRAY['SO4-1-u3-X33']::text[],false,'{"seq":21,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"ox","stem":"교류하며 서로 의지하면 두 지역이 함께 발전할 수 있어요.","answer":"O","reason_options":[{"t":"강점은 주고 부족함은 받아 모두 만족하기 때문에","correct":true},{"t":"서로 의지하면 두 지역 모두 약해지기 때문에","mis":"SO4-1-u3-X33"}],"mis":"SO4-1-u3-X33","explanation":["강점을 줘요.","부족함을 받아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#22','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C2',3,'ox','auto','같은 물건을 사도 사람마다 만족감이 다를 수 있어요.',ARRAY['SO4-1-u3-X08']::text[],false,'{"seq":22,"concept":"SO4-1-u3-C2","difficulty":3,"kind":"ox","stem":"같은 물건을 사도 사람마다 만족감이 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 중요하게 여기는 것이 다르기 때문에","correct":true},{"t":"같은 물건이면 누구나 똑같이 만족하기 때문에","mis":"SO4-1-u3-X08"}],"mis":"SO4-1-u3-X08","explanation":["중요한 것이 달라요.","만족도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#23','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C1',4,'essay','teacher','하람이가 일지 ①의 6,000원으로 무엇을 사고 무엇을 포기할지 정해 쓰고, 그렇게 고른 까닭을 합리적 선택과 이어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u3-C1","difficulty":4,"kind":"essay","stem":"하람이가 일지 ①의 6,000원으로 무엇을 사고 무엇을 포기할지 정해 쓰고, 그렇게 고른 까닭을 합리적 선택과 이어 쓰세요.","answer_guide":{"answer":"예: 책과 스티커를 사고 모자와 공은 포기할래요. 모두 사려면 10,500원이 들지만 용돈은 6,000원뿐이에요. 책은 오래 읽을 수 있어 만족이 크고, 남은 2,000원으로 스티커까지 사서 적은 비용으로 큰 만족을 얻는 합리적 선택을 했어요.","scoring_points":["살 것과 포기할 것을 썼는가","용돈으로 살 수 있게 골랐는가","합리적 선택과 이어 까닭을 썼는가"]},"explanation":["용돈을 봐요.","고르고 포기해요.","까닭을 써요."],"asset":{"type":"passage","lines":["하람이의 용돈 — 6,000원","책 — 4,000원","모자 — 3,000원","공 — 2,500원","스티커 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"일지 ① — 하람이의 장바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#24','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C10',4,'essay','teacher','일지 ⑥의 교류 가운데 두 가지를 골라 어떤 교류인지 쓰고, 그 교류로 두 지역이 각각 무엇을 얻는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u3-C10","difficulty":4,"kind":"essay","stem":"일지 ⑥의 교류 가운데 두 가지를 골라 어떤 교류인지 쓰고, 그 교류로 두 지역이 각각 무엇을 얻는지 쓰세요.","answer_guide":{"answer":"예: ㉮는 물자 교류예요. 갯벌군은 부족한 쌀을 얻고, 푸른내시는 쌀을 팔 곳을 얻어요. ㉱는 문화 교류예요. 두 지역 사람들은 함께 축제를 즐기고 서로의 문화를 알게 돼요.","scoring_points":["교류 두 가지를 골랐는가","종류를 바르게 썼는가","두 지역이 얻는 것을 썼는가"]},"explanation":["두 가지를 골라요.","종류를 써요.","얻는 것을 써요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_c#25','soc',4,1,'u3','','g4_1_soc_u3_review_c','unit_review','SO4-1-u3-C7',4,'essay','teacher','일지 ④의 장터에서 생산과 소비를 하나씩 찾아 쓰고, 그 생산이나 소비가 다른 지역과의 교류와 어떻게 이어질 수 있는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u3-C7","difficulty":4,"kind":"essay","stem":"일지 ④의 장터에서 생산과 소비를 하나씩 찾아 쓰고, 그 생산이나 소비가 다른 지역과의 교류와 어떻게 이어질 수 있는지 쓰세요.","answer_guide":{"answer":"예: ㉯ 할머니가 김치를 담가 파는 것은 생산이고, ㉰ 손님이 김치를 사는 것은 소비예요. 김치에 넣을 젓갈이 갯벌군에서 온다면, 이 생산은 갯벌군과의 물자 교류와 이어져요.","scoring_points":["생산을 찾았는가","소비를 찾았는가","교류와 이어 썼는가"]},"explanation":["생산을 찾아요.","소비를 찾아요.","교류와 이어요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#1','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C1',1,'mc','auto','일지 ①에서 하람이가 책을 사면, 남은 돈으로 살 수 없는 것은 무엇인가요?',ARRAY['SO4-1-u3-X04']::text[],false,'{"seq":1,"concept":"SO4-1-u3-C1","difficulty":1,"kind":"mc","stem":"일지 ①에서 하람이가 책을 사면, 남은 돈으로 살 수 없는 것은 무엇인가요?","options":[{"t":"모자","correct":true},{"t":"스티커","mis":"SO4-1-u3-X04"},{"t":"스티커 두 개","mis":"SO4-1-u3-X04"},{"t":"살 수 없는 것은 없어요","mis":"SO4-1-u3-X04"}],"explanation":["6,000원에서 4,000원을 써요.","2,000원이 남아요.","모자는 살 수 없어요."],"asset":{"type":"passage","lines":["하람이의 용돈 — 6,000원","책 — 4,000원","모자 — 3,000원","공 — 2,500원","스티커 — 1,000원","네 가지를 모두 사려면 10,500원이 든다."],"title":"일지 ① — 하람이의 장바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#2','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C2',1,'mc','auto','사람마다 합리적 선택이 다를 수 있는 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X08','SO4-1-u3-X06']::text[],false,'{"seq":2,"concept":"SO4-1-u3-C2","difficulty":1,"kind":"mc","stem":"사람마다 합리적 선택이 다를 수 있는 까닭은 무엇인가요?","options":[{"t":"중요하게 여기는 것이 다르기 때문이에요","correct":true},{"t":"한 사람은 꼭 잘못 고르기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"합리적 선택은 하나뿐이기 때문이에요","mis":"SO4-1-u3-X08"},{"t":"비싼 것이 늘 정답이기 때문이에요","mis":"SO4-1-u3-X06"}],"explanation":["사람마다 달라요.","중요한 것이 달라요.","선택도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#3','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C3',1,'mc','auto','합리적 선택의 차례에서 정보를 찾은 다음에 할 일은 무엇인가요?',ARRAY['SO4-1-u3-X11','SO4-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO4-1-u3-C3","difficulty":1,"kind":"mc","stem":"합리적 선택의 차례에서 정보를 찾은 다음에 할 일은 무엇인가요?","options":[{"t":"가격과 품질을 견줘요","correct":true},{"t":"필요한지 생각해요","mis":"SO4-1-u3-X11"},{"t":"고르지 않고 끝내요","mis":"SO4-1-u3-X11"},{"t":"광고를 그대로 따라요","mis":"SO4-1-u3-X10"}],"explanation":["필요한지 생각했어요.","정보를 찾았어요.","이제 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#4','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C4',1,'mc','auto','서비스 기준에서 살펴볼 점은 무엇인가요?',ARRAY['SO4-1-u3-X14']::text[],false,'{"seq":4,"concept":"SO4-1-u3-C4","difficulty":1,"kind":"mc","stem":"서비스 기준에서 살펴볼 점은 무엇인가요?","options":[{"t":"무상 수리 기간과 배송","correct":true},{"t":"모양과 색","mis":"SO4-1-u3-X14"},{"t":"튼튼한지","mis":"SO4-1-u3-X14"},{"t":"친환경 소재인지","mis":"SO4-1-u3-X14"}],"explanation":["서비스예요.","고쳐 주고 배달해 줘요.","무상 수리와 배송이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#5','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C7',1,'mc','auto','장터 같은 시장의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X24']::text[],false,'{"seq":5,"concept":"SO4-1-u3-C7","difficulty":1,"kind":"mc","stem":"장터 같은 시장의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"생산과 소비를 한곳에서 함께 볼 수 있어요","correct":true},{"t":"소비만 일어나요","mis":"SO4-1-u3-X24"},{"t":"생산만 일어나요","mis":"SO4-1-u3-X24"},{"t":"생산과 소비가 따로 떨어져 일어나요","mis":"SO4-1-u3-X24"}],"explanation":["파는 사람이 있어요.","사는 사람도 있어요.","함께 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#6','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C8',1,'mc','auto','만드는 생산 활동이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u3-X25']::text[],false,'{"seq":6,"concept":"SO4-1-u3-C8","difficulty":1,"kind":"mc","stem":"만드는 생산 활동이 아닌 것은 무엇인가요?","options":[{"t":"바다에서 조개 캐기","correct":true},{"t":"옷 만들기","mis":"SO4-1-u3-X25"},{"t":"빵 굽기","mis":"SO4-1-u3-X25"},{"t":"집 짓기","mis":"SO4-1-u3-X25"}],"explanation":["만들어 내나요?","조개는 캐요.","자연에서 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#7','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C9',1,'mc','auto','일지 ⑤에서 갯벌군에 부족한 쌀을 채워 줄 수 있는 지역은 어디인가요?',ARRAY['SO4-1-u3-X27','SO4-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u3-C9","difficulty":1,"kind":"mc","stem":"일지 ⑤에서 갯벌군에 부족한 쌀을 채워 줄 수 있는 지역은 어디인가요?","options":[{"t":"푸른내시","correct":true},{"t":"갯벌군 혼자서","mis":"SO4-1-u3-X27"},{"t":"산마루군 — 사과가 나서","mis":"SO4-1-u3-X26"},{"t":"채울 수 있는 곳이 없어요","mis":"SO4-1-u3-X27"}],"explanation":["갯벌군은 쌀이 부족해요.","쌀이 많이 나는 곳이에요.","푸른내시예요."],"asset":{"type":"passage","lines":["푸른내시 — 넓은 강과 들이 있어 쌀이 많이 나지만, 바다가 없다.","갯벌군 — 갯벌이 넓어 조개와 생선이 많이 나지만, 쌀이 부족하다.","산마루군 — 산비탈에 과수원이 많아 사과가 잘 난다."],"title":"일지 ⑤ — 세 지역 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#8','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C10',1,'mc','auto','일지 ⑥의 ㉱는 어떤 교류인가요?',ARRAY['SO4-1-u3-X30','SO4-1-u3-X29']::text[],false,'{"seq":8,"concept":"SO4-1-u3-C10","difficulty":1,"kind":"mc","stem":"일지 ⑥의 ㉱는 어떤 교류인가요?","options":[{"t":"문화 교류","correct":true},{"t":"물자 교류","mis":"SO4-1-u3-X30"},{"t":"기술 교류","mis":"SO4-1-u3-X30"},{"t":"교류가 아닌 일","mis":"SO4-1-u3-X29"}],"explanation":["함께 축제를 열어요.","즐거움을 나눠요.","문화 교류예요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#9','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C1',2,'mc','auto','선택의 문제가 생기지 않는 것은 무엇인가요?',ARRAY['SO4-1-u3-X05']::text[],false,'{"seq":9,"concept":"SO4-1-u3-C1","difficulty":2,"kind":"mc","stem":"선택의 문제가 생기지 않는 것은 무엇인가요?","options":[{"t":"누구나 넉넉하게 마실 수 있는 공기","correct":true},{"t":"한 대뿐인 교실 컴퓨터","mis":"SO4-1-u3-X05"},{"t":"정해진 용돈","mis":"SO4-1-u3-X05"},{"t":"짧은 쉬는 시간","mis":"SO4-1-u3-X05"}],"explanation":["부족한 것을 찾아요.","공기는 넉넉해요.","고를 필요가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#10','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C2',2,'mc','auto','아직 쓸 만한 가방의 끈 하나만 끊어졌어요. 비용과 만족을 견주면 가장 알맞은 선택은 무엇인가요?',ARRAY['SO4-1-u3-X06','SO4-1-u3-X07','SO4-1-u3-X04']::text[],false,'{"seq":10,"concept":"SO4-1-u3-C2","difficulty":2,"kind":"mc","stem":"아직 쓸 만한 가방의 끈 하나만 끊어졌어요. 비용과 만족을 견주면 가장 알맞은 선택은 무엇인가요?","options":[{"t":"끈만 고쳐 써요","correct":true},{"t":"새 가방을 바로 사요 — 새것이 언제나 좋아서","mis":"SO4-1-u3-X06"},{"t":"아무 중고 가방이나 사요 — 싸서","mis":"SO4-1-u3-X07"},{"t":"가방 없이 다녀요","mis":"SO4-1-u3-X04"}],"explanation":["끈 하나뿐이에요.","고치면 돼요.","비용은 적고 만족은 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#11','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C5',2,'mc','auto','일지 ③과 같은 운동화로 다른 친구가 점수표를 만들면 결과는 어떻게 될까요?',ARRAY['SO4-1-u3-X19','SO4-1-u3-X08']::text[],false,'{"seq":11,"concept":"SO4-1-u3-C5","difficulty":2,"kind":"mc","stem":"일지 ③과 같은 운동화로 다른 친구가 점수표를 만들면 결과는 어떻게 될까요?","options":[{"t":"친구의 판단과 우선순위에 따라 달라질 수 있어요","correct":true},{"t":"하람이와 꼭 같아요","mis":"SO4-1-u3-X19"},{"t":"친구 것이 정답이에요","mis":"SO4-1-u3-X08"},{"t":"하람이 것이 정답이에요","mis":"SO4-1-u3-X08"}],"explanation":["점수는 저마다 매겨요.","우선순위도 달라요.","결과도 달라요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#12','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C4',2,'mc','auto','「아껴 써야지!」인 친구와 「안전이 제일!」인 친구가 서로 다른 자전거를 골랐어요. 알맞은 생각은 무엇인가요?',ARRAY['SO4-1-u3-X08','SO4-1-u3-X15','SO4-1-u3-X06']::text[],false,'{"seq":12,"concept":"SO4-1-u3-C4","difficulty":2,"kind":"mc","stem":"「아껴 써야지!」인 친구와 「안전이 제일!」인 친구가 서로 다른 자전거를 골랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"우선순위가 달라 둘 다 합리적 선택일 수 있어요","correct":true},{"t":"한 친구는 잘못 골랐어요","mis":"SO4-1-u3-X08"},{"t":"기준은 하나만 봐야 해요","mis":"SO4-1-u3-X15"},{"t":"비싼 것을 고른 친구가 맞아요","mis":"SO4-1-u3-X06"}],"explanation":["아끼기는 가격이에요.","안전은 품질이에요.","둘 다 따져 봤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#13','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C7',2,'mc','auto','일지 ④에서 소비를 하는 사람은 누구인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X22']::text[],false,'{"seq":13,"concept":"SO4-1-u3-C7","difficulty":2,"kind":"mc","stem":"일지 ④에서 소비를 하는 사람은 누구인가요?","options":[{"t":"김치를 사는 손님","correct":true},{"t":"무를 기르는 농부","mis":"SO4-1-u3-X23"},{"t":"김치를 담가 파는 할머니","mis":"SO4-1-u3-X23"},{"t":"마술 공연을 하는 사람","mis":"SO4-1-u3-X22"}],"explanation":["사는 사람을 찾아요.","손님이에요.","소비예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#14','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C9',2,'mc','auto','세 지역이 서로 의지하며 함께 살아가는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u3-X33','SO4-1-u3-X27']::text[],false,'{"seq":14,"concept":"SO4-1-u3-C9","difficulty":2,"kind":"mc","stem":"세 지역이 서로 의지하며 함께 살아가는 것을 무엇이라고 하나요?","options":[{"t":"상호 의존","correct":true},{"t":"고립","mis":"SO4-1-u3-X33"},{"t":"한쪽 의존","mis":"SO4-1-u3-X33"},{"t":"희소성","mis":"SO4-1-u3-X27"}],"explanation":["서로예요.","의지해요.","상호 의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#15','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C10',2,'mc','auto','일지 ⑥의 여러 교류로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u3-X29','SO4-1-u3-X28']::text[],false,'{"seq":15,"concept":"SO4-1-u3-C10","difficulty":2,"kind":"mc","stem":"일지 ⑥의 여러 교류로 알 수 있는 것은 무엇인가요?","options":[{"t":"세 지역은 물자·기술·문화·봉사로 밀접하게 이어져 있어요","correct":true},{"t":"세 지역은 서로 관계없어요","mis":"SO4-1-u3-X29"},{"t":"교류는 물건뿐이에요","mis":"SO4-1-u3-X29"},{"t":"한 지역만 주고 나머지는 받기만 해요","mis":"SO4-1-u3-X28"}],"explanation":["여러 가지를 주고받아요.","돕기도 해요.","밀접하게 이어져요."],"asset":{"type":"passage","lines":["㉮ 푸른내시의 쌀을 갯벌군으로 보낸다.","㉯ 갯벌군의 조개가 푸른내시 시장에 온다.","㉰ 산마루군 농부가 푸른내시 농부에게 사과 기르는 법을 알려 준다.","㉱ 푸른내시와 산마루군이 함께 강변 축제를 연다.","㉲ 홍수가 난 갯벌군에 푸른내시 봉사단이 가서 돕는다."],"title":"일지 ⑥ — 세 지역의 교류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#16','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C11',2,'mc','auto','일지 ⑦의 가운데에 푸른내시를 둔 까닭은 무엇인가요?',ARRAY['SO4-1-u3-X31']::text[],false,'{"seq":16,"concept":"SO4-1-u3-C11","difficulty":2,"kind":"mc","stem":"일지 ⑦의 가운데에 푸른내시를 둔 까닭은 무엇인가요?","options":[{"t":"푸른내시를 중심으로 교류를 나타낸 지도이기 때문이에요","correct":true},{"t":"가장 큰 도시이기 때문이에요","mis":"SO4-1-u3-X31"},{"t":"가장 먼 지역이기 때문이에요","mis":"SO4-1-u3-X31"},{"t":"아무 데나 둔 것이에요","mis":"SO4-1-u3-X31"}],"explanation":["누구의 교류 지도인가요?","푸른내시예요.","가운데에 둬요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#17','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C5',3,'mc','auto','일지 ③에서 품질을 빼고 디자인과 가격 점수만 더하면 어느 운동화를 고르게 되나요?',ARRAY['SO4-1-u3-X17','SO4-1-u3-X15']::text[],false,'{"seq":17,"concept":"SO4-1-u3-C5","difficulty":3,"kind":"mc","stem":"일지 ③에서 품질을 빼고 디자인과 가격 점수만 더하면 어느 운동화를 고르게 되나요?","options":[{"t":"㉮ — 12점","correct":true},{"t":"㉰ — 가격이 8점이라서","mis":"SO4-1-u3-X17"},{"t":"㉯ — 품질이 10점이라서","mis":"SO4-1-u3-X17"},{"t":"셋 모두 같아요","mis":"SO4-1-u3-X15"}],"explanation":["㉮ 6 + 6 = 12예요.","㉯ 7점, ㉰ 11점이에요.","㉮예요."],"asset":{"type":"passage","lines":["기준과 최대 점수 — 품질 10점 · 가격 8점 · 디자인 6점","운동화 ㉮ — 품질 8점 · 가격 6점 · 디자인 6점","운동화 ㉯ — 품질 10점 · 가격 3점 · 디자인 4점","운동화 ㉰ — 품질 6점 · 가격 8점 · 디자인 3점"],"title":"일지 ③ — 하람이의 운동화 점수표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#18','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C6',3,'mc','auto','「급식실 줄이 길어 기다리기 힘들어요」라는 불편을 바탕으로 한 새 상품 제안으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X21','SO4-1-u3-X10']::text[],false,'{"seq":18,"concept":"SO4-1-u3-C6","difficulty":3,"kind":"mc","stem":"「급식실 줄이 길어 기다리기 힘들어요」라는 불편을 바탕으로 한 새 상품 제안으로 알맞은 것은 무엇인가요?","options":[{"t":"차례가 되면 알려 주는 번호표 기계","correct":true},{"t":"반짝이는 새 식판","mis":"SO4-1-u3-X21"},{"t":"불편과 관계없는 장난감","mis":"SO4-1-u3-X21"},{"t":"광고에서 본 과자","mis":"SO4-1-u3-X10"}],"explanation":["무엇이 불편한가요?","기다리기예요.","그것을 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#19','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C8',3,'mc','auto','일지 ④에서 서로 다른 종류의 생산 활동을 하나씩 골라 묶은 것은 무엇인가요?',ARRAY['SO4-1-u3-X23','SO4-1-u3-X25']::text[],false,'{"seq":19,"concept":"SO4-1-u3-C8","difficulty":3,"kind":"mc","stem":"일지 ④에서 서로 다른 종류의 생산 활동을 하나씩 골라 묶은 것은 무엇인가요?","options":[{"t":"㉮ · ㉯ · ㉱","correct":true},{"t":"㉮ · ㉯ · ㉰","mis":"SO4-1-u3-X23"},{"t":"㉯ · ㉱ · ㉲","mis":"SO4-1-u3-X25"},{"t":"㉮ · ㉰ · ㉲","mis":"SO4-1-u3-X23"}],"explanation":["자연에서 얻기는 ㉮예요.","만들기는 ㉯예요.","해 주기는 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 농부가 밭에서 무를 기른다.","㉯ 할머니가 그 무로 김치를 담가 판다.","㉰ 손님이 김치를 산다.","㉱ 버스 기사가 손님을 장터까지 태워 준다.","㉲ 장터 무대에서 마술 공연을 한다."],"title":"일지 ④ — 푸른내시 장터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#20','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C11',3,'mc','auto','일지 ⑦에 「갯벌군 어민들이 푸른내시 학교에 와서 갯벌 이야기 공연을 한다」를 더하려면 어떻게 나타내야 하나요?',ARRAY['SO4-1-u3-X32','SO4-1-u3-X30']::text[],false,'{"seq":20,"concept":"SO4-1-u3-C11","difficulty":3,"kind":"mc","stem":"일지 ⑦에 「갯벌군 어민들이 푸른내시 학교에 와서 갯벌 이야기 공연을 한다」를 더하려면 어떻게 나타내야 하나요?","options":[{"t":"갯벌군에서 푸른내시로 노란 화살표 — 문화 교류","correct":true},{"t":"푸른내시에서 갯벌군으로 파란 화살표 — 문화 교류","mis":"SO4-1-u3-X32"},{"t":"갯벌군에서 푸른내시로 노란 화살표 — 물자 교류","mis":"SO4-1-u3-X30"},{"t":"푸른내시에서 갯벌군으로 노란 화살표 — 기술 교류","mis":"SO4-1-u3-X32"}],"explanation":["갯벌군에서 와요.","들어오는 교류예요.","공연은 문화예요."],"asset":{"type":"passage","lines":["가운데 — 푸른내시","노란 화살표 — 갯벌군 → 푸른내시 : 조개","노란 화살표 — 산마루군 → 푸른내시 : 사과 기르는 기술","파란 화살표 — 푸른내시 → 갯벌군 : 쌀","파란 화살표 — 푸른내시 → 산마루군 : 강변 축제 공연단"],"title":"일지 ⑦ — 푸른내시 교류 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#21','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C12',3,'mc','auto','자매결연을 맺을 지역을 고르는 기준으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u3-X34']::text[],false,'{"seq":21,"concept":"SO4-1-u3-C12","difficulty":3,"kind":"mc","stem":"자매결연을 맺을 지역을 고르는 기준으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 강점이 필요하거나 우리 부족함을 채워 줄 수 있는 지역","correct":true},{"t":"이름이 가장 유명한 지역","mis":"SO4-1-u3-X34"},{"t":"우리와 똑같은 것만 나는 지역","mis":"SO4-1-u3-X34"},{"t":"아무 지역이나","mis":"SO4-1-u3-X34"}],"explanation":["주고받을 것이 있나요?","서로 채워 주나요?","그런 지역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#22','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C4',3,'mc','auto','새 물건을 사기 전에 확인할 것을 바르게 모은 것은 무엇인가요?',ARRAY['SO4-1-u3-X13','SO4-1-u3-X06']::text[],false,'{"seq":22,"concept":"SO4-1-u3-C4","difficulty":3,"kind":"mc","stem":"새 물건을 사기 전에 확인할 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"꼭 필요한지 · 이미 있거나 빌려 쓸 수 있는지 · 가진 돈으로 살 수 있는지","correct":true},{"t":"색이 예쁜지 · 친구도 샀는지 · 광고에 나왔는지","mis":"SO4-1-u3-X13"},{"t":"가장 비싼지 · 가장 새것인지 · 가장 큰지","mis":"SO4-1-u3-X06"},{"t":"아무것도 확인하지 않아도 돼요","mis":"SO4-1-u3-X13"}],"explanation":["필요한가요?","이미 있나요?","살 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#23','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C4',4,'mc','auto','하람이는 가격을 중요하게 여기지만 오래 쓸 튼튼한 필통이 필요해요. 일지 ②를 보고 가장 알맞은 선택은 무엇인가요?',ARRAY['SO4-1-u3-X10','SO4-1-u3-X06','SO4-1-u3-X11']::text[],false,'{"seq":23,"concept":"SO4-1-u3-C4","difficulty":4,"kind":"mc","stem":"하람이는 가격을 중요하게 여기지만 오래 쓸 튼튼한 필통이 필요해요. 일지 ②를 보고 가장 알맞은 선택은 무엇인가요?","options":[{"t":"㉮가 튼튼하다고 한 그 필통을 값이 싼 가게 ②에서 사요","correct":true},{"t":"㉱ 광고의 필통을 바로 사요","mis":"SO4-1-u3-X10"},{"t":"가게 ①에서 사요 — 비쌀수록 좋아서","mis":"SO4-1-u3-X06"},{"t":"정보 없이 처음 본 필통을 사요","mis":"SO4-1-u3-X11"}],"explanation":["튼튼한 필통이에요.","값은 가게 ②가 싸요.","두 가지를 함께 따져요."],"asset":{"type":"passage","lines":["㉮ 써 본 언니 — 「이 필통 1년 썼는데 지퍼가 튼튼해.」","㉯ 가격 비교 누리집 — 같은 필통이 가게 ① 6,000원 · 가게 ② 5,500원","㉰ 가게에 가서 직접 열고 닫아 보니 칸이 넉넉했다.","㉱ 광고 — 「이 필통만 쓰면 시험이 무조건 쉬워진다!」"],"title":"일지 ② — 필통 정보 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#24','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C11',4,'mc','auto','다른 반 친구가 만든 푸른내시 교류 지도에는 화살표가 하나 더 있었어요. 알맞은 생각은 무엇인가요?',ARRAY['SO4-1-u3-X31','SO4-1-u3-X32','SO4-1-u3-X29']::text[],false,'{"seq":24,"concept":"SO4-1-u3-C11","difficulty":4,"kind":"mc","stem":"다른 반 친구가 만든 푸른내시 교류 지도에는 화살표가 하나 더 있었어요. 알맞은 생각은 무엇인가요?","options":[{"t":"조사한 사례가 달라 교류 지도는 만드는 사람마다 조금씩 다를 수 있어요","correct":true},{"t":"둘 가운데 하나는 반드시 잘못 그렸어요","mis":"SO4-1-u3-X31"},{"t":"화살표 색은 아무렇게나 칠해도 돼요","mis":"SO4-1-u3-X32"},{"t":"교류는 하나만 있어야 해요","mis":"SO4-1-u3-X29"}],"explanation":["조사가 달라요.","지도도 달라요.","다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u3_review_d#25','soc',4,1,'u3','','g4_1_soc_u3_review_d','unit_review','SO4-1-u3-C1',4,'mc','auto','푸른내시 장터에 그날 아침 딱 열 개만 만든 떡이 나왔는데 사려는 사람이 아주 많아요. 이 떡을 알맞게 말한 것은 무엇인가요?',ARRAY['SO4-1-u3-X02','SO4-1-u3-X03']::text[],false,'{"seq":25,"concept":"SO4-1-u3-C1","difficulty":4,"kind":"mc","stem":"푸른내시 장터에 그날 아침 딱 열 개만 만든 떡이 나왔는데 사려는 사람이 아주 많아요. 이 떡을 알맞게 말한 것은 무엇인가요?","options":[{"t":"원하는 사람에 비해 양이 적어 희소성이 커요","correct":true},{"t":"양이 적으니 아무도 원하지 않아요","mis":"SO4-1-u3-X02"},{"t":"원하는 사람이 많으면 희소성이 작아져요","mis":"SO4-1-u3-X02"},{"t":"떡은 선택의 문제와 관계없어요","mis":"SO4-1-u3-X03"}],"explanation":["열 개뿐이에요.","원하는 사람은 많아요.","희소성이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
